def handle_condition(self, tok, indices):
    """
    Handle a DRS condition

    :param indices: list of int
    :return: list of ``DrtExpression``
    """
    if tok == 'not':
        return [self._handle_not()]

    if tok == 'or':
        conds = [self._handle_binary_expression(self._make_or_expression)]
    elif tok == 'imp':
        conds = [self._handle_binary_expression(self._make_imp_expression)]
    elif tok == 'eq':
        conds = [self._handle_eq()]
    elif tok == 'prop':
        conds = [self._handle_prop()]

    elif tok == 'pred':
        conds = [self._handle_pred()]
    elif tok == 'named':
        conds = [self._handle_named()]
    elif tok == 'rel':
        conds = [self._handle_rel()]
    elif tok == 'timex':
        conds = self._handle_timex()
    elif tok == 'card':
        conds = [self._handle_card()]

    elif tok == 'whq':
        conds = [self._handle_whq()]

    else:
        conds = []

    return sum([[cond(sent_index, word_indices) for cond in conds] for sent_index, word_indices in self._sent_and_word_indices(indices)], [])

def lookup_unique(self, rel, node, depgraph):
    """
    Lookup 'key'. There should be exactly one item in the associated relation.
    """
    deps = [
        depgraph.nodes[dep]
        for dep in sum(list(node['deps'].values()), [])
        if depgraph.nodes[dep]['rel'].lower() == rel.lower()
    ]

    if len(deps) == 0:
        raise KeyError("'%s' doesn't contain a feature '%s'" % (node['word'], rel))
    elif len(deps) > 1:
        raise KeyError("'%s' should only have one feature '%s'" % (node['word'], rel))
    else:
        return deps[0]

def _divide_to_tokensequences(self, text):
    "Divides the text into pseudosentences of fixed size"
    w = self.w
    wrdindex_list = []
    matches = re.finditer("\w+", text)
    for match in matches:
        wrdindex_list.append((match.group(), match.start()))
    return [TokenSequence(i/w, wrdindex_list[i:i+w])
            for i in range(0, len(wrdindex_list), w)]

def output_args(self):
    self._remap_metadata()
    lavcopts = {'vcodec': self.codec}
    if self.bitrate > 0:
        lavcopts.update(vbitrate=self.bitrate)
    args = ['-o', self.outfile, '-ovc', 'lavc', '-lavcopts',
            ':'.join(itertools.starmap('{0}={1}'.format,
                                       lavcopts.items()))]
    if self.extra_args:
        args.extend(self.extra_args)
    if self.metadata:
        args.extend(['-info', ':'.join('%s=%s' % (k, v)
                     for k, v in six.iteritems(self.metadata)
                     if k in self.allowed_metadata)])
    return args

def findobj(self, match=None):
    """
    Recursively find all :class:`matplotlib.artist.Artist`
    instances contained in *self*.

    If *match* is not None, it can be

      - function with signature ``boolean = match(artist)``

      - class instance: e.g., :class:`~matplotlib.lines.Line2D`

    used to filter matches.
    """
    if match is None:  # always return True
        def matchfunc(x):
            return True
    elif issubclass(match, Artist):
        def matchfunc(x):
            return isinstance(x, match)
    elif six.callable(match):
        matchfunc = func
    else:
        raise ValueError('match must be None, an '
                         'matplotlib.artist.Artist '
                         'subclass, or a callable')

    artists = []

    for c in self.get_children():
        if matchfunc(c):
            artists.append(c)
        artists.extend([thisc
                        for thisc
                        in c.findobj(matchfunc)
                        if matchfunc(thisc)])

    if matchfunc(self):
        artists.append(self)
    return artists

def _make_paths(self, segs, kinds):
    if kinds is not None:
        return [mpath.Path(seg, codes=kind)
                for seg, kind in zip(segs, kinds)]
    else:
        return [mpath.Path(seg) for seg in segs]

