            verbosity=verbosity,
            stream=stream,
            resultclass=resultclass,
        ).run(suite)
        runner.teardown_databases(old_config)

        if six.PY2:
            stream.buflist = [force_text(x) for x in stream.buflist]
        return stream.getvalue()

    def test_output_normal(self):
