def test_error_line_number_module(self):
    loader = DictLoader({
        "base.html": "{% module Template('sub.html') %}",
        "sub.html": "{{1/0}}",
    }, namespace={"_tt_modules": ObjectDict({"Template": lambda path, **kwargs: loader.load(path).generate(**kwargs)})})
    try:
        loader.load("base.html").generate()
        self.fail("did not get expected exception")
    except ZeroDivisionError:
        exc_stack = traceback.format_exc()
        self.assertTrue('# base.html:1' in exc_stack)
        self.assertTrue('# sub.html:1' in exc_stack)

def _timeit(self, kernel, recopy):
    min_time = 1e99
    if not recopy:
        kernel(self.m, self.i, self.j, self.v)

    number = 1
    start = time.time()
    while time.time() - start < 0.1:
        if recopy:
            m = self.m.copy()
        else:
            m = self.m
        while True:
            duration = timeit.timeit(lambda: kernel(m, self.i, self.j, self.v),
                                     number=number)
            if duration > 1e-5:
                break
            else:
                number *= 10
        min_time = min(min_time, duration/number)
    return min_time

def _select_function(sort, typ):
    if typ in ['F','D']:
        if callable(sort):
            # assume the user knows what they're doing
            sfunction = sort
        elif sort == 'lhp':
            sfunction = lambda x,y: (np.real(x/y) < 0.0)
        elif sort == 'rhp':
            sfunction = lambda x,y: (np.real(x/y) >= 0.0)
        elif sort == 'iuc':
            sfunction = lambda x,y: (abs(x/y) <= 1.0)
        elif sort == 'ouc':
            sfunction = lambda x,y: (abs(x/y) > 1.0)
        else:
            raise ValueError("sort parameter must be None, a callable, or "
                "one of ('lhp','rhp','iuc','ouc')")
    elif typ in ['f','d']:
        if callable(sort):
            # assume the user knows what they're doing
            sfunction = sort
        elif sort == 'lhp':
            sfunction = lambda x,y,z: (np.real((x+y*1j)/z) < 0.0)
        elif sort == 'rhp':
            sfunction = lambda x,y,z: (np.real((x+y*1j)/z) >= 0.0)
        elif sort == 'iuc':
            sfunction = lambda x,y,z: (abs((x+y*1j)/z) <= 1.0)
        elif sort == 'ouc':
            sfunction = lambda x,y,z: (abs((x+y*1j)/z) > 1.0)
        else:
            raise ValueError("sort parameter must be None, a callable, or "
                "one of ('lhp','rhp','iuc','ouc')")
    else:  # to avoid an error later
        raise ValueError("dtype %s not understood" % typ)
    return sfunction

