def _logpdf(self, x, c):
    return _lazywhere((x == x) & (c != 0), (x, c),
        lambda x, c: -special.xlog1py(c+1., c*x) / c,
        -x)

def _munp(self, n, a):
    return _lazywhere(
        a > n + 1, (a, n),
        lambda a, n: special.zeta(a - n, 1) / special.zeta(a, 1),
        np.inf)

def _cdf(self, x, a):
    k = floor(x)
    f = lambda k, a: 1.0 - exp(-a * k) / (exp(a) + 1)
    f2 = lambda k, a: exp(a * (k+1)) / (exp(a) + 1)
    return _lazywhere(k >= 0, (k, a), f=f, f2=f2)

def _get_octal_mode_from_symbolic_perms(self, path_stat, user, perms):
    prev_mode = stat.S_IMODE(path_stat.st_mode)

    is_directory = stat.S_ISDIR(path_stat.st_mode)
    has_x_permissions = (prev_mode & 00111) > 0
    apply_X_permission = is_directory or has_x_permissions

    # Permission bits constants documented at:
    # http://docs.python.org/2/library/stat.html#stat.S_ISUID
    if apply_X_permission:
        X_perms = {
            'u': {'X': stat.S_IXUSR},
            'g': {'X': stat.S_IXGRP},
            'o': {'X': stat.S_IXOTH}
        }
    else:
        X_perms = {
            'u': {'X': 0},
            'g': {'X': 0},
            'o': {'X': 0}
        }

    user_perms_to_modes = {
        'u': {
            'r': stat.S_IRUSR,
            'w': stat.S_IWUSR,
            'x': stat.S_IXUSR,
            's': stat.S_ISUID,
            't': 0,
            'u': prev_mode & stat.S_IRWXU,
            'g': (prev_mode & stat.S_IRWXG) << 3,
            'o': (prev_mode & stat.S_IRWXO) << 6 },
        'g': {
            'r': stat.S_IRGRP,
            'w': stat.S_IWGRP,
            'x': stat.S_IXGRP,
            's': stat.S_ISGID,
            't': 0,
            'u': (prev_mode & stat.S_IRWXU) >> 3,
            'g': prev_mode & stat.S_IRWXG,
            'o': (prev_mode & stat.S_IRWXO) << 3 },
        'o': {
            'r': stat.S_IROTH,
            'w': stat.S_IWOTH,
            'x': stat.S_IXOTH,
            's': 0,
            't': stat.S_ISVTX,
            'u': (prev_mode & stat.S_IRWXU) >> 6,
            'g': (prev_mode & stat.S_IRWXG) >> 3,
            'o': prev_mode & stat.S_IRWXO }
    }

    # Insert X_perms into user_perms_to_modes
    for key, value in X_perms.items():
        user_perms_to_modes[key].update(value)

    or_reduce = lambda mode, perm: mode | user_perms_to_modes[user][perm]
    return reduce(or_reduce, perms, 0)

def build_put_params(self, params, name, value=None, timestamp=None,
                     unit=None, dimensions=None, statistics=None):
    args = (name, value, unit, dimensions, statistics, timestamp)
    length = max(map(lambda a: len(a) if isinstance(a, list) else 1, args))

    def aslist(a):
        if isinstance(a, list):
            if len(a) != length:
                raise Exception('Must specify equal number of elements; expected %d.' % length)
            return a
        return [a] * length

    for index, (n, v, u, d, s, t) in enumerate(zip(*map(aslist, args))):
        metric_data = {'MetricName': n}

        if timestamp:
            metric_data['Timestamp'] = t.isoformat()

        if unit:
            metric_data['Unit'] = u

        if dimensions:
            self.build_dimension_param(d, metric_data)

        if statistics:
            metric_data['StatisticValues.Maximum'] = s['maximum']
            metric_data['StatisticValues.Minimum'] = s['minimum']
            metric_data['StatisticValues.SampleCount'] = s['samplecount']
            metric_data['StatisticValues.Sum'] = s['sum']
            if value is not None:
                msg = 'You supplied a value and statistics for a ' + \
                      'metric.Posting statistics and not value.'
                boto.log.warn(msg)
        elif value is not None:
            metric_data['Value'] = v
        else:
            raise Exception('Must specify a value or statistics to put.')

        for key, val in six.iteritems(metric_data):
            params['MetricData.member.%d.%s' % (index + 1, key)] = val

def requires(*args, **kw):
    hasgroup = lambda group: all(key in kw for key in group)
    if 1 != len(list(filter(hasgroup, groups))):
        message = ' OR '.join(['+'.join(g) for g in groups])
        message = "{0} requires {1} argument(s)" \
                  "".format(func.action, message)
        raise KeyError(message)
    return func(*args, **kw)

def wrapper(*args, **kw):
    hasgroup = lambda group: all(key in kw for key in group)
    if field in kw and not any(hasgroup(g) for g in groups):
        message = ' OR '.join(['+'.join(g) for g in groups])
        message = "{0} argument {1} requires {2}" \
                  "".format(func.action, field, message)
        raise KeyError(message)
    return func(*args, **kw)

def __repr__(self):
    render = lambda pair: '{0!s}: {1!r}'.format(*pair)
    do_show = lambda pair: not pair[0].startswith('_')
    attrs = filter(do_show, self.__dict__.items())
    name = self.__class__.__name__
    if name.startswith('JIT_'):
        name = '^{0}^'.format(self._name or '')
    return '{0}{1!r}({2})'.format(
        name, self.copy(), ', '.join(map(render, attrs)))

def init_gui_pylab(self):
    """Enable GUI event loop integration, taking pylab into account."""
    enable = False
    shell = self.shell
    if self.pylab:
        enable = lambda key: shell.enable_pylab(key, import_all=self.pylab_import_all)
        key = self.pylab
    elif self.matplotlib:
        enable = shell.enable_matplotlib
        key = self.matplotlib
    elif self.gui:
        enable = shell.enable_gui
        key = self.gui

    if not enable:
        return

    try:
        r = enable(key)
    except ImportError:
        self.log.warn("Eventloop or matplotlib integration failed. Is matplotlib installed?")
        self.shell.showtraceback()
        return
    except Exception:
        self.log.warn("GUI event loop or pylab initialization failed")
        self.shell.showtraceback()
        return

    if isinstance(r, tuple):
        gui, backend = r[:2]
        self.log.info("Enabling GUI event loop integration, "
                  "eventloop=%s, matplotlib=%s", gui, backend)
        if key == "auto":
            print("Using matplotlib backend: %s" % backend)
    else:
        gui = r
        self.log.info("Enabling GUI event loop integration, "
                  "eventloop=%s", gui)

def rehashx(self, parameter_s=''):
    """Update the alias table with all executable files in $PATH.

    This version explicitly checks that every entry in $PATH is a file
    with execute access (os.X_OK), so it is much slower than %rehash.

    Under Windows, it checks executability as a match against a
    '|'-separated string of extensions, stored in the IPython config
    variable win_exec_ext.  This defaults to 'exe|com|bat'.

    This function also resets the root module cache of module completer,
    used on slow filesystems.
    """
    from IPython.core.alias import InvalidAliasError

    # for the benefit of module completer in ipy_completers.py
    del self.shell.db['rootmodules_cache']

    path = [os.path.abspath(os.path.expanduser(p)) for p in
        os.environ.get('PATH','').split(os.pathsep)]

    syscmdlist = []
    # Now define isexec in a cross platform manner.
    if os.name == 'posix':
        isexec = lambda fname:os.path.isfile(fname) and \
                 os.access(fname,os.X_OK)
    else:
        try:
            winext = os.environ['pathext'].replace(';','|').replace('.','')
        except KeyError:
            winext = 'exe|com|bat|py'
        if 'py' not in winext:
            winext += '|py'
        execre = re.compile(r'(.*)\.(%s)$' % winext,re.IGNORECASE)
        isexec = lambda fname:os.path.isfile(fname) and execre.match(fname)
    savedir = py3compat.getcwd()

    # Now walk the paths looking for executables to alias.
    try:
        # write the whole loop for posix/Windows so we don't have an if in
        # the innermost part
        if os.name == 'posix':
            for pdir in path:
                try:
                    os.chdir(pdir)
                    dirlist = os.listdir(pdir)
                except OSError:
                    continue
                for ff in dirlist:
                    if isexec(ff):
                        try:
                            # Removes dots from the name since ipython
                            # will assume names with dots to be python.
                            if not self.shell.alias_manager.is_alias(ff):
                                self.shell.alias_manager.define_alias(
                                    ff.replace('.',''), ff)
                        except InvalidAliasError:
                            pass
                        else:
                            syscmdlist.append(ff)
        else:
            no_alias = Alias.blacklist
            for pdir in path:
                try:
                    os.chdir(pdir)
                    dirlist = os.listdir(pdir)
                except OSError:
                    continue
                for ff in dirlist:
                    base, ext = os.path.splitext(ff)
                    if isexec(ff) and base.lower() not in no_alias:
                        if ext.lower() == '.exe':
                            ff = base
                            try:
                                # Removes dots from the name since ipython
                                # will assume names with dots to be python.
                                self.shell.alias_manager.define_alias(
                                    base.lower().replace('.',''), ff)
                            except InvalidAliasError:
                                pass
                            syscmdlist.append(ff)
        self.shell.db['syscmdlist'] = syscmdlist
    finally:
        os.chdir(savedir)

