            yield ''
            yield ''
            yield 'class %s(models.Model):' % table2model(table_name)
            known_models.append(table2model(table_name))
            try:
                relations = connection.introspection.get_relations(cursor, table_name)
            except NotImplementedError:
                relations = {}
            try:
                indexes = connection.introspection.get_indexes(cursor, table_name)
            except NotImplementedError:
                indexes = {}
            try:
                constraints = connection.introspection.get_constraints(cursor, table_name)
            except NotImplementedError:
                constraints = {}
            used_column_names = []  # Holds column names used in the table so far
            for row in connection.introspection.get_table_description(cursor, table_name):
                comment_notes = []  # Holds Field notes, to be displayed in a Python comment.
                extra_params = OrderedDict()  # Holds Field parameters such as 'db_column'.
                column_name = row[0]
                is_relation = column_name in relations

                att_name, params, notes = self.normalize_col_name(
                    column_name, used_column_names, is_relation)
                extra_params.update(params)
                comment_notes.extend(notes)

                used_column_names.append(att_name)

                # Add primary_key and unique, if necessary.
                if column_name in indexes:
                    if indexes[column_name]['primary_key']:
                        extra_params['primary_key'] = True
                    elif indexes[column_name]['unique']:
                        extra_params['unique'] = True

                if is_relation:
                    rel_to = "self" if relations[column_name][1] == table_name else table2model(relations[column_name][1])
                    if rel_to in known_models:
                        field_type = 'ForeignKey(%s' % rel_to
                    else:
                        field_type = "ForeignKey('%s'" % rel_to
                else:
                    # Calling `get_field_type` to get the field type string and any
                    # additional parameters and notes.
                    field_type, field_params, field_notes = self.get_field_type(connection, table_name, row)
                    extra_params.update(field_params)
                    comment_notes.extend(field_notes)

                    field_type += '('

                # Don't output 'id = meta.AutoField(primary_key=True)', because
                # that's assumed if it doesn't exist.
                if att_name == 'id' and extra_params == {'primary_key': True}:
                    if field_type == 'AutoField(':
                        continue
                    elif field_type == 'IntegerField(' and not connection.features.can_introspect_autofield:
                        comment_notes.append('AutoField?')

                # Add 'null' and 'blank', if the 'null_ok' flag was present in the
                # table description.
                if row[6]:  # If it's NULL...
                    if field_type == 'BooleanField(':
                        field_type = 'NullBooleanField('
                    else:
                        extra_params['blank'] = True
                        extra_params['null'] = True

                field_desc = '%s = %s%s' % (
                    att_name,
                    # Custom fields will have a dotted path
                    '' if '.' in field_type else 'models.',
                    field_type,
                )
                if extra_params:
                    if not field_desc.endswith('('):
                        field_desc += ', '
                    field_desc += ', '.join(
                        '%s=%s' % (k, strip_prefix(repr(v)))
                        for k, v in extra_params.items())
                field_desc += ')'
                if comment_notes:
                    field_desc += '  # ' + ' '.join(comment_notes)
                yield '    %s' % field_desc
            for meta_line in self.get_meta(table_name, constraints):
                yield meta_line

def handle_merge(self, loader, conflicts):
    """
    Handles merging together conflicted migrations interactively,
    if it's safe; otherwise, advises on how to fix it.
    """
    if self.interactive:
        questioner = InteractiveMigrationQuestioner()
    else:
        questioner = MigrationQuestioner(defaults={'ask_merge': True})
    for app_label, migration_names in conflicts.items():
        # Grab out the migrations in question, and work out their
        # common ancestor.
        merge_migrations = []
        for migration_name in migration_names:
            migration = loader.get_migration(app_label, migration_name)
            migration.ancestry = loader.graph.forwards_plan((app_label, migration_name))
            merge_migrations.append(migration)
        all_items_equal = lambda seq: all(item == seq[0] for item in seq[1:])
        merge_migrations_generations = zip(*[m.ancestry for m in merge_migrations])
        common_ancestor_count = sum(1 for common_ancestor_generation
                                    in takewhile(all_items_equal, merge_migrations_generations))
        if not common_ancestor_count:
            raise ValueError("Could not find common ancestor of %s" % migration_names)
        # Now work out the operations along each divergent branch
        for migration in merge_migrations:
            migration.branch = migration.ancestry[common_ancestor_count:]
            migrations_ops = (loader.get_migration(node_app, node_name).operations
                              for node_app, node_name in migration.branch)
            migration.merged_operations = sum(migrations_ops, [])
        # In future, this could use some of the Optimizer code
        # (can_optimize_through) to automatically see if they're
        # mergeable. For now, we always just prompt the user.
        if self.verbosity > 0:
            self.stdout.write(self.style.MIGRATE_HEADING("Merging %s" % app_label))
            for migration in merge_migrations:
                self.stdout.write(self.style.MIGRATE_LABEL("  Branch %s" % migration.name))
                for operation in migration.merged_operations:
                    self.stdout.write("    - %s\n" % operation.describe())
        if questioner.ask_merge(app_label):
            # If they still want to merge it, then write out an empty
            # file depending on the migrations needing merging.
            numbers = [
                MigrationAutodetector.parse_number(migration.name)
                for migration in merge_migrations
            ]
            try:
                biggest_number = max(x for x in numbers if x is not None)
            except ValueError:
                biggest_number = 1
            subclass = type("Migration", (Migration, ), {
                "dependencies": [(app_label, migration.name) for migration in merge_migrations],
            })
            new_migration = subclass("%04i_merge" % (biggest_number + 1), app_label)
            writer = MigrationWriter(new_migration)

            if not self.dry_run:
                # Write the merge migrations file to the disk
                with open(writer.path, "wb") as fh:
                    fh.write(writer.as_string())
                if self.verbosity > 0:
                    self.stdout.write("\nCreated new merge migration %s" % writer.path)
            elif self.verbosity == 3:
                # Alternatively, makemigrations --merge --dry-run --verbosity 3
                # will output the merge migrations to stdout rather than saving
                # the file to the disk.
                self.stdout.write(self.style.MIGRATE_HEADING(
                    "Full merge migrations file '%s':" % writer.filename) + "\n"
                )
                self.stdout.write("%s\n" % writer.as_string())

def process_response(self, request, response):
    """Sets the cache, if needed."""
    if not self._should_update_cache(request, response):
        # We don't need to update the cache, just return.
        return response

    if response.streaming or response.status_code != 200:
        return response

    # Don't cache responses that set a user-specific (and maybe security
    # sensitive) cookie in response to a cookie-less request.
    if not request.COOKIES and response.cookies and has_vary_header(response, 'Cookie'):
        return response

    # Try to get the timeout from the "max-age" section of the "Cache-
    # Control" header before reverting to using the default cache_timeout
    # length.
    timeout = get_max_age(response)
    if timeout is None:
        timeout = self.cache_timeout
    elif timeout == 0:
        # max-age was set to 0, don't bother caching.
        return response
    patch_response_headers(response, timeout)
    if timeout:
        cache_key = learn_cache_key(request, response, timeout, self.key_prefix, cache=self.cache)
        if hasattr(response, 'render') and callable(response.render):
            response.add_post_render_callback(
                lambda r: self.cache.set(cache_key, r, timeout)
            )
        else:
            self.cache.set(cache_key, response, timeout)
    return response

