def check_url(self, path, method='GET', body=None, headers=None,
              expected_status=200, allowed_warnings=None,
              allowed_errors=None):
    url = self.get_url(path)
    red = self.run_redbot(url, method, body, headers)
    if not red.response.complete:
        if isinstance(red.response.http_error, Exception):
            logging.warning((red.response.http_error.desc, vars(red.response.http_error), url))
            raise red.response.http_error.res_error
        else:
            raise Exception("unknown error; incomplete response")
    self.assertEqual(int(red.response.status_code), expected_status)

    allowed_warnings = (allowed_warnings or []) + self.get_allowed_warnings()
    allowed_errors = (allowed_errors or []) + self.get_allowed_errors()

    errors = []
    warnings = []
    for msg in red.response.notes:
        if msg.level == 'bad':
            logger = logging.error
            if not isinstance(msg, tuple(allowed_errors)):
                errors.append(msg)
        elif msg.level == 'warning':
            logger = logging.warning
            if not isinstance(msg, tuple(allowed_warnings)):
                warnings.append(msg)
        elif msg.level in ('good', 'info', 'uri'):
            logger = logging.info
        else:
            raise Exception('unknown level' + msg.level)
        logger('%s: %s (%s)', msg.category, msg.show_summary('en'),
               msg.__class__.__name__)
        logger(msg.show_text('en'))

    self.assertEqual(len(warnings) + len(errors), 0,
                     'Had %d unexpected warnings and %d errors' %
                     (len(warnings), len(errors)))

def flush(self, include_footers=False, callback=None):
    """Flushes the current output buffer to the network.

    The ``callback`` argument, if given, can be used for flow control:
    it will be run when all flushed data has been written to the socket.
    Note that only one flush callback can be outstanding at a time;
    if another flush occurs before the previous flush's callback
    has been run, the previous callback will be discarded.

    .. versionchanged:: 4.0
       Now returns a `.Future` if no callback is given.
    """
    chunk = b"".join(self._write_buffer)
    self._write_buffer = []
    if not self._headers_written:
        self._headers_written = True
        for transform in self._transforms:
            self._status_code, self._headers, chunk = \
                transform.transform_first_chunk(
                    self._status_code, self._headers,
                    chunk, include_footers)
        # Ignore the chunk and only write the headers for HEAD requests
        if self.request.method == "HEAD":
            chunk = None

        # Finalize the cookie headers (which have been stored in a side
        # object so an outgoing cookie could be overwritten before it
        # is sent).
        if hasattr(self, "_new_cookie"):
            for cookie in self._new_cookie.values():
                self.add_header("Set-Cookie", cookie.OutputString(None))

        start_line = httputil.ResponseStartLine('',
                                                self._status_code,
                                                self._reason)
        return self.request.connection.write_headers(
            start_line, self._headers, chunk, callback=callback)
    else:
        for transform in self._transforms:
            chunk = transform.transform_chunk(chunk, include_footers)
        # Ignore the chunk and only write the headers for HEAD requests
        if self.request.method != "HEAD":
            return self.request.connection.write(chunk, callback=callback)
        else:
            future = Future()
            future.set_result(None)
            return future

def finish(self):
    if self.stream_request_body:
        self.request.body.set_result(None)
    else:
        self.request.body = b''.join(self.chunks)
        self.request._parse_body()
        self.execute()

def add_handler(self, fd, handler, events):
    if fd in self.fds:
        raise ValueError('fd %s added twice' % fd)
    fd, fileobj = self.split_fd(fd)
    self.fds[fd] = _FD(fd, fileobj, wrap(handler))
    if events & tornado.ioloop.IOLoop.READ:
        self.fds[fd].reading = True
        self.reactor.addReader(self.fds[fd])
    if events & tornado.ioloop.IOLoop.WRITE:
        self.fds[fd].writing = True
        self.reactor.addWriter(self.fds[fd])

def resolve(self, host, port, family=0):
    # getHostByName doesn't accept IP addresses, so if the input
    # looks like an IP address just return it immediately.
    if twisted.internet.abstract.isIPAddress(host):
        resolved = host
        resolved_family = socket.AF_INET
    elif twisted.internet.abstract.isIPv6Address(host):
        resolved = host
        resolved_family = socket.AF_INET6
    else:
        deferred = self.resolver.getHostByName(utf8(host))
        resolved = yield gen.Task(deferred.addBoth)
        if isinstance(resolved, failure.Failure):
            resolved.raiseException()
        elif twisted.internet.abstract.isIPAddress(resolved):
            resolved_family = socket.AF_INET
        elif twisted.internet.abstract.isIPv6Address(resolved):
            resolved_family = socket.AF_INET6
        else:
            resolved_family = socket.AF_UNSPEC
    if family != socket.AF_UNSPEC and family != resolved_family:
        raise Exception('Requested socket family %d but got %d' %
                        (family, resolved_family))
    result = [
        (resolved_family, (resolved, port)),
    ]
    raise gen.Return(result)

def prepare(self):
    if 'expected_size' in self.request.arguments:
        self.request.connection.set_max_body_size(
            int(self.get_argument('expected_size')))
    if 'body_timeout' in self.request.arguments:
        self.request.connection.set_body_timeout(
            float(self.get_argument('body_timeout')))

def run(self):
    env = self.state.document.settings.env

    # Interface function
    name = self.arguments[0].strip()
    obj = _import_object(name)
    args, varargs, keywords, defaults = inspect.getargspec(obj)

    # Implementation function
    impl_name = self.options['impl']
    impl_obj = _import_object(impl_name)
    impl_args, impl_varargs, impl_keywords, impl_defaults = inspect.getargspec(impl_obj)

    # Format signature taking implementation into account
    args = list(args)
    defaults = list(defaults)

    def set_default(arg, value):
        j = args.index(arg)
        defaults[len(defaults) - (len(args) - j)] = value

    def remove_arg(arg):
        if arg not in args:
            return
        j = args.index(arg)
        if j < len(args) - len(defaults):
            del args[j]
        else:
            del defaults[len(defaults) - (len(args) - j)]
            del args[j]

    options = []
    for j, opt_name in enumerate(impl_args):
        if opt_name in args:
            continue
        if j >= len(impl_args) - len(impl_defaults):
            options.append((opt_name, impl_defaults[len(impl_defaults) - (len(impl_args) - j)]))
        else:
            options.append((opt_name, None))
    set_default('options', dict(options))
    set_default('method', self.options['method'].strip())

    for arg in list(args):
        if arg not in impl_args and arg not in ('fun', 'x0', 'args', 'tol',
                                                'callback', 'method', 'options'):
            remove_arg(arg)

    signature = inspect.formatargspec(args, varargs, keywords, defaults)

    # Produce output
    self.options['noindex'] = True
    self.arguments[0] = name + signature
    lines = textwrap.dedent(pydoc.getdoc(impl_obj)).splitlines()
    new_lines = []
    for line in lines:
        if line.strip() == 'Options':
            new_lines.append("Other Parameters")
        elif line.strip() == "-"*len('Options'):
            new_lines.append("-"*len("Other Parameters"))
        else:
            new_lines.append(line)
    mangle_docstrings(env.app, 'function', name, None, None, new_lines)
    lines = new_lines
    new_lines = []
    for line in lines:
        if line.strip() == ':Other Parameters:':
            new_lines.extend((BLURB % (name,)).splitlines())
            new_lines.append(':Options:')
        else:
            new_lines.append(line)
    self.content = ViewList(new_lines, self.content.parent)
    return base_directive.run(self)

def _gen_work(self):
    """ Generate a suitable work array if one does not already exist.
    """

    n = self.data.x.shape[-1]
    p = self.beta0.shape[0]

    if len(self.data.x.shape) == 2:
        m = self.data.x.shape[0]
    else:
        m = 1

    if self.model.implicit:
        q = self.data.y
    elif len(self.data.y.shape) == 2:
        q = self.data.y.shape[0]
    else:
        q = 1

    if self.data.we is None:
        ldwe = ld2we = 1
    elif len(self.data.we.shape) == 3:
        ld2we, ldwe = self.data.we.shape[1:]
    else:
        # Okay, this isn't precisely right, but for this calculation,
        # it's fine
        ldwe = 1
        ld2we = self.data.we.shape[1]

    if self.job % 10 < 2:
        # ODR not OLS
        lwork = (18 + 11*p + p*p + m + m*m + 4*n*q + 6*n*m + 2*n*q*p +
                 2*n*q*m + q*q + 5*q + q*(p+m) + ldwe*ld2we*q)
    else:
        # OLS not ODR
        lwork = (18 + 11*p + p*p + m + m*m + 4*n*q + 2*n*m + 2*n*q*p +
                 5*q + q*(p+m) + ldwe*ld2we*q)

    if isinstance(self.work, numpy.ndarray) and self.work.shape == (lwork,)\
            and self.work.dtype.str.endswith('f8'):
        # the existing array is fine
        return
    else:
        self.work = numpy.zeros((lwork,), float)

def _check(self):
    """ Checks data structure for consistency """
    nnz = self.nnz

    # index arrays should have integer data types
    if self.row.dtype.kind != 'i':
        warn("row index array has non-integer dtype (%s)  "
                % self.row.dtype.name)
    if self.col.dtype.kind != 'i':
        warn("col index array has non-integer dtype (%s) "
                % self.col.dtype.name)

    idx_dtype = get_index_dtype(maxval=max(self.shape))
    self.row = np.asarray(self.row, dtype=idx_dtype)
    self.col = np.asarray(self.col, dtype=idx_dtype)
    self.data = to_native(self.data)

    if nnz > 0:
        if self.row.max() >= self.shape[0]:
            raise ValueError('row index exceeds matrix dimensions')
        if self.col.max() >= self.shape[1]:
            raise ValueError('column index exceeds matrix dimensions')
        if self.row.min() < 0:
            raise ValueError('negative row index found')
        if self.col.min() < 0:
            raise ValueError('negative column index found')

def code(self,*args):
    if len(args) != self.function.func_code.co_argcount:
        raise TypeError('%s() takes exactly %d arguments (%d given)' %
                    (self.function.__name__,
                     self.function.func_code.co_argcount,
                     len(args)))
    signature = tuple(map(lookup_type,args))
    ident = self.function.__name__
    return self.accelerate(signature,ident).function_code()

