class RRuleLocator(DateLocator):
    # use the dateutil rrule instance

    def __init__(self, o, tz=None):
        DateLocator.__init__(self, tz)
        self.rule = o

    def __call__(self):
        # if no data have been set, this will tank with a ValueError
        try:
            dmin, dmax = self.viewlim_to_dt()
        except ValueError:
            return []

        if dmin > dmax:
            dmax, dmin = dmin, dmax
        delta = relativedelta(dmax, dmin)

        # We need to cap at the endpoints of valid datetime
        try:
            start = dmin - delta
        except ValueError:
            start = _from_ordinalf(1.0)

        try:
            stop = dmax + delta
        except ValueError:
            # The magic number!
            stop = _from_ordinalf(3652059.9999999)

        self.rule.set(dtstart=start, until=stop, count=self.MAXTICKS + 1)

        # estimate the number of ticks very approximately so we don't
        # have to do a very expensive (and potentially near infinite)
        # 'between' calculation, only to find out it will fail.
        nmax, nmin = date2num((dmax, dmin))
        estimate = (nmax - nmin) / (self._get_unit() * self._get_interval())
        # This estimate is only an estimate, so be really conservative
        # about bailing...
        if estimate > self.MAXTICKS * 2:
            raise RuntimeError(
                'RRuleLocator estimated to generate %d ticks from %s to %s: '
                'exceeds Locator.MAXTICKS * 2 (%d) ' % (estimate, dmin, dmax,
                                                        self.MAXTICKS * 2))

        dates = self.rule.between(dmin, dmax, True)
        if len(dates) == 0:
            return date2num([dmin, dmax])
        return self.raise_if_exceeds(date2num(dates))

    def _get_unit(self):
        """
        Return how many days a unit of the locator is; used for
        intelligent autoscaling.
        """
        freq = self.rule._rrule._freq
        return self.get_unit_generic(freq)

    @staticmethod
    def get_unit_generic(freq):
        if (freq == YEARLY):
            return 365.0
        elif (freq == MONTHLY):
            return 30.0
        elif (freq == WEEKLY):
            return 7.0
        elif (freq == DAILY):
            return 1.0
        elif (freq == HOURLY):
            return (1.0 / 24.0)
        elif (freq == MINUTELY):
            return (1.0 / (24 * 60))
        elif (freq == SECONDLY):
            return (1.0 / (24 * 3600))
        else:
            # error
            return -1   # or should this just return '1'?

    def _get_interval(self):
        return self.rule._rrule._interval

    def autoscale(self):
        """
        Set the view limits to include the data range.
        """
        dmin, dmax = self.datalim_to_dt()
        if dmin > dmax:
            dmax, dmin = dmin, dmax

        delta = relativedelta(dmax, dmin)

        # We need to cap at the endpoints of valid datetime
        try:
            start = dmin - delta
        except ValueError:
            start = _from_ordinalf(1.0)

        try:
            stop = dmax + delta
        except ValueError:
            # The magic number!
            stop = _from_ordinalf(3652059.9999999)

        self.rule.set(dtstart=start, until=stop)
        dmin, dmax = self.datalim_to_dt()

        vmin = self.rule.before(dmin, True)
        if not vmin:
            vmin = dmin

        vmax = self.rule.after(dmax, True)
        if not vmax:
            vmax = dmax

        vmin = date2num(vmin)
        vmax = date2num(vmax)

        return self.nonsingular(vmin, vmax)

def set_data(self, x, y, A):
    A = cbook.safe_masked_invalid(A)
    if x is None:
        x = np.arange(0, A.shape[1]+1, dtype=np.float64)
    else:
        x = np.asarray(x, np.float64).ravel()
    if y is None:
        y = np.arange(0, A.shape[0]+1, dtype=np.float64)
    else:
        y = np.asarray(y, np.float64).ravel()

    if A.shape[:2] != (y.size-1, x.size-1):
        print(A.shape)
        print(y.size)
        print(x.size)
        raise ValueError("Axes don't match array shape")
    if A.ndim not in [2, 3]:
        raise ValueError("A must be 2D or 3D")
    if A.ndim == 3 and A.shape[2] == 1:
        A.shape = A.shape[:2]
    self.is_grayscale = False
    if A.ndim == 3:
        if A.shape[2] in [3, 4]:
            if ((A[:, :, 0] == A[:, :, 1]).all() and
                (A[:, :, 0] == A[:, :, 2]).all()):
                self.is_grayscale = True
        else:
            raise ValueError("3D arrays must have RGB or RGBA as last dim")
    self._A = A
    self._Ax = x
    self._Ay = y
    self._rgbacache = None

def _make_verts(self, U, V):
    uv = (U + V * 1j)
    if self.angles == 'xy' and self.scale_units == 'xy':
        # Here eps is 1 so that if we get U, V by diffing
        # the X, Y arrays, the vectors will connect the
        # points, regardless of the axis scaling (including log).
        angles, lengths = self._angles_lengths(U, V, eps=1)
    elif self.angles == 'xy' or self.scale_units == 'xy':
        # Calculate eps based on the extents of the plot
        # so that we don't end up with roundoff error from
        # adding a small number to a large.
        eps = np.abs(self.ax.dataLim.extents).max() * 0.001
        angles, lengths = self._angles_lengths(U, V, eps=eps)
    if self.scale_units == 'xy':
        a = lengths
    else:
        a = np.absolute(uv)
    if self.scale is None:
        sn = max(10, math.sqrt(self.N))
        if self.Umask is not ma.nomask:
            amean = a[~self.Umask].mean()
        else:
            amean = a.mean()
        scale = 1.8 * amean * sn / self.span  # crude auto-scaling
            # scale is typical arrow length as a multiple
            # of the arrow width
    if self.scale_units is None:
        if self.scale is None:
            self.scale = scale
        widthu_per_lenu = 1.0
    else:
        if self.scale_units == 'xy':
            dx = 1
        else:
            dx = self._dots_per_unit(self.scale_units)
        widthu_per_lenu = dx / self._trans_scale
        if self.scale is None:
            self.scale = scale * widthu_per_lenu
    length = a * (widthu_per_lenu / (self.scale * self.width))
    X, Y = self._h_arrows(length)
    if self.angles == 'xy':
        theta = angles
    elif self.angles == 'uv':
        theta = np.angle(uv)
    else:
        # Make a copy to avoid changing the input array.
        theta = ma.masked_invalid(self.angles, copy=True).filled(0)
        theta = theta.ravel()
        theta *= (np.pi / 180.0)
    theta.shape = (theta.shape[0], 1)  # for broadcasting
    xy = (X + Y * 1j) * np.exp(1j * theta) * self.width
    xy = xy[:, :, np.newaxis]
    XY = np.concatenate((xy.real, xy.imag), axis=2)
    if self.Umask is not ma.nomask:
        XY = ma.array(XY)
        XY[self.Umask] = ma.masked
        # This might be handled more efficiently with nans, given
        # that nans will end up in the paths anyway.

    return XY

