def lookup_allowed(self, lookup, value):
    from django.contrib.admin.filters import SimpleListFilter

    model = self.model
    # Check FKey lookups that are allowed, so that popups produced by
    # ForeignKeyRawIdWidget, on the basis of ForeignKey.limit_choices_to,
    # are allowed to work.
    for l in model._meta.related_fkey_lookups:
        # As ``limit_choices_to`` can be a callable, invoke it here.
        if callable(l):
            l = l()
        for k, v in widgets.url_params_from_lookup_dict(l).items():
            if k == lookup and v == value:
                return True

    parts = lookup.split(LOOKUP_SEP)

    # Last term in lookup is a query term (__exact, __startswith etc)
    # This term can be ignored.
    if len(parts) > 1 and parts[-1] in QUERY_TERMS:
        parts.pop()

    # Special case -- foo__id__exact and foo__id queries are implied
    # if foo has been specifically included in the lookup list; so
    # drop __id if it is the last part. However, first we need to find
    # the pk attribute name.
    rel_name = None
    for part in parts[:-1]:
        try:
            field = model._meta.get_field(part)
        except FieldDoesNotExist:
            # Lookups on non-existent fields are ok, since they're ignored
            # later.
            return True
        if hasattr(field, 'rel'):
            if field.rel is None:
                # This property or relation doesn't exist, but it's allowed
                # since it's ignored in ChangeList.get_filters().
                return True
            model = field.rel.to
            if hasattr(field.rel, 'get_related_field'):
                rel_name = field.rel.get_related_field().name
            else:
                rel_name = None
        elif isinstance(field, ForeignObjectRel):
            model = field.related_model
            rel_name = model._meta.pk.name
        else:
            rel_name = None
    if rel_name and len(parts) > 1 and parts[-1] == rel_name:
        parts.pop()

    if len(parts) == 1:
        return True
    clean_lookup = LOOKUP_SEP.join(parts)
    valid_lookups = [self.date_hierarchy]
    for filter_item in self.list_filter:
        if isinstance(filter_item, type) and issubclass(filter_item, SimpleListFilter):
            valid_lookups.append(filter_item.parameter_name)
        elif isinstance(filter_item, (list, tuple)):
            valid_lookups.append(filter_item[0])
        else:
            valid_lookups.append(filter_item)
    return clean_lookup in valid_lookups

def items_for_result(cl, result, form):
    """
    Generates the actual list of data.
    """

    def link_in_col(is_first, field_name, cl):
        if cl.list_display_links is None:
            return False
        if is_first and not cl.list_display_links:
            return True
        return field_name in cl.list_display_links

    first = True
    pk = cl.lookup_opts.pk.attname
    for field_name in cl.list_display:
        row_classes = ['field-%s' % field_name]
        try:
            f, attr, value = lookup_field(field_name, result, cl.model_admin)
        except ObjectDoesNotExist:
            result_repr = EMPTY_CHANGELIST_VALUE
        else:
            if f is None:
                if field_name == 'action_checkbox':
                    row_classes = ['action-checkbox']
                allow_tags = getattr(attr, 'allow_tags', False)
                boolean = getattr(attr, 'boolean', False)
                if boolean:
                    allow_tags = True
                result_repr = display_for_value(value, boolean)
                # Strip HTML tags in the resulting text, except if the
                # function has an "allow_tags" attribute set to True.
                if allow_tags:
                    result_repr = mark_safe(result_repr)
                if isinstance(value, (datetime.date, datetime.time)):
                    row_classes.append('nowrap')
            else:
                if isinstance(f.rel, models.ManyToOneRel):
                    field_val = getattr(result, f.name)
                    if field_val is None:
                        result_repr = EMPTY_CHANGELIST_VALUE
                    else:
                        result_repr = field_val
                else:
                    result_repr = display_for_field(value, f)
                if isinstance(f, (models.DateField, models.TimeField, models.ForeignKey)):
                    row_classes.append('nowrap')
        if force_text(result_repr) == '':
            result_repr = mark_safe('&nbsp;')
        row_class = mark_safe(' class="%s"' % ' '.join(row_classes))
        # If list_display_links not defined, add the link tag to the first field
        if link_in_col(first, field_name, cl):
            table_tag = 'th' if first else 'td'
            first = False

            # Display link to the result's change_view if the url exists, else
            # display just the result's representation.
            try:
                url = cl.url_for_result(result)
            except NoReverseMatch:
                link_or_text = result_repr
            else:
                url = add_preserved_filters({'preserved_filters': cl.preserved_filters, 'opts': cl.opts}, url)
                # Convert the pk to something that can be used in Javascript.
                # Problem cases are long ints (23L) and non-ASCII strings.
                if cl.to_field:
                    attr = str(cl.to_field)
                else:
                    attr = pk
                value = result.serializable_value(attr)
                result_id = escapejs(value)
                link_or_text = format_html(
                    '<a href="{}"{}>{}</a>',
                    url,
                    format_html(
                        ' onclick="opener.dismissRelatedLookupPopup(window, '
                        '&#39;{}&#39;); return false;"', result_id
                    ) if cl.is_popup else '',
                    result_repr)

            yield format_html('<{}{}>{}</{}>',
                              table_tag,
                              row_class,
                              link_or_text,
                              table_tag)
        else:
            # By default the fields come from ModelAdmin.list_editable, but if we pull
            # the fields out of the form instead of list_editable custom admins
            # can provide fields on a per request basis
            if (form and field_name in form.fields and not (
                    field_name == cl.model._meta.pk.name and
                    form[cl.model._meta.pk.name].is_hidden)):
                bf = form[field_name]
                result_repr = mark_safe(force_text(bf.errors) + force_text(bf))
            yield format_html('<td{}>{}</td>', row_class, result_repr)
    if form and not form[cl.model._meta.pk.name].is_hidden:
        yield format_html('<td>{}</td>', force_text(form[cl.model._meta.pk.name]))

def default_reference_role(name, rawtext, text, lineno, inliner, options=None, content=None):
    if options is None:
        options = {}
    if content is None:
        content = []
    context = inliner.document.settings.default_reference_context
    node = docutils.nodes.reference(
        rawtext,
        text,
        refuri=(ROLES[context] % (
            inliner.document.settings.link_base,
            text.lower(),
        )),
        **options
    )
    return [node], []

def _check_relation(self, cls, parent_model):
    # There's no FK, but we do need to confirm that the ct_field and ct_fk_field are valid,
    # and that they are part of a GenericForeignKey.

    gfks = [
        f for f in cls.model._meta.virtual_fields
        if isinstance(f, GenericForeignKey)
    ]
    if len(gfks) == 0:
        return [
            checks.Error(
                "'%s.%s' has no GenericForeignKey." % (
                    cls.model._meta.app_label, cls.model._meta.object_name
                ),
                hint=None,
                obj=cls,
                id='admin.E301'
            )
        ]
    else:
        # Check that the ct_field and ct_fk_fields exist
        try:
            cls.model._meta.get_field(cls.ct_field)
        except FieldDoesNotExist:
            return [
                checks.Error(
                    "'ct_field' references '%s', which is not a field on '%s.%s'." % (
                        cls.ct_field, cls.model._meta.app_label, cls.model._meta.object_name
                    ),
                    hint=None,
                    obj=cls,
                    id='admin.E302'
                )
            ]

        try:
            cls.model._meta.get_field(cls.ct_fk_field)
        except FieldDoesNotExist:
            return [
                checks.Error(
                    "'ct_fk_field' references '%s', which is not a field on '%s.%s'." % (
                        cls.ct_fk_field, cls.model._meta.app_label, cls.model._meta.object_name
                    ),
                    hint=None,
                    obj=cls,
                    id='admin.E303'
                )
            ]

        # There's one or more GenericForeignKeys; make sure that one of them
        # uses the right ct_field and ct_fk_field.
        for gfk in gfks:
            if gfk.ct_field == cls.ct_field and gfk.fk_field == cls.ct_fk_field:
                return []

        return [
            checks.Error(
                "'%s.%s' has no GenericForeignKey using content type field '%s' and object ID field '%s'." % (
                    cls.model._meta.app_label, cls.model._meta.object_name, cls.ct_field, cls.ct_fk_field
                ),
                hint=None,
                obj=cls,
                id='admin.E304'
            )
        ]

def __init__(self, *args, **kwargs):
    super(PostGISSchemaEditor, self).__init__(*args, **kwargs)
    self.geometry_sql = []

def __repr__(self):
    return "<DeserializedObject: %s.%s(pk=%s)>" % (
        self.object._meta.app_label, self.object._meta.object_name, self.object.pk)

def _handle_fk_field_node(self, node, field):
    """
    Handle a <field> node for a ForeignKey
    """
    # Check if there is a child node named 'None', returning None if so.
    if node.getElementsByTagName('None'):
        return None
    else:
        if hasattr(field.rel.to._default_manager, 'get_by_natural_key'):
            keys = node.getElementsByTagName('natural')
            if keys:
                # If there are 'natural' subelements, it must be a natural key
                field_value = [getInnerText(k).strip() for k in keys]
                obj = field.rel.to._default_manager.db_manager(self.db).get_by_natural_key(*field_value)
                obj_pk = getattr(obj, field.rel.field_name)
                # If this is a natural foreign key to an object that
                # has a FK/O2O as the foreign key, use the FK value
                if field.rel.to._meta.pk.rel:
                    obj_pk = obj_pk.pk
            else:
                # Otherwise, treat like a normal PK
                field_value = getInnerText(node).strip()
                obj_pk = field.rel.to._meta.get_field(field.rel.field_name).to_python(field_value)
            return obj_pk
        else:
            field_value = getInnerText(node).strip()
            return field.rel.to._meta.get_field(field.rel.field_name).to_python(field_value)

def add_field(self, model, field):
    """
    Creates a field on a model.
    Usually involves adding a column, but may involve adding a
    table instead (for M2M fields)
    """
    # Special-case implicit M2M tables
    if field.many_to_many and field.rel.through._meta.auto_created:
        return self.create_model(field.rel.through)
    # Get the column's definition
    definition, params = self.column_sql(model, field, include_default=True)
    # It might not actually have a column behind it
    if definition is None:
        return
    # Check constraints can go on the column SQL here
    db_params = field.db_parameters(connection=self.connection)
    if db_params['check']:
        definition += " CHECK (%s)" % db_params['check']
    # Build the SQL and run it
    sql = self.sql_create_column % {
        "table": self.quote_name(model._meta.db_table),
        "column": self.quote_name(field.column),
        "definition": definition,
    }
    self.execute(sql, params)
    # Drop the default if we need to
    # (Django usually does not use in-database defaults)
    if not self.skip_default(field) and field.default is not None:
        sql = self.sql_alter_column % {
            "table": self.quote_name(model._meta.db_table),
            "changes": self.sql_alter_column_no_default % {
                "column": self.quote_name(field.column),
            }
        }
        self.execute(sql)
    # Add an index, if required
    if field.db_index and not field.unique:
        self.deferred_sql.append(self._create_index_sql(model, [field]))
    # Add any FK constraints later
    if field.rel and self.connection.features.supports_foreign_keys and field.db_constraint:
        self.deferred_sql.append(self._create_fk_sql(model, field, "_fk_%(to_table)s_%(to_column)s"))
    # Reset connection if required
    if self.connection.features.connection_persists_old_columns:
        self.connection.close()

def _alter_field(self, model, old_field, new_field, old_type, new_type,
                 old_db_params, new_db_params, strict=False):
    """Actually perform a "physical" (non-ManyToMany) field update."""

    # Drop any FK constraints, we'll remake them later
    fks_dropped = set()
    if old_field.rel and old_field.db_constraint:
        fk_names = self._constraint_names(model, [old_field.column], foreign_key=True)
        if strict and len(fk_names) != 1:
            raise ValueError("Found wrong number (%s) of foreign key constraints for %s.%s" % (
                len(fk_names),
                model._meta.db_table,
                old_field.column,
            ))
        for fk_name in fk_names:
            fks_dropped.add((old_field.column,))
            self.execute(self._delete_constraint_sql(self.sql_delete_fk, model, fk_name))
    # Has unique been removed?
    if old_field.unique and (not new_field.unique or (not old_field.primary_key and new_field.primary_key)):
        # Find the unique constraint for this field
        constraint_names = self._constraint_names(model, [old_field.column], unique=True)
        if strict and len(constraint_names) != 1:
            raise ValueError("Found wrong number (%s) of unique constraints for %s.%s" % (
                len(constraint_names),
                model._meta.db_table,
                old_field.column,
            ))
        for constraint_name in constraint_names:
            self.execute(self._delete_constraint_sql(self.sql_delete_unique, model, constraint_name))
    # Drop incoming FK constraints if we're a primary key and things are going
    # to change.
    if old_field.primary_key and new_field.primary_key and old_type != new_type:
        # '_meta.related_field' also contains M2M reverse fields, these
        # will be filtered out
        for _old_rel, new_rel in _related_non_m2m_objects(old_field, new_field):
            rel_fk_names = self._constraint_names(
                new_rel.related_model, [new_rel.field.column], foreign_key=True
            )
            for fk_name in rel_fk_names:
                self.execute(self._delete_constraint_sql(self.sql_delete_fk, new_rel.related_model, fk_name))
    # Removed an index? (no strict check, as multiple indexes are possible)
    if (old_field.db_index and not new_field.db_index and
            not old_field.unique and not
            (not new_field.unique and old_field.unique)):
        # Find the index for this field
        index_names = self._constraint_names(model, [old_field.column], index=True)
        for index_name in index_names:
            self.execute(self._delete_constraint_sql(self.sql_delete_index, model, index_name))
    # Change check constraints?
    if old_db_params['check'] != new_db_params['check'] and old_db_params['check']:
        constraint_names = self._constraint_names(model, [old_field.column], check=True)
        if strict and len(constraint_names) != 1:
            raise ValueError("Found wrong number (%s) of check constraints for %s.%s" % (
                len(constraint_names),
                model._meta.db_table,
                old_field.column,
            ))
        for constraint_name in constraint_names:
            self.execute(self._delete_constraint_sql(self.sql_delete_check, model, constraint_name))
    # Have they renamed the column?
    if old_field.column != new_field.column:
        self.execute(self.sql_rename_column % {
            "table": self.quote_name(model._meta.db_table),
            "old_column": self.quote_name(old_field.column),
            "new_column": self.quote_name(new_field.column),
            "type": new_type,
        })
    # Next, start accumulating actions to do
    actions = []
    null_actions = []
    post_actions = []
    # Type change?
    if old_type != new_type:
        fragment, other_actions = self._alter_column_type_sql(
            model._meta.db_table, old_field, new_field, new_type
        )
        actions.append(fragment)
        post_actions.extend(other_actions)
    # When changing a column NULL constraint to NOT NULL with a given
    # default value, we need to perform 4 steps:
    #  1. Add a default for new incoming writes
    #  2. Update existing NULL rows with new default
    #  3. Replace NULL constraint with NOT NULL
    #  4. Drop the default again.
    # Default change?
    old_default = self.effective_default(old_field)
    new_default = self.effective_default(new_field)
    needs_database_default = (
        old_default != new_default and
        new_default is not None and
        not self.skip_default(new_field)
    )
    if needs_database_default:
        if self.connection.features.requires_literal_defaults:
            # Some databases can't take defaults as a parameter (oracle)
            # If this is the case, the individual schema backend should
            # implement prepare_default
            actions.append((
                self.sql_alter_column_default % {
                    "column": self.quote_name(new_field.column),
                    "default": self.prepare_default(new_default),
                },
                [],
            ))
        else:
            actions.append((
                self.sql_alter_column_default % {
                    "column": self.quote_name(new_field.column),
                    "default": "%s",
                },
                [new_default],
            ))
    # Nullability change?
    if old_field.null != new_field.null:
        if (self.connection.features.interprets_empty_strings_as_nulls and
                new_field.get_internal_type() in ("CharField", "TextField")):
            # The field is nullable in the database anyway, leave it alone
            pass
        elif new_field.null:
            null_actions.append((
                self.sql_alter_column_null % {
                    "column": self.quote_name(new_field.column),
                    "type": new_type,
                },
                [],
            ))
        else:
            null_actions.append((
                self.sql_alter_column_not_null % {
                    "column": self.quote_name(new_field.column),
                    "type": new_type,
                },
                [],
            ))
    # Only if we have a default and there is a change from NULL to NOT NULL
    four_way_default_alteration = (
        new_field.has_default() and
        (old_field.null and not new_field.null)
    )
    if actions or null_actions:
        if not four_way_default_alteration:
            # If we don't have to do a 4-way default alteration we can
            # directly run a (NOT) NULL alteration
            actions = actions + null_actions
        # Combine actions together if we can (e.g. postgres)
        if self.connection.features.supports_combined_alters and actions:
            sql, params = tuple(zip(*actions))
            actions = [(", ".join(sql), sum(params, []))]
        # Apply those actions
        for sql, params in actions:
            self.execute(
                self.sql_alter_column % {
                    "table": self.quote_name(model._meta.db_table),
                    "changes": sql,
                },
                params,
            )
        if four_way_default_alteration:
            # Update existing rows with default value
            self.execute(
                self.sql_update_with_default % {
                    "table": self.quote_name(model._meta.db_table),
                    "column": self.quote_name(new_field.column),
                    "default": "%s",
                },
                [new_default],
            )
            # Since we didn't run a NOT NULL change before we need to do it
            # now
            for sql, params in null_actions:
                self.execute(
                    self.sql_alter_column % {
                        "table": self.quote_name(model._meta.db_table),
                        "changes": sql,
                    },
                    params,
                )
    if post_actions:
        for sql, params in post_actions:
            self.execute(sql, params)
    # Added a unique?
    if not old_field.unique and new_field.unique:
        self.execute(self._create_unique_sql(model, [new_field.column]))
    # Added an index?
    if (not old_field.db_index and new_field.db_index and
            not new_field.unique and not
            (not old_field.unique and new_field.unique)):
        self.execute(self._create_index_sql(model, [new_field], suffix="_uniq"))
    # Type alteration on primary key? Then we need to alter the column
    # referring to us.
    rels_to_update = []
    if old_field.primary_key and new_field.primary_key and old_type != new_type:
        rels_to_update.extend(_related_non_m2m_objects(old_field, new_field))
    # Changed to become primary key?
    # Note that we don't detect unsetting of a PK, as we assume another field
    # will always come along and replace it.
    if not old_field.primary_key and new_field.primary_key:
        # First, drop the old PK
        constraint_names = self._constraint_names(model, primary_key=True)
        if strict and len(constraint_names) != 1:
            raise ValueError("Found wrong number (%s) of PK constraints for %s" % (
                len(constraint_names),
                model._meta.db_table,
            ))
        for constraint_name in constraint_names:
            self.execute(self._delete_constraint_sql(self.sql_delete_pk, model, constraint_name))
        # Make the new one
        self.execute(
            self.sql_create_pk % {
                "table": self.quote_name(model._meta.db_table),
                "name": self.quote_name(self._create_index_name(model, [new_field.column], suffix="_pk")),
                "columns": self.quote_name(new_field.column),
            }
        )
        # Update all referencing columns
        rels_to_update.extend(_related_non_m2m_objects(old_field, new_field))
    # Handle our type alters on the other end of rels from the PK stuff above
    for old_rel, new_rel in rels_to_update:
        rel_db_params = new_rel.field.db_parameters(connection=self.connection)
        rel_type = rel_db_params['type']
        fragment, other_actions = self._alter_column_type_sql(
            new_rel.related_model._meta.db_table, old_rel.field, new_rel.field, rel_type
        )
        self.execute(
            self.sql_alter_column % {
                "table": self.quote_name(new_rel.related_model._meta.db_table),
                "changes": fragment[0],
            },
            fragment[1],
        )
        for sql, params in other_actions:
            self.execute(sql, params)
    # Does it have a foreign key?
    if (new_field.rel and
            (fks_dropped or not old_field.rel or not old_field.db_constraint) and
            new_field.db_constraint):
        self.execute(self._create_fk_sql(model, new_field, "_fk_%(to_table)s_%(to_column)s"))
    # Rebuild FKs that pointed to us if we previously had to drop them
    if old_field.primary_key and new_field.primary_key and old_type != new_type:
        for rel in new_field.model._meta.related_objects:
            if not rel.many_to_many:
                self.execute(self._create_fk_sql(rel.related_model, rel.field, "_fk"))
    # Does it have check constraints we need to add?
    if old_db_params['check'] != new_db_params['check'] and new_db_params['check']:
        self.execute(
            self.sql_create_check % {
                "table": self.quote_name(model._meta.db_table),
                "name": self.quote_name(self._create_index_name(model, [new_field.column], suffix="_check")),
                "column": self.quote_name(new_field.column),
                "check": new_db_params['check'],
            }
        )
    # Drop the default if we need to
    # (Django usually does not use in-database defaults)
    if needs_database_default:
        sql = self.sql_alter_column % {
            "table": self.quote_name(model._meta.db_table),
            "changes": self.sql_alter_column_no_default % {
                "column": self.quote_name(new_field.column),
            }
        }
        self.execute(sql)
    # Reset connection if required
    if self.connection.features.connection_persists_old_columns:
        self.connection.close()

def _constraint_names(self, model, column_names=None, unique=None,
                      primary_key=None, index=None, foreign_key=None,
                      check=None):
    """
    Returns all constraint names matching the columns and conditions
    """
    column_names = list(column_names) if column_names else None
    with self.connection.cursor() as cursor:
        constraints = self.connection.introspection.get_constraints(cursor, model._meta.db_table)
    result = []
    for name, infodict in constraints.items():
        if column_names is None or column_names == infodict['columns']:
            if unique is not None and infodict['unique'] != unique:
                continue
            if primary_key is not None and infodict['primary_key'] != primary_key:
                continue
            if index is not None and infodict['index'] != index:
                continue
            if check is not None and infodict['check'] != check:
                continue
            if foreign_key is not None and not infodict['foreign_key']:
                continue
            result.append(name)
    return result

def delete_model(self, model):
    # Run superclass action
    super(DatabaseSchemaEditor, self).delete_model(model)
    # Clean up any autoincrement trigger
    self.execute("""
        DECLARE
            i INTEGER;
        BEGIN
            SELECT COUNT(*) INTO i FROM USER_CATALOG
                WHERE TABLE_NAME = '%(sq_name)s' AND TABLE_TYPE = 'SEQUENCE';
            IF i = 1 THEN
                EXECUTE IMMEDIATE 'DROP SEQUENCE "%(sq_name)s"';
            END IF;
        END;
    /""" % {'sq_name': self.connection.ops._get_sequence_name(model._meta.db_table)})

def generate_deleted_models(self):
    """
    Find all deleted models (managed and unmanaged) and make delete
    operations for them as well as separate operations to delete any
    foreign key or M2M relationships (we'll optimize these back in later
    if we can).

    We also bring forward removal of any model options that refer to
    collections of fields - the inverse of generate_created_models().
    """
    new_keys = set(self.new_model_keys).union(self.new_unmanaged_keys)
    deleted_models = set(self.old_model_keys) - new_keys
    deleted_unmanaged_models = set(self.old_unmanaged_keys) - new_keys
    all_deleted_models = chain(sorted(deleted_models), sorted(deleted_unmanaged_models))
    for app_label, model_name in all_deleted_models:
        model_state = self.from_state.models[app_label, model_name]
        model = self.old_apps.get_model(app_label, model_name)
        if not model._meta.managed:
            # Skip here, no need to handle fields for unmanaged models
            continue

        # Gather related fields
        related_fields = {}
        for field in model._meta.local_fields:
            if field.rel:
                if field.rel.to:
                    related_fields[field.name] = field
                # through will be none on M2Ms on swapped-out models;
                # we can treat lack of through as auto_created=True, though.
                if getattr(field.rel, "through", None) and not field.rel.through._meta.auto_created:
                    related_fields[field.name] = field
        for field in model._meta.local_many_to_many:
            if field.rel.to:
                related_fields[field.name] = field
            if getattr(field.rel, "through", None) and not field.rel.through._meta.auto_created:
                related_fields[field.name] = field
        # Generate option removal first
        unique_together = model_state.options.pop('unique_together', None)
        index_together = model_state.options.pop('index_together', None)
        if unique_together:
            self.add_operation(
                app_label,
                operations.AlterUniqueTogether(
                    name=model_name,
                    unique_together=None,
                )
            )
        if index_together:
            self.add_operation(
                app_label,
                operations.AlterIndexTogether(
                    name=model_name,
                    index_together=None,
                )
            )
        # Then remove each related field
        for name, field in sorted(related_fields.items()):
            self.add_operation(
                app_label,
                operations.RemoveField(
                    model_name=model_name,
                    name=name,
                )
            )
        # Finally, remove the model.
        # This depends on both the removal/alteration of all incoming fields
        # and the removal of all its own related fields, and if it's
        # a through model the field that references it.
        dependencies = []
        for related_object in model._meta.related_objects:
            related_object_app_label = related_object.related_model._meta.app_label
            object_name = related_object.related_model._meta.object_name
            field_name = related_object.field.name
            dependencies.append((related_object_app_label, object_name, field_name, False))
            if not related_object.many_to_many:
                dependencies.append((related_object_app_label, object_name, field_name, "alter"))

        for name, field in sorted(related_fields.items()):
            dependencies.append((app_label, model_name, name, False))
        # We're referenced in another field's through=
        through_user = self.through_users.get((app_label, model_state.name_lower), None)
        if through_user:
            dependencies.append((through_user[0], through_user[1], through_user[2], False))
        # Finally, make the operation, deduping any dependencies
        self.add_operation(
            app_label,
            operations.DeleteModel(
                name=model_state.name,
            ),
            dependencies=list(set(dependencies)),
        )

def serialize(cls, value):
    """
    Serializes the value to a string that's parsable by Python, along
    with any needed imports to make that string work.
    More advanced than repr() as it can encode things
    like datetime.datetime.now.
    """
    # FIXME: Ideally Promise would be reconstructible, but for now we
    # use force_text on them and defer to the normal string serialization
    # process.
    if isinstance(value, Promise):
        value = force_text(value)

    # Sequences
    if isinstance(value, (list, set, tuple)):
        imports = set()
        strings = []
        for item in value:
            item_string, item_imports = cls.serialize(item)
            imports.update(item_imports)
            strings.append(item_string)
        if isinstance(value, set):
            # Don't use the literal "{%s}" as it doesn't support empty set
            format = "set([%s])"
        elif isinstance(value, tuple):
            # When len(value)==0, the empty tuple should be serialized as
            # "()", not "(,)" because (,) is invalid Python syntax.
            format = "(%s)" if len(value) != 1 else "(%s,)"
        else:
            format = "[%s]"
        return format % (", ".join(strings)), imports
    # Dictionaries
    elif isinstance(value, dict):
        imports = set()
        strings = []
        for k, v in value.items():
            k_string, k_imports = cls.serialize(k)
            v_string, v_imports = cls.serialize(v)
            imports.update(k_imports)
            imports.update(v_imports)
            strings.append((k_string, v_string))
        return "{%s}" % (", ".join("%s: %s" % (k, v) for k, v in strings)), imports
    # Datetimes
    elif isinstance(value, datetime.datetime):
        value_repr = cls.serialize_datetime(value)
        imports = ["import datetime"]
        if value.tzinfo is not None:
            imports.append("from django.utils.timezone import utc")
        return value_repr, set(imports)
    # Dates
    elif isinstance(value, datetime.date):
        value_repr = repr(value)
        if isinstance(value, datetime_safe.date):
            value_repr = "datetime.%s" % value_repr
        return value_repr, {"import datetime"}
    # Times
    elif isinstance(value, datetime.time):
        value_repr = repr(value)
        if isinstance(value, datetime_safe.time):
            value_repr = "datetime.%s" % value_repr
        return value_repr, {"import datetime"}
    # Timedeltas
    elif isinstance(value, datetime.timedelta):
        return repr(value), {"import datetime"}
    # Settings references
    elif isinstance(value, SettingsReference):
        return "settings.%s" % value.setting_name, {"from django.conf import settings"}
    # Simple types
    elif isinstance(value, float):
        if math.isnan(value) or math.isinf(value):
            return 'float("{}")'.format(value), set()
        return repr(value), set()
    elif isinstance(value, six.integer_types + (bool, type(None))):
        return repr(value), set()
    elif isinstance(value, six.binary_type):
        value_repr = repr(value)
        if six.PY2:
            # Prepend the `b` prefix since we're importing unicode_literals
            value_repr = 'b' + value_repr
        return value_repr, set()
    elif isinstance(value, six.text_type):
        value_repr = repr(value)
        if six.PY2:
            # Strip the `u` prefix since we're importing unicode_literals
            value_repr = value_repr[1:]
        return value_repr, set()
    # Decimal
    elif isinstance(value, decimal.Decimal):
        return repr(value), {"from decimal import Decimal"}
    # Django fields
    elif isinstance(value, models.Field):
        attr_name, path, args, kwargs = value.deconstruct()
        return cls.serialize_deconstructed(path, args, kwargs)
    # Classes
    elif isinstance(value, type):
        special_cases = [
            (models.Model, "models.Model", []),
        ]
        for case, string, imports in special_cases:
            if case is value:
                return string, set(imports)
        if hasattr(value, "__module__"):
            module = value.__module__
            if module == six.moves.builtins.__name__:
                return value.__name__, set()
            else:
                return "%s.%s" % (module, value.__name__), {"import %s" % module}
    elif isinstance(value, models.manager.BaseManager):
        as_manager, manager_path, qs_path, args, kwargs = value.deconstruct()
        if as_manager:
            name, imports = cls._serialize_path(qs_path)
            return "%s.as_manager()" % name, imports
        else:
            return cls.serialize_deconstructed(manager_path, args, kwargs)
    elif isinstance(value, Operation):
        string, imports = OperationWriter(value, indentation=0).serialize()
        # Nested operation, trailing comma is handled in upper OperationWriter._write()
        return string.rstrip(','), imports
    # Anything that knows how to deconstruct itself.
    elif hasattr(value, 'deconstruct'):
        return cls.serialize_deconstructed(*value.deconstruct())
    # Functions
    elif isinstance(value, (types.FunctionType, types.BuiltinFunctionType)):
        # @classmethod?
        if getattr(value, "__self__", None) and isinstance(value.__self__, type):
            klass = value.__self__
            module = klass.__module__
            return "%s.%s.%s" % (module, klass.__name__, value.__name__), {"import %s" % module}
        # Further error checking
        if value.__name__ == '<lambda>':
            raise ValueError("Cannot serialize function: lambda")
        if value.__module__ is None:
            raise ValueError("Cannot serialize function %r: No module" % value)
        # Python 3 is a lot easier, and only uses this branch if it's not local.
        if getattr(value, "__qualname__", None) and getattr(value, "__module__", None):
            if "<" not in value.__qualname__:  # Qualname can include <locals>
                return "%s.%s" % (value.__module__, value.__qualname__), {"import %s" % value.__module__}
        # Python 2/fallback version
        module_name = value.__module__
        # Make sure it's actually there and not an unbound method
        module = import_module(module_name)
        if not hasattr(module, value.__name__):
            raise ValueError(
                "Could not find function %s in %s.\n"
                "Please note that due to Python 2 limitations, you cannot "
                "serialize unbound method functions (e.g. a method "
                "declared and used in the same class body). Please move "
                "the function into the main module body to use migrations.\n"
                "For more information, see "
                "https://docs.djangoproject.com/en/%s/topics/migrations/#serializing-values"
                % (value.__name__, module_name, get_docs_version()))
        return "%s.%s" % (module_name, value.__name__), {"import %s" % module_name}
    # Other iterables
    elif isinstance(value, collections.Iterable):
        imports = set()
        strings = []
        for item in value:
            item_string, item_imports = cls.serialize(item)
            imports.update(item_imports)
            strings.append(item_string)
        # When len(strings)==0, the empty iterable should be serialized as
        # "()", not "(,)" because (,) is invalid Python syntax.
        format = "(%s)" if len(strings) != 1 else "(%s,)"
        return format % (", ".join(strings)), imports
    # Compiled regex
    elif isinstance(value, COMPILED_REGEX_TYPE):
        imports = {"import re"}
        regex_pattern, pattern_imports = cls.serialize(value.pattern)
        regex_flags, flag_imports = cls.serialize(value.flags)
        imports.update(pattern_imports)
        imports.update(flag_imports)
        args = [regex_pattern]
        if value.flags:
            args.append(regex_flags)
        return "re.compile(%s)" % ', '.join(args), imports
    # Uh oh.
    else:
        raise ValueError(
            "Cannot serialize: %r\nThere are some values Django cannot serialize into "
            "migration files.\nFor more, see https://docs.djangoproject.com/en/%s/"
            "topics/migrations/#migration-serializing" % (value, get_docs_version())
        )

def _run_sql(self, schema_editor, sqls):
    if isinstance(sqls, (list, tuple)):
        for sql in sqls:
            params = None
            if isinstance(sql, (list, tuple)):
                elements = len(sql)
                if elements == 2:
                    sql, params = sql
                else:
                    raise ValueError("Expected a 2-tuple but got %d" % elements)
            schema_editor.execute(sql, params=params)
    elif sqls != RunSQL.noop:
        statements = schema_editor.connection.ops.prepare_sql_script(sqls)
        for statement in statements:
            schema_editor.execute(statement, params=None)

def PROTECT(collector, field, sub_objs, using):
    raise ProtectedError("Cannot delete some instances of model '%s' because "
        "they are referenced through a protected foreign key: '%s.%s'" % (
            field.rel.to.__name__, sub_objs[0].__class__.__name__, field.name
        ),
        sub_objs
    )

class Options(object):
    FORWARD_PROPERTIES = ('fields', 'many_to_many', 'concrete_fields',
                          'local_concrete_fields', '_forward_fields_map')
    REVERSE_PROPERTIES = ('related_objects', 'fields_map', '_relation_tree')

    def __init__(self, meta, app_label=None):
        self._get_fields_cache = {}
        self.proxied_children = []
        self.local_fields = []
        self.local_many_to_many = []
        self.virtual_fields = []
        self.model_name = None
        self.verbose_name = None
        self.verbose_name_plural = None
        self.db_table = ''
        self.ordering = []
        self.unique_together = []
        self.index_together = []
        self.select_on_save = False
        self.default_permissions = ('add', 'change', 'delete')
        self.permissions = []
        self.object_name = None
        self.app_label = app_label
        self.get_latest_by = None
        self.order_with_respect_to = None
        self.db_tablespace = settings.DEFAULT_TABLESPACE
        self.meta = meta
        self.pk = None
        self.has_auto_field = False
        self.auto_field = None
        self.abstract = False
        self.managed = True
        self.proxy = False
        # For any class that is a proxy (including automatically created
        # classes for deferred object loading), proxy_for_model tells us
        # which class this model is proxying. Note that proxy_for_model
        # can create a chain of proxy models. For non-proxy models, the
        # variable is always None.
        self.proxy_for_model = None
        # For any non-abstract class, the concrete class is the model
        # in the end of the proxy_for_model chain. In particular, for
        # concrete models, the concrete_model is always the class itself.
        self.concrete_model = None
        self.swappable = None
        self.parents = OrderedDict()
        self.auto_created = False

        # To handle various inheritance situations, we need to track where
        # managers came from (concrete or abstract base classes). `managers`
        # keeps a list of 3-tuples of the form:
        # (creation_counter, instance, abstract(=True))
        self.managers = []

        # List of all lookups defined in ForeignKey 'limit_choices_to' options
        # from *other* models. Needed for some admin checks. Internal use only.
        self.related_fkey_lookups = []

        # A custom app registry to use, if you're making a separate model set.
        self.apps = apps

        self.default_related_name = None

    @lru_cache(maxsize=None)
    def _map_model(self, link):
        # This helper function is used to allow backwards compatibility with
        # the previous API. No future methods should use this function.
        # It maps a field to (field, model or related_model,) depending on the
        # field type.
        model = link.model._meta.concrete_model
        if model is self.model:
            model = None
        return link, model

    @lru_cache(maxsize=None)
    def _map_model_details(self, link):
        # This helper function is used to allow backwards compatibility with
        # the previous API. No future methods should use this function.
        # This function maps a field to a tuple of:
        #  (field, model or related_model, direct, is_m2m) depending on the
        # field type.
        direct = not link.auto_created or link.concrete
        model = link.model._meta.concrete_model
        if model is self.model:
            model = None
        m2m = link.is_relation and link.many_to_many
        return link, model, direct, m2m

    @property
    def app_config(self):
        # Don't go through get_app_config to avoid triggering imports.
        return self.apps.app_configs.get(self.app_label)

    @property
    def installed(self):
        return self.app_config is not None

    @property
    def abstract_managers(self):
        return [
            (counter, instance.name, instance) for counter, instance, abstract
            in self.managers if abstract
        ]

    @property
    def concrete_managers(self):
        return [
            (counter, instance.name, instance) for counter, instance, abstract
            in self.managers if not abstract
        ]

    def contribute_to_class(self, cls, name):
        from django.db import connection
        from django.db.backends.utils import truncate_name

        cls._meta = self
        self.model = cls
        # First, construct the default values for these options.
        self.object_name = cls.__name__
        self.model_name = self.object_name.lower()
        self.verbose_name = camel_case_to_spaces(self.object_name)

        # Store the original user-defined values for each option,
        # for use when serializing the model definition
        self.original_attrs = {}

        # Next, apply any overridden values from 'class Meta'.
        if self.meta:
            meta_attrs = self.meta.__dict__.copy()
            for name in self.meta.__dict__:
                # Ignore any private attributes that Django doesn't care about.
                # NOTE: We can't modify a dictionary's contents while looping
                # over it, so we loop over the *original* dictionary instead.
                if name.startswith('_'):
                    del meta_attrs[name]
            for attr_name in DEFAULT_NAMES:
                if attr_name in meta_attrs:
                    setattr(self, attr_name, meta_attrs.pop(attr_name))
                    self.original_attrs[attr_name] = getattr(self, attr_name)
                elif hasattr(self.meta, attr_name):
                    setattr(self, attr_name, getattr(self.meta, attr_name))
                    self.original_attrs[attr_name] = getattr(self, attr_name)

            ut = meta_attrs.pop('unique_together', self.unique_together)
            self.unique_together = normalize_together(ut)

            it = meta_attrs.pop('index_together', self.index_together)
            self.index_together = normalize_together(it)

            # verbose_name_plural is a special case because it uses a 's'
            # by default.
            if self.verbose_name_plural is None:
                self.verbose_name_plural = string_concat(self.verbose_name, 's')

            # Any leftover attributes must be invalid.
            if meta_attrs != {}:
                raise TypeError("'class Meta' got invalid attribute(s): %s" % ','.join(meta_attrs.keys()))
        else:
            self.verbose_name_plural = string_concat(self.verbose_name, 's')
        del self.meta

        # If the db_table wasn't provided, use the app_label + model_name.
        if not self.db_table:
            self.db_table = "%s_%s" % (self.app_label, self.model_name)
            self.db_table = truncate_name(self.db_table, connection.ops.max_name_length())

    def _prepare(self, model):
        if self.order_with_respect_to:
            # The app registry will not be ready at this point, so we cannot
            # use get_field().
            query = self.order_with_respect_to
            try:
                self.order_with_respect_to = next(
                    f for f in self._get_fields(reverse=False)
                    if f.name == query or f.attname == query
                )
            except StopIteration:
                raise FieldDoesNotExist('%s has no field named %r' % (self.object_name, query))

            self.ordering = ('_order',)
            if not any(isinstance(field, OrderWrt) for field in model._meta.local_fields):
                model.add_to_class('_order', OrderWrt())
        else:
            self.order_with_respect_to = None

        if self.pk is None:
            if self.parents:
                # Promote the first parent link in lieu of adding yet another
                # field.
                field = next(six.itervalues(self.parents))
                # Look for a local field with the same name as the
                # first parent link. If a local field has already been
                # created, use it instead of promoting the parent
                already_created = [fld for fld in self.local_fields if fld.name == field.name]
                if already_created:
                    field = already_created[0]
                field.primary_key = True
                self.setup_pk(field)
            else:
                auto = AutoField(verbose_name='ID', primary_key=True,
                        auto_created=True)
                model.add_to_class('id', auto)

    def add_field(self, field, virtual=False):
        # Insert the given field in the order in which it was created, using
        # the "creation_counter" attribute of the field.
        # Move many-to-many related fields from self.fields into
        # self.many_to_many.
        if virtual:
            self.virtual_fields.append(field)
        elif field.is_relation and field.many_to_many:
            self.local_many_to_many.insert(bisect(self.local_many_to_many, field), field)
        else:
            self.local_fields.insert(bisect(self.local_fields, field), field)
            self.setup_pk(field)

        # If the field being added is a relation to another known field,
        # expire the cache on this field and the forward cache on the field
        # being referenced, because there will be new relationships in the
        # cache. Otherwise, expire the cache of references *to* this field.
        # The mechanism for getting at the related model is slightly odd -
        # ideally, we'd just ask for field.related_model. However, related_model
        # is a cached property, and all the models haven't been loaded yet, so
        # we need to make sure we don't cache a string reference.
        if field.is_relation and hasattr(field.rel, 'to') and field.rel.to:
            try:
                field.rel.to._meta._expire_cache(forward=False)
            except AttributeError:
                pass
            self._expire_cache()
        else:
            self._expire_cache(reverse=False)

    def setup_pk(self, field):
        if not self.pk and field.primary_key:
            self.pk = field
            field.serialize = False

    def setup_proxy(self, target):
        """
        Does the internal setup so that the current model is a proxy for
        "target".
        """
        self.pk = target._meta.pk
        self.proxy_for_model = target
        self.db_table = target._meta.db_table

    def __repr__(self):
        return '<Options for %s>' % self.object_name

    def __str__(self):
        return "%s.%s" % (smart_text(self.app_label), smart_text(self.model_name))

    @property
    def verbose_name_raw(self):
        """
        There are a few places where the untranslated verbose name is needed
        (so that we get the same value regardless of currently active
        locale).
        """
        with override(None):
            return force_text(self.verbose_name)

    @property
    def swapped(self):
        """
        Has this model been swapped out for another? If so, return the model
        name of the replacement; otherwise, return None.

        For historical reasons, model name lookups using get_model() are
        case insensitive, so we make sure we are case insensitive here.
        """
        if self.swappable:
            model_label = '%s.%s' % (self.app_label, self.model_name)
            swapped_for = getattr(settings, self.swappable, None)
            if swapped_for:
                try:
                    swapped_label, swapped_object = swapped_for.split('.')
                except ValueError:
                    # setting not in the format app_label.model_name
                    # raising ImproperlyConfigured here causes problems with
                    # test cleanup code - instead it is raised in get_user_model
                    # or as part of validation.
                    return swapped_for

                if '%s.%s' % (swapped_label, swapped_object.lower()) not in (None, model_label):
                    return swapped_for
        return None

    @cached_property
    def fields(self):
        """
        Returns a list of all forward fields on the model and its parents,
        excluding ManyToManyFields.

        Private API intended only to be used by Django itself; get_fields()
        combined with filtering of field properties is the public API for
        obtaining this field list.
        """
        # For legacy reasons, the fields property should only contain forward
        # fields that are not virtual or with a m2m cardinality. Therefore we
        # pass these three filters as filters to the generator.
        # The third lambda is a longwinded way of checking f.related_model - we don't
        # use that property directly because related_model is a cached property,
        # and all the models may not have been loaded yet; we don't want to cache
        # the string reference to the related_model.
        is_not_an_m2m_field = lambda f: not (f.is_relation and f.many_to_many)
        is_not_a_generic_relation = lambda f: not (f.is_relation and f.one_to_many)
        is_not_a_generic_foreign_key = lambda f: not (
            f.is_relation and f.many_to_one and not (hasattr(f.rel, 'to') and f.rel.to)
        )
        return make_immutable_fields_list(
            "fields",
            (f for f in self._get_fields(reverse=False) if
            is_not_an_m2m_field(f) and is_not_a_generic_relation(f)
            and is_not_a_generic_foreign_key(f))
        )

    @cached_property
    def concrete_fields(self):
        """
        Returns a list of all concrete fields on the model and its parents.

        Private API intended only to be used by Django itself; get_fields()
        combined with filtering of field properties is the public API for
        obtaining this field list.
        """
        return make_immutable_fields_list(
            "concrete_fields", (f for f in self.fields if f.concrete)
        )

    @cached_property
    def local_concrete_fields(self):
        """
        Returns a list of all concrete fields on the model.

        Private API intended only to be used by Django itself; get_fields()
        combined with filtering of field properties is the public API for
        obtaining this field list.
        """
        return make_immutable_fields_list(
            "local_concrete_fields", (f for f in self.local_fields if f.concrete)
        )

    @raise_deprecation(suggested_alternative="get_fields()")
    def get_fields_with_model(self):
        return [self._map_model(f) for f in self.get_fields()]

    @raise_deprecation(suggested_alternative="get_fields()")
    def get_concrete_fields_with_model(self):
        return [self._map_model(f) for f in self.concrete_fields]

    @cached_property
    def many_to_many(self):
        """
        Returns a list of all many to many fields on the model and its parents.

        Private API intended only to be used by Django itself; get_fields()
        combined with filtering of field properties is the public API for
        obtaining this list.
        """
        return make_immutable_fields_list(
            "many_to_many",
            (f for f in self._get_fields(reverse=False)
            if f.is_relation and f.many_to_many)
        )

    @cached_property
    def related_objects(self):
        """
        Returns all related objects pointing to the current model. The related
        objects can come from a one-to-one, one-to-many, or many-to-many field
        relation type.

        Private API intended only to be used by Django itself; get_fields()
        combined with filtering of field properties is the public API for
        obtaining this field list.
        """
        all_related_fields = self._get_fields(forward=False, reverse=True, include_hidden=True)
        return make_immutable_fields_list(
            "related_objects",
            (obj for obj in all_related_fields
            if not obj.hidden or obj.field.many_to_many)
        )

    @raise_deprecation(suggested_alternative="get_fields()")
    def get_m2m_with_model(self):
        return [self._map_model(f) for f in self.many_to_many]

    @cached_property
    def _forward_fields_map(self):
        res = {}
        fields = self._get_fields(reverse=False)
        for field in fields:
            res[field.name] = field
            # Due to the way Django's internals work, get_field() should also
            # be able to fetch a field by attname. In the case of a concrete
            # field with relation, includes the *_id name too
            try:
                res[field.attname] = field
            except AttributeError:
                pass
        return res

    @cached_property
    def fields_map(self):
        res = {}
        fields = self._get_fields(forward=False, include_hidden=True)
        for field in fields:
            res[field.name] = field
            # Due to the way Django's internals work, get_field() should also
            # be able to fetch a field by attname. In the case of a concrete
            # field with relation, includes the *_id name too
            try:
                res[field.attname] = field
            except AttributeError:
                pass
        return res

    def get_field(self, field_name, many_to_many=None):
        """
        Returns a field instance given a field name. The field can be either a
        forward or reverse field, unless many_to_many is specified; if it is,
        only forward fields will be returned.

        The many_to_many argument exists for backwards compatibility reasons;
        it has been deprecated and will be removed in Django 2.0.
        """
        m2m_in_kwargs = many_to_many is not None
        if m2m_in_kwargs:
            # Always throw a warning if many_to_many is used regardless of
            # whether it alters the return type or not.
            warnings.warn(
                "The 'many_to_many' argument on get_field() is deprecated; "
                "use a filter on field.many_to_many instead.",
                RemovedInDjango20Warning
            )

        try:
            # In order to avoid premature loading of the relation tree
            # (expensive) we prefer checking if the field is a forward field.
            field = self._forward_fields_map[field_name]

            if many_to_many is False and field.many_to_many:
                raise FieldDoesNotExist(
                    '%s has no field named %r' % (self.object_name, field_name)
                )

            return field
        except KeyError:
            # If the app registry is not ready, reverse fields are
            # unavailable, therefore we throw a FieldDoesNotExist exception.
            if not self.apps.models_ready:
                raise FieldDoesNotExist(
                    "%s has no field named %r. The app cache isn't ready yet, "
                    "so if this is an auto-created related field, it won't "
                    "be available yet." % (self.object_name, field_name)
                )

        try:
            if m2m_in_kwargs:
                # Previous API does not allow searching reverse fields.
                raise FieldDoesNotExist('%s has no field named %r' % (self.object_name, field_name))

            # Retrieve field instance by name from cached or just-computed
            # field map.
            return self.fields_map[field_name]
        except KeyError:
            raise FieldDoesNotExist('%s has no field named %r' % (self.object_name, field_name))

    @raise_deprecation(suggested_alternative="get_field()")
    def get_field_by_name(self, name):
        return self._map_model_details(self.get_field(name))

    @raise_deprecation(suggested_alternative="get_fields()")
    def get_all_field_names(self):
        names = set()
        fields = self.get_fields()
        for field in fields:
            # For backwards compatibility GenericForeignKey should not be
            # included in the results.
            if field.is_relation and field.many_to_one and field.related_model is None:
                continue
            # Relations to child proxy models should not be included.
            if (field.model != self.model and
                    field.model._meta.concrete_model == self.concrete_model):
                continue

            names.add(field.name)
            if hasattr(field, 'attname'):
                names.add(field.attname)
        return list(names)

    @raise_deprecation(suggested_alternative="get_fields()")
    def get_all_related_objects(self, local_only=False, include_hidden=False,
                                include_proxy_eq=False):

        include_parents = True if local_only is False else PROXY_PARENTS
        fields = self._get_fields(
            forward=False, reverse=True,
            include_parents=include_parents,
            include_hidden=include_hidden,
        )
        fields = (obj for obj in fields if not isinstance(obj.field, ManyToManyField))
        if include_proxy_eq:
            children = chain.from_iterable(c._relation_tree
                                           for c in self.concrete_model._meta.proxied_children
                                           if c is not self)
            relations = (f.rel for f in children
                         if include_hidden or not f.rel.field.rel.is_hidden())
            fields = chain(fields, relations)
        return list(fields)

    @raise_deprecation(suggested_alternative="get_fields()")
    def get_all_related_objects_with_model(self, local_only=False, include_hidden=False,
                                           include_proxy_eq=False):
        return [
            self._map_model(f) for f in self.get_all_related_objects(
                local_only=local_only,
                include_hidden=include_hidden,
                include_proxy_eq=include_proxy_eq,
            )
        ]

    @raise_deprecation(suggested_alternative="get_fields()")
    def get_all_related_many_to_many_objects(self, local_only=False):
        include_parents = True if local_only is not True else PROXY_PARENTS
        fields = self._get_fields(
            forward=False, reverse=True,
            include_parents=include_parents, include_hidden=True
        )
        return [obj for obj in fields if isinstance(obj.field, ManyToManyField)]

    @raise_deprecation(suggested_alternative="get_fields()")
    def get_all_related_m2m_objects_with_model(self):
        fields = self._get_fields(forward=False, reverse=True, include_hidden=True)
        return [self._map_model(obj) for obj in fields if isinstance(obj.field, ManyToManyField)]

    def get_base_chain(self, model):
        """
        Returns a list of parent classes leading to 'model' (order from closet
        to most distant ancestor). This has to handle the case were 'model' is
        a grandparent or even more distant relation.
        """
        if not self.parents:
            return None
        if model in self.parents:
            return [model]
        for parent in self.parents:
            res = parent._meta.get_base_chain(model)
            if res:
                res.insert(0, parent)
                return res
        return None

    def get_parent_list(self):
        """
        Returns all the ancestors of this model as a list ordered by MRO.
        Useful for determining if something is an ancestor, regardless of lineage.
        """
        result = OrderedSet(self.parents)
        for parent in self.parents:
            for ancestor in parent._meta.get_parent_list():
                result.add(ancestor)
        return list(result)

    def get_ancestor_link(self, ancestor):
        """
        Returns the field on the current model which points to the given
        "ancestor". This is possible an indirect link (a pointer to a parent
        model, which points, eventually, to the ancestor). Used when
        constructing table joins for model inheritance.

        Returns None if the model isn't an ancestor of this one.
        """
        if ancestor in self.parents:
            return self.parents[ancestor]
        for parent in self.parents:
            # Tries to get a link field from the immediate parent
            parent_link = parent._meta.get_ancestor_link(ancestor)
            if parent_link:
                # In case of a proxied model, the first link
                # of the chain to the ancestor is that parent
                # links
                return self.parents[parent] or parent_link

    def _populate_directed_relation_graph(self):
        """
        This method is used by each model to find its reverse objects. As this
        method is very expensive and is accessed frequently (it looks up every
        field in a model, in every app), it is computed on first access and then
        is set as a property on every model.
        """
        related_objects_graph = defaultdict(list)

        all_models = self.apps.get_models(include_auto_created=True)
        for model in all_models:
            # Abstract model's fields are copied to child models, hence we will
            # see the fields from the child models.
            if model._meta.abstract:
                continue
            fields_with_relations = (
                f for f in model._meta._get_fields(reverse=False, include_parents=False)
                if f.is_relation and f.related_model is not None
            )
            for f in fields_with_relations:
                if not isinstance(f.rel.to, six.string_types):
                    related_objects_graph[f.rel.to._meta].append(f)

        for model in all_models:
            # Set the relation_tree using the internal __dict__. In this way
            # we avoid calling the cached property. In attribute lookup,
            # __dict__ takes precedence over a data descriptor (such as
            # @cached_property). This means that the _meta._relation_tree is
            # only called if related_objects is not in __dict__.
            related_objects = related_objects_graph[model._meta]
            model._meta.__dict__['_relation_tree'] = related_objects
        # It seems it is possible that self is not in all_models, so guard
        # against that with default for get().
        return self.__dict__.get('_relation_tree', EMPTY_RELATION_TREE)

    @cached_property
    def _relation_tree(self):
        return self._populate_directed_relation_graph()

    def _expire_cache(self, forward=True, reverse=True):
        # This method is usually called by apps.cache_clear(), when the
        # registry is finalized, or when a new field is added.
        properties_to_expire = []
        if forward:
            properties_to_expire.extend(self.FORWARD_PROPERTIES)
        if reverse and not self.abstract:
            properties_to_expire.extend(self.REVERSE_PROPERTIES)

        for cache_key in properties_to_expire:
            try:
                delattr(self, cache_key)
            except AttributeError:
                pass

        self._get_fields_cache = {}

    def get_fields(self, include_parents=True, include_hidden=False):
        """
        Returns a list of fields associated to the model. By default, includes
        forward and reverse fields, fields derived from inheritance, but not
        hidden fields. The returned fields can be changed using the parameters:

        - include_parents: include fields derived from inheritance
        - include_hidden:  include fields that have a related_name that
                           starts with a "+"
        """
        if include_parents is False:
            include_parents = PROXY_PARENTS
        return self._get_fields(include_parents=include_parents, include_hidden=include_hidden)

    def _get_fields(self, forward=True, reverse=True, include_parents=True, include_hidden=False,
                    seen_models=None):
        """
        Internal helper function to return fields of the model.
        * If forward=True, then fields defined on this model are returned.
        * If reverse=True, then relations pointing to this model are returned.
        * If include_hidden=True, then fields with is_hidden=True are returned.
        * The include_parents argument toggles if fields from parent models
          should be included. It has three values: True, False, and
          PROXY_PARENTS. When set to PROXY_PARENTS, the call will return all
          fields defined for the current model or any of its parents in the
          parent chain to the model's concrete model.
        """
        if include_parents not in (True, False, PROXY_PARENTS):
            raise TypeError("Invalid argument for include_parents: %s" % (include_parents,))
        # This helper function is used to allow recursion in ``get_fields()``
        # implementation and to provide a fast way for Django's internals to
        # access specific subsets of fields.

        # We must keep track of which models we have already seen. Otherwise we
        # could include the same field multiple times from different models.
        topmost_call = False
        if seen_models is None:
            seen_models = set()
            topmost_call = True
        seen_models.add(self.model)

        # Creates a cache key composed of all arguments
        cache_key = (forward, reverse, include_parents, include_hidden, topmost_call)

        try:
            # In order to avoid list manipulation. Always return a shallow copy
            # of the results.
            return self._get_fields_cache[cache_key]
        except KeyError:
            pass

        fields = []
        # Recursively call _get_fields() on each parent, with the same
        # options provided in this call.
        if include_parents is not False:
            for parent in self.parents:
                # In diamond inheritance it is possible that we see the same
                # model from two different routes. In that case, avoid adding
                # fields from the same parent again.
                if parent in seen_models:
                    continue
                if (parent._meta.concrete_model != self.concrete_model and
                        include_parents == PROXY_PARENTS):
                    continue
                for obj in parent._meta._get_fields(
                        forward=forward, reverse=reverse, include_parents=include_parents,
                        include_hidden=include_hidden, seen_models=seen_models):
                    if hasattr(obj, 'parent_link') and obj.parent_link:
                        continue
                    fields.append(obj)
        if reverse:
            # Tree is computed once and cached until the app cache is expired.
            # It is composed of a list of fields pointing to the current model
            # from other models.
            all_fields = self._relation_tree
            for field in all_fields:
                # If hidden fields should be included or the relation is not
                # intentionally hidden, add to the fields dict.
                if include_hidden or not field.rel.hidden:
                    fields.append(field.rel)

        if forward:
            fields.extend(
                field for field in chain(self.local_fields, self.local_many_to_many)
            )
            # Virtual fields are recopied to each child model, and they get a
            # different model as field.model in each child. Hence we have to
            # add the virtual fields separately from the topmost call. If we
            # did this recursively similar to local_fields, we would get field
            # instances with field.model != self.model.
            if topmost_call:
                fields.extend(
                    f for f in self.virtual_fields
                )

        # In order to avoid list manipulation. Always
        # return a shallow copy of the results
        fields = make_immutable_fields_list("get_fields()", fields)

        # Store result into cache for later access
        self._get_fields_cache[cache_key] = fields
        return fields

def get_or_create(self, defaults=None, **kwargs):
    """
    Looks up an object with the given kwargs, creating one if necessary.
    Returns a tuple of (object, created), where created is a boolean
    specifying whether an object was created.
    """
    lookup, params = self._extract_model_params(defaults, **kwargs)
    self._for_write = True
    try:
        return self.get(**lookup), False
    except self.model.DoesNotExist:
        return self._create_object_from_params(lookup, params)

def __set__(self, instance, value):
    # The similarity of the code below to the code in
    # ReverseSingleRelatedObjectDescriptor is annoying, but there's a bunch
    # of small differences that would make a common base class convoluted.

    # If null=True, we can assign null here, but otherwise the value needs
    # to be an instance of the related class.
    if value is None and self.related.field.null is False:
        raise ValueError(
            'Cannot assign None: "%s.%s" does not allow null values.' % (
                instance._meta.object_name,
                self.related.get_accessor_name(),
            )
        )
    elif value is not None and not isinstance(value, self.related.related_model):
        raise ValueError(
            'Cannot assign "%r": "%s.%s" must be a "%s" instance.' % (
                value,
                instance._meta.object_name,
                self.related.get_accessor_name(),
                self.related.related_model._meta.object_name,
            )
        )
    elif value is not None:
        if instance._state.db is None:
            instance._state.db = router.db_for_write(instance.__class__, instance=value)
        elif value._state.db is None:
            value._state.db = router.db_for_write(value.__class__, instance=instance)
        elif value._state.db is not None and instance._state.db is not None:
            if not router.allow_relation(value, instance):
                raise ValueError('Cannot assign "%r": the current database router prevents this relation.' % value)

    related_pk = tuple(getattr(instance, field.attname) for field in self.related.field.foreign_related_fields)
    if not self.related.field.allow_unsaved_instance_assignment and None in related_pk:
        raise ValueError(
            'Cannot assign "%r": "%s" instance isn\'t saved in the database.' %
            (value, instance._meta.object_name)
        )

    # Set the value of the related field to the value of the related object's related field
    for index, field in enumerate(self.related.field.local_related_fields):
        setattr(value, field.attname, related_pk[index])

    # Since we already know what the related object is, seed the related
    # object caches now, too. This avoids another db hit if you get the
    # object you just set.
    setattr(instance, self.cache_name, value)
    setattr(value, self.related.field.get_cache_name(), instance)

def get_queryset(self):
    try:
        return self.instance._prefetched_objects_cache[self.prefetch_cache_name]
    except (AttributeError, KeyError):
        qs = super(ManyRelatedManager, self).get_queryset()
        qs._add_hints(instance=self.instance)
        if self._db:
            qs = qs.using(self._db)
        return qs._next_is_sticky().filter(**self.core_filters)

def get_accessor_name(self, model=None):
    # This method encapsulates the logic that decides what name to give an
    # accessor descriptor that retrieves related many-to-one or
    # many-to-many objects. It uses the lower-cased object_name + "_set",
    # but this can be overridden with the "related_name" option.
    # Due to backwards compatibility ModelForms need to be able to provide
    # an alternate model. See BaseInlineFormSet.get_default_prefix().
    opts = model._meta if model else self.related_model._meta
    model = model or self.related_model
    if self.multiple:
        # If this is a symmetrical m2m relation on self, there is no reverse accessor.
        if self.symmetrical and model == self.to:
            return None
    if self.related_name:
        return self.related_name
    if opts.default_related_name:
        return opts.default_related_name % {
            'model_name': opts.model_name.lower(),
            'app_label': opts.app_label.lower(),
        }
    return opts.model_name + ('_set' if self.multiple else '')

def contribute_to_related_class(self, cls, related):
    # Internal FK's - i.e., those with a related name ending with '+' -
    # and swapped models don't get a related descriptor.
    if not self.rel.is_hidden() and not related.related_model._meta.swapped:
        setattr(cls, related.get_accessor_name(), self.related_accessor_class(related))
        # While 'limit_choices_to' might be a callable, simply pass
        # it along for later - this is too early because it's still
        # model load time.
        if self.rel.limit_choices_to:
            cls._meta.related_fkey_lookups.append(self.rel.limit_choices_to)

def _get_m2m_reverse_attr(self, related, attr):
    "Function that can be curried to provide the related accessor or DB column name for the m2m table"
    cache_attr = '_m2m_reverse_%s_cache' % attr
    if hasattr(self, cache_attr):
        return getattr(self, cache_attr)
    found = False
    if self.rel.through_fields is not None:
        link_field_name = self.rel.through_fields[1]
    else:
        link_field_name = None
    for f in self.rel.through._meta.fields:
        # NOTE f.rel.to != f.related_model
        if f.is_relation and f.rel.to == related.model:
            if link_field_name is None and related.related_model == related.model:
                # If this is an m2m-intermediate to self,
                # the first foreign key you find will be
                # the source column. Keep searching for
                # the second foreign key.
                if found:
                    setattr(self, cache_attr, getattr(f, attr))
                    break
                else:
                    found = True
            elif link_field_name is None or link_field_name == f.name:
                setattr(self, cache_attr, getattr(f, attr))
                break
    return getattr(self, cache_attr)

def get_select_from_parent(klass_info):
    for ki in klass_info['related_klass_infos']:
        if ki['from_parent']:
            ki['select_fields'] = (klass_info['select_fields'] +
                                   ki['select_fields'])
        get_select_from_parent(ki)

def css_classes(self, extra_classes=None):
    """
    Returns a string of space-separated CSS classes for this field.
    """
    if hasattr(extra_classes, 'split'):
        extra_classes = extra_classes.split()
    extra_classes = set(extra_classes or [])
    if self.errors and hasattr(self.form, 'error_css_class'):
        extra_classes.add(self.form.error_css_class)
    if self.field.required and hasattr(self.form, 'required_css_class'):
        extra_classes.add(self.form.required_css_class)
    return ' '.join(extra_classes)

def add_fields(self, form, index):
    """Add a hidden field for the object's primary key."""
    from django.db.models import AutoField, OneToOneField, ForeignKey
    self._pk_field = pk = self.model._meta.pk
    # If a pk isn't editable, then it won't be on the form, so we need to
    # add it here so we can tell which object is which when we get the
    # data back. Generally, pk.editable should be false, but for some
    # reason, auto_created pk fields and AutoField's editable attribute is
    # True, so check for that as well.

    def pk_is_not_editable(pk):
        return ((not pk.editable) or (pk.auto_created or isinstance(pk, AutoField))
            or (pk.rel and pk.rel.parent_link and pk_is_not_editable(pk.rel.to._meta.pk)))
    if pk_is_not_editable(pk) or pk.name not in form.fields:
        if form.is_bound:
            # If we're adding the related instance, ignore its primary key
            # as it could be an auto-generated default which isn't actually
            # in the database.
            pk_value = None if form.instance._state.adding else form.instance.pk
        else:
            try:
                if index is not None:
                    pk_value = self.get_queryset()[index].pk
                else:
                    pk_value = None
            except IndexError:
                pk_value = None
        if isinstance(pk, OneToOneField) or isinstance(pk, ForeignKey):
            qs = pk.rel.to._default_manager.get_queryset()
        else:
            qs = self.model._default_manager.get_queryset()
        qs = qs.using(form.instance._state.db)
        if form._meta.widgets:
            widget = form._meta.widgets.get(self._pk_field.name, HiddenInput)
        else:
            widget = HiddenInput
        form.fields[self._pk_field.name] = ModelChoiceField(qs, initial=pk_value, required=False, widget=widget)
    super(BaseModelFormSet, self).add_fields(form, index)

def add_fields(self, form, index):
    super(BaseInlineFormSet, self).add_fields(form, index)
    if self._pk_field == self.fk:
        name = self._pk_field.name
        kwargs = {'pk_field': True}
    else:
        # The foreign key field might not be on the form, so we poke at the
        # Model field to get the label, since we need that for error messages.
        name = self.fk.name
        kwargs = {
            'label': getattr(form.fields.get(name), 'label', capfirst(self.fk.verbose_name))
        }
        if self.fk.rel.field_name != self.fk.rel.to._meta.pk.name:
            kwargs['to_field'] = self.fk.rel.field_name

    # If we're adding a new object, ignore a parent's auto-generated pk
    # as it will be regenerated on the save request.
    if self.instance._state.adding and form._meta.model._meta.pk.has_default():
        self.instance.pk = None

    form.fields[name] = InlineForeignKeyField(self.instance, **kwargs)

    # Add the generated field to form._meta.fields if it's defined to make
    # sure validation isn't skipped on that field.
    if form._meta.fields:
        if isinstance(form._meta.fields, tuple):
            form._meta.fields = list(form._meta.fields)
        form._meta.fields.append(self.fk.name)

