def _get_output_fourier_complex(output, input):
    if output is None:
        if input.dtype.type in [numpy.complex64, numpy.complex128]:
            output = numpy.zeros(input.shape, dtype=input.dtype)
        else:
            output = numpy.zeros(input.shape, dtype=numpy.complex128)
        return_value = output
    elif type(output) is type:
        if output not in [numpy.complex64, numpy.complex128]:
            raise RuntimeError("output type not supported")
        output = numpy.zeros(input.shape, dtype=output)
        return_value = output
    else:
        if output.shape != input.shape:
            raise RuntimeError("output shape not correct")
        return_value = None
    return output, return_value

def set_shape(self,shape):
    shape = tuple(shape)

    if len(shape) != 2:
        raise ValueError("Only two-dimensional sparse arrays "
                                 "are supported.")
    try:
        shape = int(shape[0]),int(shape[1])  # floats, other weirdness
    except:
        raise TypeError('invalid shape')

    if not (shape[0] >= 0 and shape[1] >= 0):
        raise ValueError('invalid shape')

    if (self._shape != shape) and (self._shape is not None):
        try:
            self = self.reshape(shape)
        except NotImplementedError:
            raise NotImplementedError("Reshaping not implemented for %s." %
                                      self.__class__.__name__)
    self._shape = shape

