def bucket_lister(bucket, prefix='', delimiter='', marker='', headers=None,
                  encoding_type=None):
    """
    A generator function for listing keys in a bucket.
    """
    more_results = True
    k = None
    while more_results:
        rs = bucket.get_all_keys(prefix=prefix, marker=marker,
                                 delimiter=delimiter, headers=headers,
                                 encoding_type=encoding_type)
        for k in rs:
            yield k
        if k:
            marker = rs.next_marker or k.name
        if marker and encoding_type == "url":
            if isinstance(marker, six.text_type):
                marker = marker.encode('utf-8')
            marker = urllib.parse.unquote(marker)
        more_results= rs.is_truncated

def _build_filter(self, property, name, op, val):
    if name == "__id__":
        name = 'itemName()'
    if name != "itemName()":
        name = '`%s`' % name
    if val is None:
        if op in ('is', '='):
            return "%(name)s is null" % {"name": name}
        elif op in ('is not', '!='):
            return "%s is not null" % name
        else:
            val = ""
    if property.__class__ == ListProperty:
        if op in ("is", "="):
            op = "like"
        elif op in ("!=", "not"):
            op = "not like"
        if not(op in ["like", "not like"] and val.startswith("%")):
            val = "%%:%s" % val
    return "%s %s '%s'" % (name, op, val.replace("'", "''"))

def wrapper(cls):
    orig_vars = cls.__dict__.copy()
    orig_vars.pop('__dict__', None)
    orig_vars.pop('__weakref__', None)
    slots = orig_vars.get('__slots__')
    if slots is not None:
        if isinstance(slots, str):
            slots = [slots]
        for slots_var in slots:
            orig_vars.pop(slots_var)
    return metaclass(cls.__name__, cls.__bases__, orig_vars)

