def update_class(old, new):
    """Replace stuff in the __dict__ of a class, and upgrade
    method code objects"""
    for key in list(old.__dict__.keys()):
        old_obj = getattr(old, key)

        try:
            new_obj = getattr(new, key)
        except AttributeError:
            # obsolete attribute: remove it
            try:
                delattr(old, key)
            except (AttributeError, TypeError):
                pass
            continue

        if update_generic(old_obj, new_obj): continue

        try:
            setattr(old, key, getattr(new, key))
        except (AttributeError, TypeError):
            pass # skip non-writable attributes

def _from_module(self, module, object):
    """
    Return true if the given object is defined in the given
    module.
    """
    if module is None:
        return True
    elif inspect.isfunction(object):
        return module.__dict__ is object.__globals__
    elif inspect.isbuiltin(object):
        return module.__name__ == object.__module__
    elif inspect.isclass(object):
        return module.__name__ == object.__module__
    elif inspect.ismethod(object):
        # This one may be a bug in cython that fails to correctly set the
        # __module__ attribute of methods, but since the same error is easy
        # to make by extension code writers, having this safety in place
        # isn't such a bad idea
        return module.__name__ == object.__self__.__class__.__module__
    elif inspect.getmodule(object) is not None:
        return module is inspect.getmodule(object)
    elif hasattr(object, '__module__'):
        return module.__name__ == object.__module__
    elif isinstance(object, property):
        return True # [XX] no way not be sure.
    elif inspect.ismethoddescriptor(object):
        # Unbound PyQt signals reach this point in Python 3.4b3, and we want
        # to avoid throwing an error. See also http://bugs.python.org/issue3158
        return False
    else:
        raise ValueError("object must be a class or function, got %r" % object)

def parse_meta(config):
    if not config.has_section('meta'):
        raise FormatError("No meta section found !")

    d = {}
    for name, value in config.items('meta'):
        d[name] = value

    for k in ['name', 'description', 'version']:
        if not k in d:
            raise FormatError("Option %s (section [meta]) is mandatory, "
                "but not found" % k)

    if not 'requires' in d:
        d['requires'] = []

    return d

def build_sources(self):

