def _get_submatrix(self, row_slice, col_slice):
    """Return a submatrix of this matrix (new matrix is created)."""

    M,N = self.shape

    def process_slice(sl, num):
        if isinstance(sl, slice):
            if sl.step not in (1, None):
                raise ValueError('slicing with step != 1 not supported')
            i0, i1 = sl.start, sl.stop
            if i0 is None:
                i0 = 0
            elif i0 < 0:
                i0 = num + i0

            if i1 is None:
                i1 = num
            elif i1 < 0:
                i1 = num + i1
            return i0, i1

        elif isintlike(sl):
            if sl < 0:
                sl += num
            return sl, sl + 1
        else:
            raise TypeError('expected slice or scalar')

    def check_bounds(i0, i1, num):
        if not (0 <= i0 <= num) or not (0 <= i1 <= num) or not (i0 <= i1):
            raise IndexError(
                  "index out of bounds: 0 <= %d <= %d, 0 <= %d <= %d,"
                  " %d <= %d" % (i0, num, i1, num, i0, i1))

    i0, i1 = process_slice(row_slice, M)
    j0, j1 = process_slice(col_slice, N)
    check_bounds(i0, i1, M)
    check_bounds(j0, j1, N)

    indptr, indices, data = get_csr_submatrix(M, N,
            self.indptr, self.indices, self.data,
            int(i0), int(i1), int(j0), int(j1))

    shape = (i1 - i0, j1 - j0)

    return self.__class__((data,indices,indptr), shape=shape)

def check_setdiag(a, b, k):
    # Check setting diagonal using a scalar, a vector of
    # correct length, and too short or too long vectors
    for r in [-1, len(np.diag(a, k)), 2, 30]:
        if r < 0:
            v = int(np.random.randint(1, 20, size=1))
        else:
            v = np.random.randint(1, 20, size=r)

        dense_setdiag(a, v, k)
        b.setdiag(v, k)

        # check that dense_setdiag worked
        d = np.diag(a, k)
        if np.asarray(v).ndim == 0:
            assert_array_equal(d, v, err_msg=msg + " %d" % (r,))
        else:
            n = min(len(d), len(v))
            assert_array_equal(d[:n], v[:n], err_msg=msg + " %d" % (r,))
        # check that sparse setdiag worked
        assert_array_equal(b.A, a, err_msg=msg + " %d" % (r,))

def legenq(n, m, z):
    if abs(z) < 1e-15:
        # mpmath has bad performance here
        return np.nan
    return _exception_to_nan(mpmath.legenq)(n, m, z, type=2)

def _sf(self, x, a):
    fac = 0.5*special.gammainc(a, abs(x))
    return where(x > 0, 0.5-fac, 0.5+fac)

def _munp(self, n, c):
    k = arange(0, n+1)
    vals = 1.0/c**n * sum(
        comb(n, k) * (-1)**k * special.gamma(c*k + 1),
        axis=0)
    return where(c*n > -1, vals, inf)

def _cdf(self, x, c):
    xc1 = np.power(x, -c)
    return exp(-xc1)

def _pdf(self, x, b):
    # We use (x**2 + b**2)/2 = ((x-b)**2)/2 + xb.
    # The factor of exp(-xb) is then included in the i0e function
    # in place of the modified Bessel function, i0, improving
    # numerical stability for large values of xb.
    return x * exp(-(x-b)*(x-b)/2.0) * special.i0e(x*b)

def _pmf(self, k, a):
    Pk = 1.0 / special.zeta(a, 1) / k**a
    return Pk

