def __repr__(self):
    res = super(Semaphore, self).__repr__()
    extra = 'locked' if self._value == 0 else 'unlocked,value:{0}'.format(
        self._value)
    if self._waiters:
        extra = '{0},waiters:{1}'.format(extra, len(self._waiters))
    return '<{0} [{1}]>'.format(res[1:-1], extra)

