def __repr__(self):
    """
    A string representation of the token that can reproduce it
    with eval(), which lists all the token's non-default
    annotations.
    """
    typestr = (' type=%s,' % unicode_repr(self.type)
               if self.type != self.tok else '')

    propvals = ', '.join(
        '%s=%s' % (p, unicode_repr(getattr(self, p)))
        for p in self._properties
        if getattr(self, p)
    )

    return '%s(%s,%s %s)' % (self.__class__.__name__,
        unicode_repr(self.tok), typestr, propvals)

def get_fontspec():
    """Build fontspec preamble from rc."""
    latex_fontspec = []
    texcommand = get_texcommand()

    if texcommand != "pdflatex":
        latex_fontspec.append("\\usepackage{fontspec}")

    if texcommand != "pdflatex" and rcParams.get("pgf.rcfonts", True):
        # try to find fonts from rc parameters
        families = ["serif", "sans-serif", "monospace"]
        fontspecs = [r"\setmainfont{%s}", r"\setsansfont{%s}",
                     r"\setmonofont{%s}"]
        for family, fontspec in zip(families, fontspecs):
            matches = [f for f in rcParams["font." + family]
                       if f in system_fonts]
            if matches:
                latex_fontspec.append(fontspec % matches[0])
            else:
                pass  # no fonts found, fallback to LaTeX defaule

    return "\n".join(latex_fontspec)

