def check_for_migrations(app_config, connection):
    # Inner import, else tests imports it too early as it needs settings
    from django.db.migrations.loader import MigrationLoader
    loader = MigrationLoader(connection)
    if app_config.label in loader.migrated_apps:
        raise CommandError(
            "App '%s' has migrations. Only the sqlmigrate and sqlflush commands "
            "can be used when an app has migrations." % app_config.label
        )

def handle_inspection(self, options):
    connection = connections[options['database']]
    # 'table_name_filter' is a stealth option
    table_name_filter = options.get('table_name_filter')

    table2model = lambda table_name: re.sub(r'[^a-zA-Z0-9]', '', table_name.title())
    strip_prefix = lambda s: s[1:] if s.startswith("u'") else s

    with connection.cursor() as cursor:
        yield "# This is an auto-generated Django model module."
        yield "# You'll have to do the following manually to clean this up:"
        yield "#   * Rearrange models' order"
        yield "#   * Make sure each model has one field with primary_key=True"
        yield (
            "#   * Remove `managed = False` lines if you wish to allow "
            "Django to create, modify, and delete the table"
        )
        yield "# Feel free to rename the models, but don't rename db_table values or field names."
        yield "#"
        yield "# Also note: You'll have to insert the output of 'django-admin sqlcustom [app_label]'"
        yield "# into your database."
        yield "from __future__ import unicode_literals"
        yield ''
        yield 'from %s import models' % self.db_module
        known_models = []
        for table_name in connection.introspection.table_names(cursor):
            if table_name_filter is not None and callable(table_name_filter):
                if not table_name_filter(table_name):
                    continue
            yield ''
            yield ''
            yield 'class %s(models.Model):' % table2model(table_name)
            known_models.append(table2model(table_name))
            try:
                relations = connection.introspection.get_relations(cursor, table_name)
            except NotImplementedError:
                relations = {}
            try:
                indexes = connection.introspection.get_indexes(cursor, table_name)
            except NotImplementedError:
                indexes = {}
            try:
                constraints = connection.introspection.get_constraints(cursor, table_name)
            except NotImplementedError:
                constraints = {}
            used_column_names = []  # Holds column names used in the table so far
            for row in connection.introspection.get_table_description(cursor, table_name):
                comment_notes = []  # Holds Field notes, to be displayed in a Python comment.
                extra_params = OrderedDict()  # Holds Field parameters such as 'db_column'.
                column_name = row[0]
                is_relation = column_name in relations

                att_name, params, notes = self.normalize_col_name(
                    column_name, used_column_names, is_relation)
                extra_params.update(params)
                comment_notes.extend(notes)

                used_column_names.append(att_name)

                # Add primary_key and unique, if necessary.
                if column_name in indexes:
                    if indexes[column_name]['primary_key']:
                        extra_params['primary_key'] = True
                    elif indexes[column_name]['unique']:
                        extra_params['unique'] = True

                if is_relation:
                    rel_to = "self" if relations[column_name][1] == table_name else table2model(relations[column_name][1])
                    if rel_to in known_models:
                        field_type = 'ForeignKey(%s' % rel_to
                    else:
                        field_type = "ForeignKey('%s'" % rel_to
                else:
                    # Calling `get_field_type` to get the field type string and any
                    # additional parameters and notes.
                    field_type, field_params, field_notes = self.get_field_type(connection, table_name, row)
                    extra_params.update(field_params)
                    comment_notes.extend(field_notes)

                    field_type += '('

                # Don't output 'id = meta.AutoField(primary_key=True)', because
                # that's assumed if it doesn't exist.
                if att_name == 'id' and extra_params == {'primary_key': True}:
                    if field_type == 'AutoField(':
                        continue
                    elif field_type == 'IntegerField(' and not connection.features.can_introspect_autofield:
                        comment_notes.append('AutoField?')

                # Add 'null' and 'blank', if the 'null_ok' flag was present in the
                # table description.
                if row[6]:  # If it's NULL...
                    if field_type == 'BooleanField(':
                        field_type = 'NullBooleanField('
                    else:
                        extra_params['blank'] = True
                        extra_params['null'] = True

                field_desc = '%s = %s%s' % (
                    att_name,
                    # Custom fields will have a dotted path
                    '' if '.' in field_type else 'models.',
                    field_type,
                )
                if extra_params:
                    if not field_desc.endswith('('):
                        field_desc += ', '
                    field_desc += ', '.join(
                        '%s=%s' % (k, strip_prefix(repr(v)))
                        for k, v in extra_params.items())
                field_desc += ')'
                if comment_notes:
                    field_desc += '  # ' + ' '.join(comment_notes)
                yield '    %s' % field_desc
            for meta_line in self.get_meta(table_name, constraints):
                yield meta_line

def find_fixtures(self, fixture_label):
    """
    Finds fixture files for a given label.
    """
    fixture_name, ser_fmt, cmp_fmt = self.parse_name(fixture_label)
    databases = [self.using, None]
    cmp_fmts = list(self.compression_formats.keys()) if cmp_fmt is None else [cmp_fmt]
    ser_fmts = serializers.get_public_serializer_formats() if ser_fmt is None else [ser_fmt]

    if self.verbosity >= 2:
        self.stdout.write("Loading '%s' fixtures..." % fixture_name)

    if os.path.isabs(fixture_name):
        fixture_dirs = [os.path.dirname(fixture_name)]
        fixture_name = os.path.basename(fixture_name)
    else:
        fixture_dirs = self.fixture_dirs
        if os.path.sep in os.path.normpath(fixture_name):
            fixture_dirs = [os.path.join(dir_, os.path.dirname(fixture_name))
                            for dir_ in fixture_dirs]
            fixture_name = os.path.basename(fixture_name)

    suffixes = ('.'.join(ext for ext in combo if ext)
            for combo in product(databases, ser_fmts, cmp_fmts))
    targets = set('.'.join((fixture_name, suffix)) for suffix in suffixes)

    fixture_files = []
    for fixture_dir in fixture_dirs:
        if self.verbosity >= 2:
            self.stdout.write("Checking %s for fixtures..." % humanize(fixture_dir))
        fixture_files_in_dir = []
        for candidate in glob.iglob(os.path.join(fixture_dir, fixture_name + '*')):
            if os.path.basename(candidate) in targets:
                # Save the fixture_dir and fixture_name for future error messages.
                fixture_files_in_dir.append((candidate, fixture_dir, fixture_name))

        if self.verbosity >= 2 and not fixture_files_in_dir:
            self.stdout.write("No fixture '%s' in %s." %
                              (fixture_name, humanize(fixture_dir)))

        # Check kept for backwards-compatibility; it isn't clear why
        # duplicates are only allowed in different directories.
        if len(fixture_files_in_dir) > 1:
            raise CommandError(
                "Multiple fixtures named '%s' in %s. Aborting." %
                (fixture_name, humanize(fixture_dir)))
        fixture_files.extend(fixture_files_in_dir)

    if fixture_name != 'initial_data' and not fixture_files:
        # Warning kept for backwards-compatibility; why not an exception?
        warnings.warn("No fixture named '%s' found." % fixture_name)
    elif fixture_name == 'initial_data' and fixture_files:
        warnings.warn(
            'initial_data fixtures are deprecated. Use data migrations instead.',
            RemovedInDjango19Warning
        )

    return fixture_files

def find_fixtures(self, fixture_label):
    """
