def migration_progress_callback(self, action, migration=None, fake=False):
    if self.verbosity >= 1:
        compute_time = self.verbosity > 1
        if action == "apply_start":
            if compute_time:
                self.start = time.time()
            self.stdout.write("  Applying %s..." % migration, ending="")
            self.stdout.flush()
        elif action == "apply_success":
            elapsed = " (%.3fs)" % (time.time() - self.start) if compute_time else ""
            if fake:
                self.stdout.write(self.style.MIGRATE_SUCCESS(" FAKED" + elapsed))
            else:
                self.stdout.write(self.style.MIGRATE_SUCCESS(" OK" + elapsed))
        elif action == "unapply_start":
            if compute_time:
                self.start = time.time()
            self.stdout.write("  Unapplying %s..." % migration, ending="")
            self.stdout.flush()
        elif action == "unapply_success":
            elapsed = " (%.3fs)" % (time.time() - self.start) if compute_time else ""
            if fake:
                self.stdout.write(self.style.MIGRATE_SUCCESS(" FAKED" + elapsed))
            else:
                self.stdout.write(self.style.MIGRATE_SUCCESS(" OK" + elapsed))
        elif action == "render_start":
            if compute_time:
                self.start = time.time()
            self.stdout.write("  Rendering model states...", ending="")
            self.stdout.flush()
        elif action == "render_success":
            elapsed = " (%.3fs)" % (time.time() - self.start) if compute_time else ""
            self.stdout.write(self.style.MIGRATE_SUCCESS(" DONE" + elapsed))

def _get_app_label_and_model_name(model, app_label=''):
    if isinstance(model, six.string_types):
        split = model.split('.', 1)
        return (tuple(split) if len(split) == 2 else (app_label, split[0]))
    else:
        return model._meta.app_label, model._meta.model_name

def _parse_expressions(self, *expressions):
    return [
        arg if hasattr(arg, 'resolve_expression') else (
            F(arg) if isinstance(arg, six.string_types) else Value(arg)
        ) for arg in expressions
    ]

