def _add_items(self, source_field_name, target_field_name, *objs):
    # source_field_name: the PK fieldname in join table for the source object
    # target_field_name: the PK fieldname in join table for the target object
    # *objs - objects to add. Either object instances, or primary keys of object instances.

    # If there aren't any objects, there is nothing to do.
    from django.db.models import Model
    if objs:
        new_ids = set()
        for obj in objs:
            if isinstance(obj, self.model):
                if not router.allow_relation(obj, self.instance):
                    raise ValueError(
                        'Cannot add "%r": instance is on database "%s", value is on database "%s"' %
                        (obj, self.instance._state.db, obj._state.db)
                    )
                fk_val = self.through._meta.get_field(
                    target_field_name).get_foreign_related_value(obj)[0]
                if fk_val is None:
                    raise ValueError(
                        'Cannot add "%r": the value for field "%s" is None' %
                        (obj, target_field_name)
                    )
                new_ids.add(fk_val)
            elif isinstance(obj, Model):
                raise TypeError(
                    "'%s' instance expected, got %r" %
                    (self.model._meta.object_name, obj)
                )
            else:
                new_ids.add(obj)

        db = router.db_for_write(self.through, instance=self.instance)
        vals = (self.through._default_manager.using(db)
                .values_list(target_field_name, flat=True)
                .filter(**{
                    source_field_name: self.related_val[0],
                    '%s__in' % target_field_name: new_ids,
                }))
        new_ids = new_ids - set(vals)

        with transaction.atomic(using=db, savepoint=False):
            if self.reverse or source_field_name == self.source_field_name:
                # Don't send the signal when we are inserting the
                # duplicate data row for symmetrical reverse entries.
                signals.m2m_changed.send(sender=self.through, action='pre_add',
                    instance=self.instance, reverse=self.reverse,
                    model=self.model, pk_set=new_ids, using=db)

            # Add the ones that aren't there already
            self.through._default_manager.using(db).bulk_create([
                self.through(**{
                    '%s_id' % source_field_name: self.related_val[0],
                    '%s_id' % target_field_name: obj_id,
                })
                for obj_id in new_ids
            ])

            if self.reverse or source_field_name == self.source_field_name:
                # Don't send the signal when we are inserting the
                # duplicate data row for symmetrical reverse entries.
                signals.m2m_changed.send(sender=self.through, action='post_add',
                    instance=self.instance, reverse=self.reverse,
                    model=self.model, pk_set=new_ids, using=db)

def get_lookup_constraint(self, constraint_class, alias, targets, sources, lookups,
                          raw_value):
    from django.db.models.sql.where import SubqueryConstraint, AND, OR
    root_constraint = constraint_class()
    assert len(targets) == len(sources)
    if len(lookups) > 1:
        raise exceptions.FieldError('Relation fields do not support nested lookups')
    lookup_type = lookups[0]

    def get_normalized_value(value):
        from django.db.models import Model
        if isinstance(value, Model):
            value_list = []
            for source in sources:
                # Account for one-to-one relations when sent a different model
                while not isinstance(value, source.model) and source.rel:
                    source = source.rel.to._meta.get_field(source.rel.field_name)
                value_list.append(getattr(value, source.attname))
            return tuple(value_list)
        elif not isinstance(value, tuple):
            return (value,)
        return value

    is_multicolumn = len(self.related_fields) > 1
    if (hasattr(raw_value, '_as_sql') or
            hasattr(raw_value, 'get_compiler')):
        root_constraint.add(SubqueryConstraint(alias, [target.column for target in targets],
                                               [source.name for source in sources], raw_value),
                            AND)
    elif lookup_type == 'isnull':
        root_constraint.add(IsNull(targets[0].get_col(alias, sources[0]), raw_value), AND)
    elif (lookup_type == 'exact' or (lookup_type in ['gt', 'lt', 'gte', 'lte']
                                     and not is_multicolumn)):
        value = get_normalized_value(raw_value)
        for target, source, val in zip(targets, sources, value):
            lookup_class = target.get_lookup(lookup_type)
            root_constraint.add(
                lookup_class(target.get_col(alias, source), val), AND)
    elif lookup_type in ['range', 'in'] and not is_multicolumn:
        values = [get_normalized_value(value) for value in raw_value]
        value = [val[0] for val in values]
        lookup_class = targets[0].get_lookup(lookup_type)
        root_constraint.add(lookup_class(targets[0].get_col(alias, sources[0]), value), AND)
    elif lookup_type == 'in':
        values = [get_normalized_value(value) for value in raw_value]
        for value in values:
            value_constraint = constraint_class()
            for source, target, val in zip(sources, targets, value):
                lookup_class = target.get_lookup('exact')
                lookup = lookup_class(target.get_col(alias, source), val)
                value_constraint.add(lookup, AND)
            root_constraint.add(value_constraint, OR)
    else:
        raise TypeError('Related Field got invalid lookup: %s' % lookup_type)
    return root_constraint

def get_choices(self, include_blank=True, blank_choice=BLANK_CHOICE_DASH, limit_choices_to=None):
    """Returns choices with a default blank choices included, for use
    as SelectField choices for this field."""
    blank_defined = False
    choices = list(self.choices) if self.choices else []
    named_groups = choices and isinstance(choices[0][1], (list, tuple))
    if not named_groups:
        for choice, __ in choices:
            if choice in ('', None):
                blank_defined = True
                break

    first_choice = (blank_choice if include_blank and
                    not blank_defined else [])
    if self.choices:
        return first_choice + choices
    rel_model = self.rel.to
    limit_choices_to = limit_choices_to or self.get_limit_choices_to()
    if hasattr(self.rel, 'get_related_field'):
        lst = [(getattr(x, self.rel.get_related_field().attname),
               smart_text(x))
               for x in rel_model._default_manager.complex_filter(
                   limit_choices_to)]
    else:
        lst = [(x._get_pk_val(), smart_text(x))
               for x in rel_model._default_manager.complex_filter(
                   limit_choices_to)]
    return first_choice + lst

def get_db_prep_value(self, value, connection, prepared=False):
    if isinstance(value, six.string_types):
        value = uuid.UUID(value.replace('-', ''))
    if isinstance(value, uuid.UUID):
        if connection.features.has_native_uuid_field:
            return value
        return value.hex
    return value

def deferred_to_data(self, target, callback):
    """
    Converts the self.deferred_loading data structure to an alternate data
    structure, describing the field that *will* be loaded. This is used to
    compute the columns to select from the database and also by the
    QuerySet class to work out which fields are being initialized on each
    model. Models that have all their fields included aren't mentioned in
    the result, only those that have field restrictions in place.

    The "target" parameter is the instance that is populated (in place).
    The "callback" is a function that is called whenever a (model, field)
    pair need to be added to "target". It accepts three parameters:
    "target", and the model and list of fields being added for that model.
    """
    field_names, defer = self.deferred_loading
    if not field_names:
        return
    orig_opts = self.get_meta()
    seen = {}
    must_include = {orig_opts.concrete_model: {orig_opts.pk}}
    for field_name in field_names:
        parts = field_name.split(LOOKUP_SEP)
        cur_model = self.model._meta.concrete_model
        opts = orig_opts
        for name in parts[:-1]:
            old_model = cur_model
            source = opts.get_field(name)
            if is_reverse_o2o(source):
                cur_model = source.related_model
            else:
                cur_model = source.rel.to
            opts = cur_model._meta
            # Even if we're "just passing through" this model, we must add
            # both the current model's pk and the related reference field
            # (if it's not a reverse relation) to the things we select.
            if not is_reverse_o2o(source):
                must_include[old_model].add(source)
            add_to_dict(must_include, cur_model, opts.pk)
        field = opts.get_field(parts[-1])
        is_reverse_object = field.auto_created and not field.concrete
        model = field.related_model if is_reverse_object else field.model
        model = model._meta.concrete_model
        if model == opts.model:
            model = cur_model
        if not is_reverse_o2o(field):
            add_to_dict(seen, model, field)

    if defer:
        # We need to load all fields for each model, except those that
        # appear in "seen" (for all models that appear in "seen"). The only
        # slight complexity here is handling fields that exist on parent
        # models.
        workset = {}
        for model, values in six.iteritems(seen):
            for field in model._meta.fields:
                if field in values:
                    continue
                m = field.model._meta.concrete_model
                add_to_dict(workset, m, field)
        for model, values in six.iteritems(must_include):
            # If we haven't included a model in workset, we don't add the
            # corresponding must_include fields for that model, since an
            # empty set means "include all fields". That's why there's no
            # "else" branch here.
            if model in workset:
                workset[model].update(values)
        for model, values in six.iteritems(workset):
            callback(target, model, values)
    else:
        for model, values in six.iteritems(must_include):
            if model in seen:
                seen[model].update(values)
            else:
                # As we've passed through this model, but not explicitly
                # included any fields, we have to make sure it's mentioned
                # so that only the "must include" fields are pulled in.
                seen[model] = values
        # Now ensure that every model in the inheritance chain is mentioned
        # in the parent list. Again, it must be mentioned to ensure that
        # only "must include" fields are pulled in.
        for model in orig_opts.get_parent_list():
            if model not in seen:
                seen[model] = set()
        for model, values in six.iteritems(seen):
            callback(target, model, values)

def value(self):
    """
    Returns the value for this BoundField, using the initial value if
    the form is not bound or the data otherwise.
    """
    if not self.form.is_bound:
        data = self.form.initial.get(self.name, self.field.initial)
        if callable(data):
            if self._initial_value is not UNSET:
                data = self._initial_value
            else:
                data = data()
                # If this is an auto-generated default date, nix the
                # microseconds for standardized handling. See #22502.
                if (isinstance(data, (datetime.datetime, datetime.time)) and
                        not getattr(self.field.widget, 'supports_microseconds', True)):
                    data = data.replace(microsecond=0)
                self._initial_value = data
    else:
        data = self.field.bound_data(
            self.data, self.form.initial.get(self.name, self.field.initial)
        )
    return self.field.prepare_value(data)

def add_fields(self, form, index):
    """Add a hidden field for the object's primary key."""
    from django.db.models import AutoField, OneToOneField, ForeignKey
    self._pk_field = pk = self.model._meta.pk
    # If a pk isn't editable, then it won't be on the form, so we need to
    # add it here so we can tell which object is which when we get the
    # data back. Generally, pk.editable should be false, but for some
    # reason, auto_created pk fields and AutoField's editable attribute is
    # True, so check for that as well.

    def pk_is_not_editable(pk):
        return ((not pk.editable) or (pk.auto_created or isinstance(pk, AutoField))
            or (pk.rel and pk.rel.parent_link and pk_is_not_editable(pk.rel.to._meta.pk)))
    if pk_is_not_editable(pk) or pk.name not in form.fields:
        if form.is_bound:
            # If we're adding the related instance, ignore its primary key
            # as it could be an auto-generated default which isn't actually
            # in the database.
            pk_value = None if form.instance._state.adding else form.instance.pk
        else:
            try:
                if index is not None:
                    pk_value = self.get_queryset()[index].pk
                else:
                    pk_value = None
            except IndexError:
                pk_value = None
        if isinstance(pk, OneToOneField) or isinstance(pk, ForeignKey):
            qs = pk.rel.to._default_manager.get_queryset()
        else:
            qs = self.model._default_manager.get_queryset()
        qs = qs.using(form.instance._state.db)
        if form._meta.widgets:
            widget = form._meta.widgets.get(self._pk_field.name, HiddenInput)
        else:
            widget = HiddenInput
        form.fields[self._pk_field.name] = ModelChoiceField(qs, initial=pk_value, required=False, widget=widget)
    super(BaseModelFormSet, self).add_fields(form, index)

def get_full_path(self):
    # RFC 3986 requires query string arguments to be in the ASCII range.
    # Rather than crash if this doesn't happen, we encode defensively.
    return '%s%s' % (
        escape_uri_path(self.path),
        ('?' + iri_to_uri(self.META.get('QUERY_STRING', ''))) if self.META.get('QUERY_STRING', '') else ''
    )

