                new_interfaces[i] = interfaces[i]
        return new_interfaces, ips

def parse_ip_output(output, secondary=False):
    for line in output.split('\n'):
        if not line:
            continue
        words = line.split()
        if words[0] == 'inet':
            if '/' in words[1]:
                address, netmask_length = words[1].split('/')
            else:
                # pointopoint interfaces do not have a prefix
                address = words[1]
                netmask_length = "32"
            address_bin = struct.unpack('!L', socket.inet_aton(address))[0]
            netmask_bin = (1<<32) - (1<<32>>int(netmask_length))
            netmask = socket.inet_ntoa(struct.pack('!L', netmask_bin))
            network = socket.inet_ntoa(struct.pack('!L', address_bin & netmask_bin))
            iface = words[-1]
            if iface != device:
                interfaces[iface] = {}
            if not secondary and "ipv4" not in interfaces[iface]:
                interfaces[iface]['ipv4'] = {'address': address,
                                             'netmask': netmask,
                                             'network': network}
            else:
                if "ipv4_secondaries" not in interfaces[iface]:
                    interfaces[iface]["ipv4_secondaries"] = []
                interfaces[iface]["ipv4_secondaries"].append({
                    'address': address,
                    'netmask': netmask,
                    'network': network,
                })

            # add this secondary IP to the main device
            if secondary:
                if "ipv4_secondaries" not in interfaces[device]:
                    interfaces[device]["ipv4_secondaries"] = []
                interfaces[device]["ipv4_secondaries"].append({
                    'address': address,
                    'netmask': netmask,
                    'network': network,
                })

            # If this is the default address, update default_ipv4
            if 'address' in default_ipv4 and default_ipv4['address'] == address:
                default_ipv4['netmask'] = netmask
                default_ipv4['network'] = network
                default_ipv4['macaddress'] = macaddress
                default_ipv4['mtu'] = interfaces[device]['mtu']
                default_ipv4['type'] = interfaces[device].get("type", "unknown")
                default_ipv4['alias'] = words[-1]
            if not address.startswith('127.'):
                ips['all_ipv4_addresses'].append(address)
        elif words[0] == 'inet6':
            address, prefix = words[1].split('/')
            scope = words[3]
            if 'ipv6' not in interfaces[device]:
                interfaces[device]['ipv6'] = []
            interfaces[device]['ipv6'].append({
                'address' : address,
                'prefix'  : prefix,
                'scope'   : scope
            })
            # If this is the default address, update default_ipv6
            if 'address' in default_ipv6 and default_ipv6['address'] == address:
                default_ipv6['prefix']     = prefix
                default_ipv6['scope']      = scope
                default_ipv6['macaddress'] = macaddress
                default_ipv6['mtu']        = interfaces[device]['mtu']
                default_ipv6['type']       = interfaces[device].get("type", "unknown")
            if not address == '::1':
                ips['all_ipv6_addresses'].append(address)

def parse_interface_line(self, words):
    device = words[0][0:-1]
    current_if = {'device': device, 'ipv4': [], 'ipv6': [], 'type': 'unknown'}
    current_if['flags'] = self.get_options(words[1])
    current_if['macaddress'] = 'unknown'    # will be overwritten later
    return current_if

def _late_merge_role_tags(self):
    # build a local dict of tags for roles
    role_tags = {}
    for task in self._ds['tasks']:
        if 'role_name' in task:
            this_role = task['role_name'] + "-" + task['vars']['role_uuid']

            if this_role not in role_tags:
                role_tags[this_role] = []

            if 'tags' in task['vars']:
                if isinstance(task['vars']['tags'], basestring):
                    role_tags[this_role] += shlex.split(task['vars']['tags'])
                else:
                    role_tags[this_role] += task['vars']['tags']

    # apply each role's tags to its tasks
    for idx, val in enumerate(self._tasks):
        if getattr(val, 'role_name', None) is not None:
            this_role = val.role_name + "-" + val.module_vars['role_uuid']
            if this_role in role_tags:
                self._tasks[idx].tags = sorted(set(self._tasks[idx].tags + role_tags[this_role]))

def __init__(self, results, runner):
    self.runner = runner

    self.results = { 'contacted': {}, 'dark': {}}
    self.hosts_to_poll = []
    self.completed = False

    # flag to determine if at least one host was contacted
    self.active = False
    # True to work with the `and` below
    skipped = True
    jid = None
    for (host, res) in results['contacted'].iteritems():
        if res.get('started', False):
            self.hosts_to_poll.append(host)
            jid = res.get('ansible_job_id', None)
            self.runner.vars_cache[host]['ansible_job_id'] = jid
            self.active = True
        else:
            skipped = skipped and res.get('skipped', False)
            self.runner.vars_cache[host]['ansible_job_id'] = ''
            self.results['contacted'][host] = res
    for (host, res) in results['dark'].iteritems():
        self.runner.vars_cache[host]['ansible_job_id'] = ''
        self.results['dark'][host] = res

    if not skipped:
        if jid is None:
            raise errors.AnsibleError("unexpected error: unable to determine jid")
        if len(self.hosts_to_poll)==0:
            raise errors.AnsibleError("unexpected error: no hosts to poll")

def wait(self, seconds, poll_interval):
    """ Wait a certain time for job completion, check status every poll_interval. """
    # jid is None when all hosts were skipped
    if not self.active:
        return self.results

    clock = seconds - poll_interval
    while (clock >= 0 and not self.completed):
        time.sleep(poll_interval)

        poll_results = self.poll()

        for (host, res) in poll_results['polled'].iteritems():
            if res.get('started'):
                self.runner.callbacks.on_async_poll(host, res, self.runner.vars_cache[host]['ansible_job_id'], clock)

        clock = clock - poll_interval

    return self.results

def changed(*a, **kw):
    ''' Test if task result yields changed '''
    item = a[0]
    if type(item) != dict:
        raise errors.AnsibleFilterError("|changed expects a dictionary")
    if not 'changed' in item:
        changed = False
        if ('results' in item    # some modules return a 'results' key
                and type(item['results']) == list
                and type(item['results'][0]) == dict):
            for result in item['results']:
                changed = changed or result.get('changed', False)
    else:
        changed = item.get('changed', False)
    return changed

def update_cache(self):
    """ Make calls to Collins and saves the output in a cache """

    self.cache = dict()
    self.inventory = dict()

    # Locates all server assets from Collins.
    try:
        server_assets = self.find_assets()
    except:
        self.log.error("Error while locating assets from Collins:\n%s",
            traceback.format_exc())
        return False

    for asset in server_assets:
        # Determines the index to retrieve the asset's IP address either by an
        # attribute set on the Collins asset or the pre-configured value.
        if self._asset_has_attribute(asset, 'ANSIBLE_IP_INDEX'):
            ip_index = self._asset_get_attribute(asset, 'ANSIBLE_IP_INDEX')
            try:
                ip_index = int(ip_index)
            except:
                self.log.error(
                    "ANSIBLE_IP_INDEX attribute on asset %s not an integer: %s", asset,
                    ip_index)
        else:
            ip_index = self.ip_address_index

        asset['COLLINS'] = {}

        # Attempts to locate the asset's primary identifier (hostname or IP address),
        # which will be used to index the asset throughout the Ansible inventory.
        if self.prefer_hostnames and self._asset_has_attribute(asset, 'HOSTNAME'):
            asset_identifier = self._asset_get_attribute(asset, 'HOSTNAME')
        elif 'ADDRESSES' not in asset:
            self.log.warning("No IP addresses found for asset '%s', skipping",
                asset)
            continue
        elif len(asset['ADDRESSES']) < ip_index + 1:
            self.log.warning(
                "No IP address found at index %s for asset '%s', skipping",
                ip_index, asset)
            continue
        else:
            asset_identifier = asset['ADDRESSES'][ip_index]['ADDRESS']

        # Adds an asset index to the Ansible inventory based upon unpacking
        # the name of the asset's current STATE from its dictionary.
        if 'STATE' in asset['ASSET'] and asset['ASSET']['STATE']:
            state_inventory_key = self.to_safe(
                'STATE-%s' % asset['ASSET']['STATE']['NAME'])
            self.push(self.inventory, state_inventory_key, asset_identifier)

        # Indexes asset by all user-defined Collins attributes.
        if 'ATTRIBS' in asset:
            for attrib_block in asset['ATTRIBS'].keys():
                for attrib in asset['ATTRIBS'][attrib_block].keys():
                    asset['COLLINS'][attrib] = asset['ATTRIBS'][attrib_block][attrib]
                    attrib_key = self.to_safe('%s-%s' % (attrib, asset['ATTRIBS'][attrib_block][attrib]))
                    self.push(self.inventory, attrib_key, asset_identifier)

        # Indexes asset by all built-in Collins attributes.
        for attribute in asset['ASSET'].keys():
            if attribute not in CollinsDefaults.SPECIAL_ATTRIBUTES:
                attribute_val = asset['ASSET'][attribute]
                if attribute_val is not None:
                    attrib_key = self.to_safe('%s-%s' % (attribute, attribute_val))
                    self.push(self.inventory, attrib_key, asset_identifier)

        # Indexes asset by hardware product information.
        if 'HARDWARE' in asset:
            if 'PRODUCT' in asset['HARDWARE']['BASE']:
                product = asset['HARDWARE']['BASE']['PRODUCT']
                if product:
                    product_key = self.to_safe(
                        'HARDWARE-PRODUCT-%s' % asset['HARDWARE']['BASE']['PRODUCT'])
                    self.push(self.inventory, product_key, asset_identifier)

        # Indexing now complete, adds the host details to the asset cache.
        self.cache[asset_identifier] = asset

    try:
        self.write_to_cache(self.cache, self.cache_path_cache)
        self.write_to_cache(self.inventory, self.cache_path_inventory)
    except:
        self.log.error("Error while writing to cache:\n%s", traceback.format_exc())
        return False
    return True

