def _get_octal_mode_from_symbolic_perms(self, path_stat, user, perms):
    prev_mode = stat.S_IMODE(path_stat.st_mode)

    is_directory = stat.S_ISDIR(path_stat.st_mode)
    has_x_permissions = (prev_mode & 00111) > 0
    apply_X_permission = is_directory or has_x_permissions

    # Permission bits constants documented at:
    # http://docs.python.org/2/library/stat.html#stat.S_ISUID
    if apply_X_permission:
        X_perms = {
            'u': {'X': stat.S_IXUSR},
            'g': {'X': stat.S_IXGRP},
            'o': {'X': stat.S_IXOTH}
        }
    else:
        X_perms = {
            'u': {'X': 0},
            'g': {'X': 0},
            'o': {'X': 0}
        }

    user_perms_to_modes = {
        'u': {
            'r': stat.S_IRUSR,
            'w': stat.S_IWUSR,
            'x': stat.S_IXUSR,
            's': stat.S_ISUID,
            't': 0,
            'u': prev_mode & stat.S_IRWXU,
            'g': (prev_mode & stat.S_IRWXG) << 3,
            'o': (prev_mode & stat.S_IRWXO) << 6 },
        'g': {
            'r': stat.S_IRGRP,
            'w': stat.S_IWGRP,
            'x': stat.S_IXGRP,
            's': stat.S_ISGID,
            't': 0,
            'u': (prev_mode & stat.S_IRWXU) >> 3,
            'g': prev_mode & stat.S_IRWXG,
            'o': (prev_mode & stat.S_IRWXO) << 3 },
        'o': {
            'r': stat.S_IROTH,
            'w': stat.S_IWOTH,
            'x': stat.S_IXOTH,
            's': 0,
            't': stat.S_ISVTX,
            'u': (prev_mode & stat.S_IRWXU) >> 6,
            'g': (prev_mode & stat.S_IRWXG) >> 3,
            'o': prev_mode & stat.S_IRWXO }
    }

    # Insert X_perms into user_perms_to_modes
    for key, value in X_perms.items():
        user_perms_to_modes[key].update(value)

    or_reduce = lambda mode, perm: mode | user_perms_to_modes[user][perm]
    return reduce(or_reduce, perms, 0)

def get_lsb_facts(self):
    lsb_path = module.get_bin_path('lsb_release')
    if lsb_path:
        rc, out, err = module.run_command([lsb_path, "-a"])
        if rc == 0:
            self.facts['lsb'] = {}
        for line in out.split('\n'):
            if len(line) < 1:
                continue
            value = line.split(':', 1)[1].strip()
            if 'LSB Version:' in line:
                self.facts['lsb']['release'] = value
            elif 'Distributor ID:' in line:
                self.facts['lsb']['id'] = value
            elif 'Description:' in line:
                self.facts['lsb']['description'] = value
            elif 'Release:' in line:
                self.facts['lsb']['release'] = value
            elif 'Codename:' in line:
                self.facts['lsb']['codename'] = value
        if 'lsb' in self.facts and 'release' in self.facts['lsb']:
            self.facts['lsb']['major_release'] = self.facts['lsb']['release'].split('.')[0]
    elif lsb_path is None and os.path.exists('/etc/lsb-release'):
        self.facts['lsb'] = {}
        for line in get_file_lines('/etc/lsb-release'):
            value = line.split('=',1)[1].strip()
            if 'DISTRIB_ID' in line:
                self.facts['lsb']['id'] = value
            elif 'DISTRIB_RELEASE' in line:
                self.facts['lsb']['release'] = value
            elif 'DISTRIB_DESCRIPTION' in line:
                self.facts['lsb']['description'] = value
            elif 'DISTRIB_CODENAME' in line:
                self.facts['lsb']['codename'] = value
    else:
        return self.facts

    if 'lsb' in self.facts and 'release' in self.facts['lsb']:
        self.facts['lsb']['major_release'] = self.facts['lsb']['release'].split('.')[0]

def get_default_interfaces(self, ip_path):
    # Use the commands:
    #     ip -4 route get 8.8.8.8                     -> Google public DNS
    #     ip -6 route get 2404:6800:400a:800::1012    -> ipv6.google.com
    # to find out the default outgoing interface, address, and gateway
    command = dict(
        v4 = [ip_path, '-4', 'route', 'get', '8.8.8.8'],
        v6 = [ip_path, '-6', 'route', 'get', '2404:6800:400a:800::1012']
    )
    interface = dict(v4 = {}, v6 = {})
    for v in 'v4', 'v6':
        if v == 'v6' and self.facts['os_family'] == 'RedHat' \
            and self.facts['distribution_version'].startswith('4.'):
            continue
        if v == 'v6' and not socket.has_ipv6:
            continue
        rc, out, err = module.run_command(command[v])
        if not out:
            # v6 routing may result in
            #   RTNETLINK answers: Invalid argument
            continue
        words = out.split('\n')[0].split()
        # A valid output starts with the queried address on the first line
        if len(words) > 0 and words[0] == command[v][-1]:
            for i in range(len(words) - 1):
                if words[i] == 'dev':
                    interface[v]['interface'] = words[i+1]
                elif words[i] == 'src':
                    interface[v]['address'] = words[i+1]
                elif words[i] == 'via' and words[i+1] != command[v][-1]:
                    interface[v]['gateway'] = words[i+1]
    return interface['v4'], interface['v6']

    def get_interfaces_info(self, ip_path, default_ipv4, default_ipv6):
        interfaces = {}
        ips = dict(
            all_ipv4_addresses = [],
            all_ipv6_addresses = [],
        )

        for path in glob.glob('/sys/class/net/*'):
            if not os.path.isdir(path):
                continue
            device = os.path.basename(path)
            interfaces[device] = { 'device': device }
            if os.path.exists(os.path.join(path, 'address')):
                macaddress = get_file_content(os.path.join(path, 'address'))
                if macaddress and macaddress != '00:00:00:00:00:00':
                    interfaces[device]['macaddress'] = macaddress
            if os.path.exists(os.path.join(path, 'mtu')):
                interfaces[device]['mtu'] = int(get_file_content(os.path.join(path, 'mtu')))
            if os.path.exists(os.path.join(path, 'operstate')):
                interfaces[device]['active'] = get_file_content(os.path.join(path, 'operstate')) != 'down'
#            if os.path.exists(os.path.join(path, 'carrier')):
#                interfaces[device]['link'] = get_file_content(os.path.join(path, 'carrier')) == '1'
            if os.path.exists(os.path.join(path, 'device','driver', 'module')):
                interfaces[device]['module'] = os.path.basename(os.path.realpath(os.path.join(path, 'device', 'driver', 'module')))
            if os.path.exists(os.path.join(path, 'type')):
                _type = get_file_content(os.path.join(path, 'type'))
                if _type == '1':
                    interfaces[device]['type'] = 'ether'
                elif _type == '512':
                    interfaces[device]['type'] = 'ppp'
                elif _type == '772':
                    interfaces[device]['type'] = 'loopback'
            if os.path.exists(os.path.join(path, 'bridge')):
                interfaces[device]['type'] = 'bridge'
                interfaces[device]['interfaces'] = [ os.path.basename(b) for b in glob.glob(os.path.join(path, 'brif', '*')) ]
                if os.path.exists(os.path.join(path, 'bridge', 'bridge_id')):
                    interfaces[device]['id'] = get_file_content(os.path.join(path, 'bridge', 'bridge_id'))
                if os.path.exists(os.path.join(path, 'bridge', 'stp_state')):
                    interfaces[device]['stp'] = get_file_content(os.path.join(path, 'bridge', 'stp_state')) == '1'
            if os.path.exists(os.path.join(path, 'bonding')):
                interfaces[device]['type'] = 'bonding'
                interfaces[device]['slaves'] = get_file_content(os.path.join(path, 'bonding', 'slaves')).split()
                interfaces[device]['mode'] = get_file_content(os.path.join(path, 'bonding', 'mode')).split()[0]
                interfaces[device]['miimon'] = get_file_content(os.path.join(path, 'bonding', 'miimon')).split()[0]
                interfaces[device]['lacp_rate'] = get_file_content(os.path.join(path, 'bonding', 'lacp_rate')).split()[0]
                primary = get_file_content(os.path.join(path, 'bonding', 'primary'))
                if primary:
                    interfaces[device]['primary'] = primary
                    path = os.path.join(path, 'bonding', 'all_slaves_active')
                    if os.path.exists(path):
                        interfaces[device]['all_slaves_active'] = get_file_content(path) == '1'

            # Check whether an interface is in promiscuous mode
            if os.path.exists(os.path.join(path,'flags')):
                promisc_mode = False
                # The second byte indicates whether the interface is in promiscuous mode.
                # 1 = promisc
                # 0 = no promisc
                data = int(get_file_content(os.path.join(path, 'flags')),16)
                promisc_mode = (data & 0x0100 > 0)
                interfaces[device]['promisc'] = promisc_mode

            def parse_ip_output(output, secondary=False):
                for line in output.split('\n'):
                    if not line:
                        continue
                    words = line.split()
                    if words[0] == 'inet':
                        if '/' in words[1]:
                            address, netmask_length = words[1].split('/')
                        else:
                            # pointopoint interfaces do not have a prefix
                            address = words[1]
                            netmask_length = "32"
                        address_bin = struct.unpack('!L', socket.inet_aton(address))[0]
                        netmask_bin = (1<<32) - (1<<32>>int(netmask_length))
                        netmask = socket.inet_ntoa(struct.pack('!L', netmask_bin))
                        network = socket.inet_ntoa(struct.pack('!L', address_bin & netmask_bin))
                        iface = words[-1]
                        if iface != device:
                            interfaces[iface] = {}
                        if not secondary and "ipv4" not in interfaces[iface]:
                            interfaces[iface]['ipv4'] = {'address': address,
                                                         'netmask': netmask,
                                                         'network': network}
                        else:
                            if "ipv4_secondaries" not in interfaces[iface]:
                                interfaces[iface]["ipv4_secondaries"] = []
                            interfaces[iface]["ipv4_secondaries"].append({
                                'address': address,
                                'netmask': netmask,
                                'network': network,
                            })

                        # add this secondary IP to the main device
                        if secondary:
                            if "ipv4_secondaries" not in interfaces[device]:
                                interfaces[device]["ipv4_secondaries"] = []
                            interfaces[device]["ipv4_secondaries"].append({
                                'address': address,
                                'netmask': netmask,
                                'network': network,
                            })

                        # If this is the default address, update default_ipv4
                        if 'address' in default_ipv4 and default_ipv4['address'] == address:
                            default_ipv4['netmask'] = netmask
                            default_ipv4['network'] = network
                            default_ipv4['macaddress'] = macaddress
                            default_ipv4['mtu'] = interfaces[device]['mtu']
                            default_ipv4['type'] = interfaces[device].get("type", "unknown")
                            default_ipv4['alias'] = words[-1]
                        if not address.startswith('127.'):
                            ips['all_ipv4_addresses'].append(address)
                    elif words[0] == 'inet6':
                        address, prefix = words[1].split('/')
                        scope = words[3]
                        if 'ipv6' not in interfaces[device]:
                            interfaces[device]['ipv6'] = []
                        interfaces[device]['ipv6'].append({
                            'address' : address,
                            'prefix'  : prefix,
                            'scope'   : scope
                        })
                        # If this is the default address, update default_ipv6
                        if 'address' in default_ipv6 and default_ipv6['address'] == address:
                            default_ipv6['prefix']     = prefix
                            default_ipv6['scope']      = scope
                            default_ipv6['macaddress'] = macaddress
                            default_ipv6['mtu']        = interfaces[device]['mtu']
                            default_ipv6['type']       = interfaces[device].get("type", "unknown")
                        if not address == '::1':
                            ips['all_ipv6_addresses'].append(address)

            ip_path = module.get_bin_path("ip")

            args = [ip_path, 'addr', 'show', 'primary', device]
            rc, stdout, stderr = self.module.run_command(args)
            primary_data = stdout

            args = [ip_path, 'addr', 'show', 'secondary', device]
            rc, stdout, stderr = self.module.run_command(args)
            secondary_data = stdout

            parse_ip_output(primary_data)
            parse_ip_output(secondary_data, secondary=True)

        # replace : by _ in interface name since they are hard to use in template
        new_interfaces = {}
        for i in interfaces:
            if ':' in i:
                new_interfaces[i.replace(':','_')] = interfaces[i]
            else:
                new_interfaces[i] = interfaces[i]
        return new_interfaces, ips

