                })

            # add this secondary IP to the main device
            if secondary:
                if "ipv4_secondaries" not in interfaces[device]:
                    interfaces[device]["ipv4_secondaries"] = []
                interfaces[device]["ipv4_secondaries"].append({
                    'address': address,
                    'netmask': netmask,
                    'network': network,
                })

            # If this is the default address, update default_ipv4
            if 'address' in default_ipv4 and default_ipv4['address'] == address:
                default_ipv4['netmask'] = netmask
                default_ipv4['network'] = network
                default_ipv4['macaddress'] = macaddress
                default_ipv4['mtu'] = interfaces[device]['mtu']
                default_ipv4['type'] = interfaces[device].get("type", "unknown")
                default_ipv4['alias'] = words[-1]
            if not address.startswith('127.'):
                ips['all_ipv4_addresses'].append(address)
        elif words[0] == 'inet6':
            address, prefix = words[1].split('/')
            scope = words[3]
            if 'ipv6' not in interfaces[device]:
                interfaces[device]['ipv6'] = []
            interfaces[device]['ipv6'].append({
                'address' : address,
                'prefix'  : prefix,
                'scope'   : scope
            })
            # If this is the default address, update default_ipv6
            if 'address' in default_ipv6 and default_ipv6['address'] == address:
                default_ipv6['prefix']     = prefix
                default_ipv6['scope']      = scope
                default_ipv6['macaddress'] = macaddress
                default_ipv6['mtu']        = interfaces[device]['mtu']
                default_ipv6['type']       = interfaces[device].get("type", "unknown")
            if not address == '::1':
                ips['all_ipv6_addresses'].append(address)

def get_interfaces_info(self, ifconfig_path):
    interfaces = {}
    current_if = {}
    ips = dict(
        all_ipv4_addresses = [],
        all_ipv6_addresses = [],
    )
    rc, out, err = module.run_command([ifconfig_path, '-a'])

    for line in out.split('\n'):

        if line:
            words = line.split()

            if re.match('^\S', line) and len(words) > 3:
                current_if = self.parse_interface_line(words, current_if, interfaces)
                interfaces[ current_if['device'] ] = current_if
            elif words[0].startswith('options='):
                self.parse_options_line(words, current_if, ips)
            elif words[0] == 'nd6':
                self.parse_nd6_line(words, current_if, ips)
            elif words[0] == 'ether':
                self.parse_ether_line(words, current_if, ips)
            elif words[0] == 'media:':
                self.parse_media_line(words, current_if, ips)
            elif words[0] == 'status:':
                self.parse_status_line(words, current_if, ips)
            elif words[0] == 'lladdr':
                self.parse_lladdr_line(words, current_if, ips)
            elif words[0] == 'inet':
                self.parse_inet_line(words, current_if, ips)
            elif words[0] == 'inet6':
                self.parse_inet6_line(words, current_if, ips)
            else:
                self.parse_unknown_line(words, current_if, ips)

    # 'parse_interface_line' and 'parse_inet*_line' leave two dicts in the
    # ipv4/ipv6 lists which is ugly and hard to read.
    # This quick hack merges the dictionaries. Purely cosmetic.
    for iface in interfaces:
        for v in 'ipv4', 'ipv6':
            combined_facts = {}
            for facts in interfaces[iface][v]:
                combined_facts.update(facts)
            if len(combined_facts.keys()) > 0:
                interfaces[iface][v] = [combined_facts]

    return interfaces, ips

def list_modules(module_dir, depth=0):
    ''' returns a hash of categories, each category being a hash of module names to file paths '''

    categories = dict(all=dict(),_aliases=dict())
    if depth <= 3: # limit # of subdirs

        files = glob.glob("%s/*" % module_dir)
        for d in files:

            category = os.path.splitext(os.path.basename(d))[0]
            if os.path.isdir(d):

                res = list_modules(d, depth + 1)
                for key in res.keys():
                    if key in categories:
                        categories[key] = ansible.utils.merge_hash(categories[key], res[key])
                        res.pop(key, None)

                if depth < 2:
                    categories.update(res)
                else:
                    category = module_dir.split("/")[-1]
                    if not category in categories:
                        categories[category] = res
                    else:
                        categories[category].update(res)
            else:
                module = category
                category = os.path.basename(module_dir)
                if not d.endswith(".py") or d.endswith('__init__.py'):
                    # windows powershell modules have documentation stubs in python docstring
                    # format (they are not executed) so skip the ps1 format files
                    continue
                elif module.startswith("_") and os.path.islink(d):
                    source = os.path.splitext(os.path.basename(os.path.realpath(d)))[0]
                    module = module.replace("_","",1)
                    if not d in categories['_aliases']:
                        categories['_aliases'][source] = [module]
                    else:
                        categories['_aliases'][source].update(module)
                    continue

                if not category in categories:
                    categories[category] = {}
                categories[category][module] = d
                categories['all'][module] = d

    return categories

def create_index_field(self, field_name, field_type,
                       default='', facet=False, returnable=False,
                       searchable=False, sortable=False,
                       highlight=False, source_field=None,
                       analysis_scheme=None):
    """
    Defines an ``IndexField``, either replacing an existing
    definition or creating a new one.

    :type field_name: string
    :param field_name: The name of a field in the search index.

    :type field_type: string
    :param field_type: The type of field.  Valid values are
        int | double | literal | text | date | latlon |
        int-array | double-array | literal-array | text-array | date-array

    :type default: string or int
    :param default: The default value for the field.  If the
        field is of type ``int`` this should be an integer value.
        Otherwise, it's a string.

    :type facet: bool
    :param facet: A boolean to indicate whether facets
        are enabled for this field or not.  Does not apply to
        fields of type ``int, int-array, text, text-array``.

    :type returnable: bool
    :param returnable: A boolean to indicate whether values
        of this field can be returned in search results or
        used in ranking.

    :type searchable: bool
