        if source_field:
            index['LiteralArrayOptions']['SourceFields'] = \
                ','.join(source_field)
    elif field_type == 'int':
        index['IntOptions'] = {
            'DefaultValue': default,
            'FacetEnabled': facet,
            'ReturnEnabled': returnable,
            'SearchEnabled': searchable,
