def _allow_ip(self, arn, ip):
    if 'Statement' not in self:
        s = self.new_statement(arn, ip)
        self['Statement'] = [s]
        self.save()
    else:
        add_statement = True
        for statement in self['Statement']:
            if statement['Resource'] == arn:
                for condition_name in statement['Condition']:
                    if condition_name == 'IpAddress':
                        add_statement = False
                        condition = statement['Condition'][condition_name]
                        if ip not in condition['aws:SourceIp']:
                            condition['aws:SourceIp'].append(ip)

        if add_statement:
            s = self.new_statement(arn, ip)
            self['Statement'].append(s)
        self.save()

def range_key_name(self):
    name = None
    if 'RangeKeyElement' in self._dict:
        name = self._dict['RangeKeyElement']['AttributeName']
    return name

def _introspect_all_indexes(self, raw_indexes, map_indexes_projection):
    """
    Given a raw index/global index structure back from a DynamoDB response,
    parse out & build the high-level Python objects that represent them.
    """
    indexes = []

    for field in raw_indexes:
        index_klass = map_indexes_projection.get('ALL')
        kwargs = {
            'parts': []
        }

        if field['Projection']['ProjectionType'] == 'ALL':
            index_klass = map_indexes_projection.get('ALL')
        elif field['Projection']['ProjectionType'] == 'KEYS_ONLY':
            index_klass = map_indexes_projection.get('KEYS_ONLY')
        elif field['Projection']['ProjectionType'] == 'INCLUDE':
            index_klass = map_indexes_projection.get('INCLUDE')
            kwargs['includes'] = field['Projection']['NonKeyAttributes']
        else:
            raise exceptions.UnknownIndexFieldError(
                "%s was seen, but is unknown. Please report this at "
                "https://github.com/boto/boto/issues." % \
                field['Projection']['ProjectionType']
            )

        name = field['IndexName']
        kwargs['parts'] = self._introspect_schema(field['KeySchema'], None)
        indexes.append(index_klass(name, **kwargs))

    return indexes

def endElement(self, name, value, connection):
    if name == 'TotalResults':
        self.total_results = value
    elif name == 'TotalPages':
        self.total_pages = value
    elif name == 'IsValid':
        if value == 'True':
            self.is_valid = True
    elif name == 'Code':
        self.errors.append({'Code': value, 'Message': None})
    elif name == 'Message':
        self.errors[-1]['Message'] = value
    elif name == 'Item':
        self.objs.append(self.curItem)
        self._xml.write(self.curItem.to_xml())
        self.curItem = None
    elif self.curItem is not None:
        self.curItem.endElement(name, value, connection)
    return None

def get_hosted_zone_by_name(self, hosted_zone_name):
    """
    Get detailed information about a particular Hosted Zone.

    :type hosted_zone_name: str
    :param hosted_zone_name: The fully qualified domain name for the Hosted
        Zone

    """
    if hosted_zone_name[-1] != '.':
        hosted_zone_name += '.'
    all_hosted_zones = self.get_all_hosted_zones()
    for zone in all_hosted_zones['ListHostedZonesResponse']['HostedZones']:
        # check that they gave us the FQDN for their zone
        if zone['Name'] == hosted_zone_name:
            return self.get_hosted_zone(zone['Id'].split('/')[-1])

def build_data(doc):
    data = {}

    # Run through all the regions. These have all the data we need.
    for region_elem in doc('Regions').find('Region'):
        region = pq(region_elem, parser='xml')
        region_name = region.find('Name').text()

        for endp in region.find('Endpoint'):
            service_name = endp.find('ServiceName').text
            endpoint = endp.find('Hostname').text

            data.setdefault(service_name, {})
            data[service_name][region_name] = endpoint

    return data

