                        if 'attrspec' in vars[d]:
                            for aa in vars[d]['attrspec']:
                                if aa[:6]=='depend':
                                    ddeps += aa[6:].strip()[1:-1].split(',')
                        if 'depend' in vars[d]:
                            ddeps=ddeps+vars[d]['depend']
                    i=i+1
                    if d in vars and ('depend' not in vars[d]) \
                       and ('=' not in vars[d]) and (d not in vars[n]['depend']) \
                       and l_or(isintent_in, isintent_inout, isintent_inplace)(vars[n]):
                        vars[d]['depend']=[n]
                        if ni>1:
                            vars[d]['=']='%s%s(%s,%s)%s'% (pd, shape_macro, n, i, ad)
                        else:
                            vars[d]['=']='%slen(%s)%s'% (pd, n, ad)
                        #  /---< no check
                        if 1 and 'check' not in vars[d]:
                            if ni>1:
                                vars[d]['check']=['%s%s(%s,%i)%s==%s'\
                                                  %(pd, shape_macro, n, i, ad, d)]
                            else:
                                vars[d]['check']=['%slen(%s)%s>=%s'%(pd, n, ad, d)]
                        if 'attrspec' not in vars[d]:
                            vars[d]['attrspec']=['optional']
                        if ('optional' not in vars[d]['attrspec']) and\
                           ('required' not in vars[d]['attrspec']):
                            vars[d]['attrspec'].append('optional')
                    elif d not in ['*', ':']:
                        #/----< no check
                        #if ni>1: vars[n]['check'].append('shape(%s,%i)==%s'%(n,i,d))
                        #else: vars[n]['check'].append('len(%s)>=%s'%(n,d))
                        if flag:
                            if d in vars:
                                if n not in ddeps:
                                    vars[n]['depend'].append(d)
                            else:
                                vars[n]['depend'] = vars[n]['depend'] + ddeps
            elif isstring(vars[n]):
                length='1'
                if 'charselector' in vars[n]:
                    if '*' in vars[n]['charselector']:
                        length = _eval_length(vars[n]['charselector']['*'],
                                              params)
                        vars[n]['charselector']['*']=length
                    elif 'len' in vars[n]['charselector']:
                        length = _eval_length(vars[n]['charselector']['len'],
                                              params)
                        del vars[n]['charselector']['len']
                        vars[n]['charselector']['*']=length

            if not vars[n]['check']:
                del vars[n]['check']
            if flag and not vars[n]['depend']:
                del vars[n]['depend']
        if '=' in vars[n]:
            if 'attrspec' not in vars[n]:
                vars[n]['attrspec']=[]
            if ('optional' not in vars[n]['attrspec']) and \
               ('required' not in vars[n]['attrspec']):
                vars[n]['attrspec'].append('optional')
            if 'depend' not in vars[n]:
                vars[n]['depend']=[]
                for v, m in list(dep_matches.items()):
                    if m(vars[n]['=']): vars[n]['depend'].append(v)
                if not vars[n]['depend']: del vars[n]['depend']
            if isscalar(vars[n]):
                vars[n]['='] = _eval_scalar(vars[n]['='], params)

    for n in list(vars.keys()):
        if n==block['name']: # n is block name
            if 'note' in vars[n]:
                block['note']=vars[n]['note']
            if block['block']=='function':
                if 'result' in block and block['result'] in vars:
                    vars[n]=appenddecl(vars[n], vars[block['result']])
                if 'prefix' in block:
                    pr=block['prefix']; ispure=0; isrec=1
                    pr1=pr.replace('pure', '')
                    ispure=(not pr==pr1)
                    pr=pr1.replace('recursive', '')
                    isrec=(not pr==pr1)
                    m=typespattern[0].match(pr)
                    if m:
                        typespec, selector, attr, edecl=cracktypespec0(m.group('this'), m.group('after'))
                        kindselect, charselect, typename=cracktypespec(typespec, selector)
                        vars[n]['typespec']=typespec
                        if kindselect:
                            if 'kind' in kindselect:
                                try:
                                    kindselect['kind'] = eval(kindselect['kind'], {}, params)
                                except:
                                    pass
                            vars[n]['kindselector']=kindselect
                        if charselect: vars[n]['charselector']=charselect
                        if typename: vars[n]['typename']=typename
                        if ispure: vars[n]=setattrspec(vars[n], 'pure')
                        if isrec: vars[n]=setattrspec(vars[n], 'recursive')
                    else:
                        outmess('analyzevars: prefix (%s) were not used\n'%repr(block['prefix']))
    if not block['block'] in ['module', 'pythonmodule', 'python module', 'block data']:
        if 'commonvars' in block:
            neededvars=copy.copy(block['args']+block['commonvars'])
        else:
            neededvars=copy.copy(block['args'])
        for n in list(vars.keys()):
            if l_or(isintent_callback, isintent_aux)(vars[n]):
                neededvars.append(n)
        if 'entry' in block:
            neededvars.extend(list(block['entry'].keys()))
            for k in list(block['entry'].keys()):
                for n in block['entry'][k]:
                    if n not in neededvars:
                        neededvars.append(n)
        if block['block']=='function':
            if 'result' in block:
                neededvars.append(block['result'])
            else:
                neededvars.append(block['name'])
        if block['block'] in ['subroutine', 'function']:
            name = block['name']
            if name in vars and 'intent' in vars[name]:
                block['intent'] = vars[name]['intent']
        if block['block'] == 'type':
            neededvars.extend(list(vars.keys()))
        for n in list(vars.keys()):
            if n not in neededvars:
                del vars[n]
    return vars

def crack2fortrangen(block,tab='\n', as_interface=False):
    global skipfuncs, onlyfuncs
    setmesstext(block)
    ret=''
    if isinstance(block, list):
        for g in block:
            if g and g['block'] in ['function', 'subroutine']:
                if g['name'] in skipfuncs:
                    continue
                if onlyfuncs and g['name'] not in onlyfuncs:
                    continue
            ret=ret+crack2fortrangen(g, tab, as_interface=as_interface)
        return ret
    prefix=''
    name=''
    args=''
    blocktype=block['block']
    if blocktype=='program': return ''
    argsl = []
    if 'name' in block:
        name=block['name']
    if 'args' in block:
        vars = block['vars']
        for a in block['args']:
            a = expr2name(a, block, argsl)
            if not isintent_callback(vars[a]):
                argsl.append(a)
        if block['block']=='function' or argsl:
            args='(%s)'%','.join(argsl)
    f2pyenhancements = ''
    if 'f2pyenhancements' in block:
        for k in list(block['f2pyenhancements'].keys()):
            f2pyenhancements = '%s%s%s %s'%(f2pyenhancements, tab+tabchar, k, block['f2pyenhancements'][k])
    intent_lst = block.get('intent', [])[:]
    if blocktype=='function' and 'callback' in intent_lst:
        intent_lst.remove('callback')
    if intent_lst:
        f2pyenhancements = '%s%sintent(%s) %s'%\
                           (f2pyenhancements, tab+tabchar,
                            ','.join(intent_lst), name)
    use=''
    if 'use' in block:
        use=use2fortran(block['use'], tab+tabchar)
    common=''
    if 'common' in block:
        common=common2fortran(block['common'], tab+tabchar)
    if name=='unknown_interface': name=''
    result=''
    if 'result' in block:
        result=' result (%s)'%block['result']
        if block['result'] not in argsl:
            argsl.append(block['result'])
    #if 'prefix' in block:
    #    prefix=block['prefix']+' '
    body=crack2fortrangen(block['body'], tab+tabchar)
    vars=vars2fortran(block, block['vars'], argsl, tab+tabchar, as_interface=as_interface)
    mess=''
    if 'from' in block and not as_interface:
        mess='! in %s'%block['from']
    if 'entry' in block:
        entry_stmts = ''
        for k, i in list(block['entry'].items()):
            entry_stmts = '%s%sentry %s(%s)' \
                          % (entry_stmts, tab+tabchar, k, ','.join(i))
        body = body + entry_stmts
    if blocktype=='block data' and name=='_BLOCK_DATA_':
        name = ''
    ret='%s%s%s %s%s%s %s%s%s%s%s%s%send %s %s'%(tab, prefix, blocktype, name, args, result, mess, f2pyenhancements, use, vars, common, body, tab, blocktype, name)
    return ret

def vars2fortran(block,vars,args,tab='', as_interface=False):
    """
    TODO:
    public sub
    ...
    """
    setmesstext(block)
    ret=''
    nout=[]
    for a in args:
        if a in block['vars']:
            nout.append(a)
    if 'commonvars' in block:
        for a in block['commonvars']:
            if a in vars:
                if a not in nout:
                    nout.append(a)
            else:
                errmess('vars2fortran: Confused?!: "%s" is not defined in vars.\n'%a)
    if 'varnames' in block:
        nout.extend(block['varnames'])
    if not as_interface:
        for a in list(vars.keys()):
            if a not in nout:
                nout.append(a)
    for a in nout:
        if 'depend' in vars[a]:
            for d in vars[a]['depend']:
                if d in vars and 'depend' in vars[d] and a in vars[d]['depend']:
                    errmess('vars2fortran: Warning: cross-dependence between variables "%s" and "%s"\n'%(a, d))
        if 'externals' in block and a in block['externals']:
            if isintent_callback(vars[a]):
                ret='%s%sintent(callback) %s'%(ret, tab, a)
            ret='%s%sexternal %s'%(ret, tab, a)
            if isoptional(vars[a]):
                ret='%s%soptional %s'%(ret, tab, a)
            if a in vars and 'typespec' not in vars[a]:
                continue
            cont=1
            for b in block['body']:
                if a==b['name'] and b['block']=='function':
                    cont=0;break
            if cont:
                continue
        if a not in vars:
            show(vars)
            outmess('vars2fortran: No definition for argument "%s".\n'%a)
            continue
        if a==block['name'] and not block['block']=='function':
            continue
        if 'typespec' not in vars[a]:
            if 'attrspec' in vars[a] and 'external' in vars[a]['attrspec']:
                if a in args:
                    ret='%s%sexternal %s'%(ret, tab, a)
                continue
            show(vars[a])
            outmess('vars2fortran: No typespec for argument "%s".\n'%a)
            continue
        vardef=vars[a]['typespec']
        if vardef=='type' and 'typename' in vars[a]:
            vardef='%s(%s)'%(vardef, vars[a]['typename'])
        selector={}
        if 'kindselector' in vars[a]:
            selector=vars[a]['kindselector']
        elif 'charselector' in vars[a]:
            selector=vars[a]['charselector']
        if '*' in selector:
            if selector['*'] in ['*', ':']:
                vardef='%s*(%s)'%(vardef, selector['*'])
            else:
                vardef='%s*%s'%(vardef, selector['*'])
        else:
            if 'len' in selector:
                vardef='%s(len=%s'%(vardef, selector['len'])
                if 'kind' in selector:
                    vardef='%s,kind=%s)'%(vardef, selector['kind'])
                else:
                    vardef='%s)'%(vardef)
            elif 'kind' in selector:
                vardef='%s(kind=%s)'%(vardef, selector['kind'])
        c=' '
        if 'attrspec' in vars[a]:
            attr=[]
            for l in vars[a]['attrspec']:
                if l not in ['external']:
                    attr.append(l)
            if attr:
                vardef='%s, %s'%(vardef, ','.join(attr))
                c=','
        if 'dimension' in vars[a]:
#             if not isintent_c(vars[a]):
#                 vars[a]['dimension'].reverse()
            vardef='%s%sdimension(%s)'%(vardef, c, ','.join(vars[a]['dimension']))
            c=','
        if 'intent' in vars[a]:
            lst = true_intent_list(vars[a])
            if lst:
                vardef='%s%sintent(%s)'%(vardef, c, ','.join(lst))
            c=','
        if 'check' in vars[a]:
            vardef='%s%scheck(%s)'%(vardef, c, ','.join(vars[a]['check']))
            c=','
        if 'depend' in vars[a]:
            vardef='%s%sdepend(%s)'%(vardef, c, ','.join(vars[a]['depend']))
            c=','
        if '=' in vars[a]:
            v = vars[a]['=']
            if vars[a]['typespec'] in ['complex', 'double complex']:
                try:
                    v = eval(v)
                    v = '(%s,%s)' % (v.real, v.imag)
                except:
                    pass
            vardef='%s :: %s=%s'%(vardef, a, v)
        else:
            vardef='%s :: %s'%(vardef, a)
        ret='%s%s%s'%(ret, tab, vardef)
    return ret

def buildmodules(lst):
    cfuncs.buildcfuncs()
    outmess('Building modules...\n')
    modules, mnames, isusedby=[], [], {}
    for i in range(len(lst)):
        if '__user__' in lst[i]['name']:
            cb_rules.buildcallbacks(lst[i])
        else:
            if 'use' in lst[i]:
                for u in lst[i]['use'].keys():
                    if u not in isusedby:
                        isusedby[u]=[]
                    isusedby[u].append(lst[i]['name'])
            modules.append(lst[i])
            mnames.append(lst[i]['name'])
    ret = {}
    for i in range(len(mnames)):
        if mnames[i] in isusedby:
            outmess('\tSkipping module "%s" which is used by %s.\n'%(mnames[i], ','.join(['"%s"'%s for s in isusedby[mnames[i]]])))
        else:
            um=[]
            if 'use' in modules[i]:
                for u in modules[i]['use'].keys():
                    if u in isusedby and u in mnames:
                        um.append(modules[mnames.index(u)])
                    else:
                        outmess('\tModule "%s" uses nonexisting "%s" which will be ignored.\n'%(mnames[i], u))
            ret[mnames[i]] = {}
            dict_append(ret[mnames[i]], rules.buildmodule(modules[i], um))
    return ret

def run_main(comline_list):
    """Run f2py as if string.join(comline_list,' ') is used as a command line.
    In case of using -h flag, return None.
    """
    crackfortran.reset_global_f2py_vars()
    f2pydir=os.path.dirname(os.path.abspath(cfuncs.__file__))
    fobjhsrc = os.path.join(f2pydir, 'src', 'fortranobject.h')
    fobjcsrc = os.path.join(f2pydir, 'src', 'fortranobject.c')
    files, options=scaninputline(comline_list)
    auxfuncs.options=options
    postlist=callcrackfortran(files, options)
    isusedby={}
    for i in range(len(postlist)):
        if 'use' in postlist[i]:
            for u in postlist[i]['use'].keys():
                if u not in isusedby:
                    isusedby[u]=[]
                isusedby[u].append(postlist[i]['name'])
    for i in range(len(postlist)):
        if postlist[i]['block']=='python module' and '__user__' in postlist[i]['name']:
            if postlist[i]['name'] in isusedby:
                #if not quiet:
                outmess('Skipping Makefile build for module "%s" which is used by %s\n'%(postlist[i]['name'], ','.join(['"%s"'%s for s in isusedby[postlist[i]['name']]])))
    if 'signsfile' in options:
        if options['verbose']>1:
            outmess('Stopping. Edit the signature file and then run f2py on the signature file: ')
            outmess('%s %s\n'%(os.path.basename(sys.argv[0]), options['signsfile']))
        return
    for i in range(len(postlist)):
        if postlist[i]['block']!='python module':
            if 'python module' not in options:
                errmess('Tip: If your original code is Fortran source then you must use -m option.\n')
            raise TypeError('All blocks must be python module blocks but got %s'%(repr(postlist[i]['block'])))
    auxfuncs.debugoptions=options['debug']
    f90mod_rules.options=options
    auxfuncs.wrapfuncs=options['wrapfuncs']

    ret=buildmodules(postlist)

    for mn in ret.keys():
        dict_append(ret[mn], {'csrc':fobjcsrc,'h':fobjhsrc})
    return ret

def var2fixfortran(vars,a,fa=None,f90mode=None):
    if fa is None:
        fa = a
    if a not in vars:
        show(vars)
        outmess('var2fixfortran: No definition for argument "%s".\n'%a)
        return ''
    if 'typespec' not in vars[a]:
        show(vars[a])
        outmess('var2fixfortran: No typespec for argument "%s".\n'%a)
        return ''
    vardef=vars[a]['typespec']
    if vardef=='type' and 'typename' in vars[a]:
        vardef='%s(%s)'%(vardef, vars[a]['typename'])
    selector={}
    lk = ''
    if 'kindselector' in vars[a]:
        selector=vars[a]['kindselector']
        lk = 'kind'
    elif 'charselector' in vars[a]:
        selector=vars[a]['charselector']
        lk = 'len'
    if '*' in selector:
        if f90mode:
            if selector['*'] in ['*', ':', '(*)']:
                vardef='%s(len=*)'%(vardef)
            else:
                vardef='%s(%s=%s)'%(vardef, lk, selector['*'])
        else:
            if selector['*'] in ['*', ':']:
                vardef='%s*(%s)'%(vardef, selector['*'])
            else:
                vardef='%s*%s'%(vardef, selector['*'])
    else:
        if 'len' in selector:
            vardef='%s(len=%s'%(vardef, selector['len'])
            if 'kind' in selector:
                vardef='%s,kind=%s)'%(vardef, selector['kind'])
            else:
                vardef='%s)'%(vardef)
        elif 'kind' in selector:
            vardef='%s(kind=%s)'%(vardef, selector['kind'])

    vardef='%s %s'%(vardef, fa)
    if 'dimension' in vars[a]:
        vardef='%s(%s)'%(vardef, ','.join(vars[a]['dimension']))
    return vardef

def createsubrwrapper(rout,signature=0):
    assert issubroutine(rout)

    extra_args = []
    vars = rout['vars']
    for a in rout['args']:
        v = rout['vars'][a]
        for i, d in enumerate(v.get('dimension', [])):
            if d==':':
                dn = 'f2py_%s_d%s' % (a, i)
                dv = dict(typespec='integer', intent=['hide'])
                dv['='] = 'shape(%s, %s)' % (a, i)
                extra_args.append(dn)
                vars[dn] = dv
                v['dimension'][i] = dn
    rout['args'].extend(extra_args)
    need_interface = bool(extra_args)

    ret = ['']
    def add(line,ret=ret):
        ret[0] = '%s\n      %s'%(ret[0], line)
    name = rout['name']
    fortranname = getfortranname(rout)
    f90mode = ismoduleroutine(rout)

    args = rout['args']

    sargs = ', '.join(args)
    if f90mode:
        add('subroutine f2pywrap_%s_%s (%s)'%(rout['modulename'], name, sargs))
        if not signature:
            add('use %s, only : %s'%(rout['modulename'], fortranname))
    else:
        add('subroutine f2pywrap%s (%s)'%(name, sargs))
        if not need_interface:
            add('external %s'%(fortranname))

    if need_interface:
        for line in rout['saved_interface'].split('\n'):
            if line.lstrip().startswith('use '):
                add(line)

    dumped_args = []
    for a in args:
        if isexternal(vars[a]):
            add('external %s'%(a))
            dumped_args.append(a)
    for a in args:
        if a in dumped_args: continue
        if isscalar(vars[a]):
            add(var2fixfortran(vars, a, f90mode=f90mode))
            dumped_args.append(a)
    for a in args:
        if a in dumped_args: continue
        add(var2fixfortran(vars, a, f90mode=f90mode))

    if need_interface:
        if f90mode:
            # f90 module already defines needed interface
            pass
        else:
            add('interface')
            add(rout['saved_interface'].lstrip())
            add('end interface')

    sargs = ', '.join([a for a in args if a not in extra_args])

    if not signature:
        add('call %s(%s)'%(fortranname, sargs))
    if f90mode:
        add('end subroutine f2pywrap_%s_%s'%(rout['modulename'], name))
    else:
        add('end')
    #print '**'*10
    #print ret[0]
    #print '**'*10
    return ret[0]

def buildapi(rout):
    rout, wrap = func2subr.assubr(rout)
    args, depargs=getargs2(rout)
    capi_maps.depargs=depargs
    var=rout['vars']
    auxvars = [a for a in var.keys() if isintent_aux(var[a])]

    if ismoduleroutine(rout):
        outmess('\t\t\tConstructing wrapper function "%s.%s"...\n'%(rout['modulename'], rout['name']))
    else:
        outmess('\t\tConstructing wrapper function "%s"...\n'%(rout['name']))
    # Routine
    vrd=routsign2map(rout)
    rd=dictappend({}, vrd)
    for r in rout_rules:
        if ('_check' in r and r['_check'](rout)) or ('_check' not in r):
            ar=applyrules(r, vrd, rout)
            rd=dictappend(rd, ar)

    # Args
    nth, nthk=0, 0
    savevrd={}
    for a in args:
        vrd=sign2map(a, var[a])
        if isintent_aux(var[a]):
            _rules = aux_rules
        else:
            _rules = arg_rules
            if not isintent_hide(var[a]):
                if not isoptional(var[a]):
                    nth=nth+1
                    vrd['nth']=repr(nth)+stnd[nth%10]+' argument'
                else:
                    nthk=nthk+1
                    vrd['nth']=repr(nthk)+stnd[nthk%10]+' keyword'
            else: vrd['nth']='hidden'
        savevrd[a]=vrd
        for r in _rules:
            if '_depend' in r:
                continue
            if ('_check' in r and r['_check'](var[a])) or ('_check' not in r):
                ar=applyrules(r, vrd, var[a])
                rd=dictappend(rd, ar)
                if '_break' in r:
                    break
    for a in depargs:
        if isintent_aux(var[a]):
            _rules = aux_rules
        else:
            _rules = arg_rules
        vrd=savevrd[a]
        for r in _rules:
            if '_depend' not in r:
                continue
            if ('_check' in r and r['_check'](var[a])) or ('_check' not in r):
                ar=applyrules(r, vrd, var[a])
                rd=dictappend(rd, ar)
                if '_break' in r:
                    break
        if 'check' in var[a]:
            for c in var[a]['check']:
                vrd['check']=c
                ar=applyrules(check_rules, vrd, var[a])
                rd=dictappend(rd, ar)
    if isinstance(rd['cleanupfrompyobj'], list):
        rd['cleanupfrompyobj'].reverse()
    if isinstance(rd['closepyobjfrom'], list):
        rd['closepyobjfrom'].reverse()
    rd['docsignature']=stripcomma(replace('#docsign##docsignopt##docsignxa#',
                                          {'docsign':rd['docsign'],
                                           'docsignopt':rd['docsignopt'],
                                           'docsignxa':rd['docsignxa']}))
    optargs=stripcomma(replace('#docsignopt##docsignxa#',
                               {'docsignxa':rd['docsignxashort'],
                                'docsignopt':rd['docsignoptshort']}
                               ))
    if optargs=='':
        rd['docsignatureshort']=stripcomma(replace('#docsign#', {'docsign':rd['docsign']}))
    else:
        rd['docsignatureshort']=replace('#docsign#[#docsignopt#]',
                                        {'docsign': rd['docsign'],
                                         'docsignopt': optargs,
                                         })
    rd['latexdocsignatureshort']=rd['docsignatureshort'].replace('_', '\\_')
    rd['latexdocsignatureshort']=rd['latexdocsignatureshort'].replace(',', ', ')
    cfs=stripcomma(replace('#callfortran##callfortranappend#', {'callfortran':rd['callfortran'],'callfortranappend':rd['callfortranappend']}))
    if len(rd['callfortranappend'])>1:
        rd['callcompaqfortran']=stripcomma(replace('#callfortran# 0,#callfortranappend#', {'callfortran':rd['callfortran'],'callfortranappend':rd['callfortranappend']}))
    else:
        rd['callcompaqfortran']=cfs
    rd['callfortran']=cfs
    if isinstance(rd['docreturn'], list):
        rd['docreturn']=stripcomma(replace('#docreturn#', {'docreturn':rd['docreturn']}))+' = '
    rd['docstrsigns']=[]
    rd['latexdocstrsigns']=[]
    for k in ['docstrreq', 'docstropt', 'docstrout', 'docstrcbs']:
        if k in rd and isinstance(rd[k], list):
            rd['docstrsigns']=rd['docstrsigns']+rd[k]
        k='latex'+k
        if k in rd and isinstance(rd[k], list):
            rd['latexdocstrsigns']=rd['latexdocstrsigns']+rd[k][0:1]+\
                                    ['\\begin{description}']+rd[k][1:]+\
                                    ['\\end{description}']

    # Workaround for Python 2.6, 2.6.1 bug: http://bugs.python.org/issue4720
    if rd['keyformat'] or rd['xaformat']:
        argformat = rd['argformat']
        if isinstance(argformat, list):
            argformat.append('|')
        else:
            assert isinstance(argformat, str), repr((argformat, type(argformat)))
            rd['argformat'] += '|'

    ar=applyrules(routine_rules, rd)
    if ismoduleroutine(rout):
        outmess('\t\t\t  %s\n'%(ar['docshort']))
    else:
        outmess('\t\t  %s\n'%(ar['docshort']))
    return ar, wrap

def buildusevars(m, r):
    ret={}
    outmess('\t\tBuilding use variable hooks for module "%s" (feature only for F90/F95)...\n'%(m['name']))
    varsmap={}
    revmap={}
    if 'map' in r:
        for k in r['map'].keys():
            if r['map'][k] in revmap:
                outmess('\t\t\tVariable "%s<=%s" is already mapped by "%s". Skipping.\n'%(r['map'][k], k, revmap[r['map'][k]]))
            else:
                revmap[r['map'][k]]=k
    if 'only' in r and r['only']:
        for v in r['map'].keys():
            if r['map'][v] in m['vars']:

                if revmap[r['map'][v]]==v:
                    varsmap[v]=r['map'][v]
                else:
                    outmess('\t\t\tIgnoring map "%s=>%s". See above.\n'%(v, r['map'][v]))
            else:
                outmess('\t\t\tNo definition for variable "%s=>%s". Skipping.\n'%(v, r['map'][v]))
    else:
        for v in m['vars'].keys():
            if v in revmap:
                varsmap[v]=revmap[v]
            else:
                varsmap[v]=v
    for v in varsmap.keys():
        ret=dictappend(ret, buildusevar(v, varsmap[v], m['vars'], m['name']))
    return ret

def equal_types(self):
    bits = typeinfo[self.NAME][3]
    types = []
    for name in _type_names:
        if name==self.NAME: continue
        if typeinfo[name][3]==bits:
            types.append(Type(name))
    return types

def flushTo(self, other_queue):
    if len(self._queue) == 0:
        pass
    elif len(self._queue) == 1:
        other_queue.add('/*' + self._queue[0][2:].rstrip() + ' */\n')
    else:
        other_queue.add('/*\n')
        LineQueue.flushTo(self, other_queue)
        other_queue.add('*/\n')
    self.clear()

def similar_words(self, word, n=20):
    scores = defaultdict(int)
    for c in self._word_to_contexts[self._key(word)]:
        for w in self._context_to_words[c]:
            if w != word:
                scores[w] += self._context_to_words[c][word] * self._context_to_words[c][w]
    return sorted(scores, key=scores.get, reverse=True)[:n]

def synonyms(self, ngram, fileid=None):
    '''
    Returns a list of synonyms for the current ngram.

    :param ngram: ngram to lookup
    :type ngram: C{string}
    :param fileid: thesaurus fileid to search in. If None, search all fileids.
    :type fileid: C{string}
    :return: If fileid is specified, list of synonyms; otherwise, list of tuples of fileids and
             lists, where inner lists contain synonyms.
    '''
    if fileid:
        return self._thesaurus[fileid][ngram].keys()
    else:
        return [(fileid, self._thesaurus[fileid][ngram].keys()) for fileid in self._fileids]

def select(self, end, **restrictions):
    edgelist = self._edgelists[end]

    # If there are no restrictions, then return all edges.
    if restrictions=={}: return iter(edgelist)

    # Find the index corresponding to the given restrictions.
    restr_keys = sorted(restrictions.keys())
    restr_keys = tuple(restr_keys)

    # If it doesn't exist, then create it.
    if restr_keys not in self._indexes:
        self._add_index(restr_keys)

    vals = tuple(restrictions[key] for key in restr_keys)
    return iter(self._indexes[restr_keys][end].get(vals, []))

def parse(self, tokens):
    """
    Parses the list of tokens subject to the projectivity constraint
    and the productions in the parser's grammar.  This uses a method
    similar to the span-concatenation algorithm defined in Eisner (1996).
    It returns the most probable parse derived from the parser's
    probabilistic dependency grammar.
    """
    self._tokens = list(tokens)
    chart = []
    for i in range(0, len(self._tokens) + 1):
        chart.append([])
        for j in range(0, len(self._tokens) + 1):
            chart[i].append(ChartCell(i,j))
            if i==j+1:
                if tokens[i-1] in self._grammar._tags:
                    for tag in self._grammar._tags[tokens[i-1]]:
                        chart[i][j].add(DependencySpan(i-1,i,i-1,[-1], [tag]))
                else:
                    print('No tag found for input token \'%s\', parse is impossible.' % tokens[i-1])
                    return []
    for i in range(1,len(self._tokens)+1):
        for j in range(i-2,-1,-1):
            for k in range(i-1,j,-1):
                for span1 in chart[k][j]._entries:
                        for span2 in chart[i][k]._entries:
                            for newspan in self.concatenate(span1, span2):
                                chart[i][j].add(newspan)
    trees = []
    max_parse = None
    max_score = 0
    for parse in chart[len(self._tokens)][0]._entries:
        conll_format = ""
        malt_format = ""
        for i in range(len(tokens)):
            malt_format += '%s\t%s\t%d\t%s\n' % (tokens[i], 'null', parse._arcs[i] + 1, 'null')
            #conll_format += '\t%d\t%s\t%s\t%s\t%s\t%s\t%d\t%s\t%s\t%s\n' % (i+1, tokens[i], tokens[i], parse._tags[i], parse._tags[i], 'null', parse._arcs[i] + 1, 'null', '-', '-')
            # Modify to comply with recent change in dependency graph such that there must be a ROOT element. 
            conll_format += '\t%d\t%s\t%s\t%s\t%s\t%s\t%d\t%s\t%s\t%s\n' % (i+1, tokens[i], tokens[i], parse._tags[i], parse._tags[i], 'null', parse._arcs[i] + 1, 'ROOT', '-', '-')
        dg = DependencyGraph(conll_format)
        score = self.compute_prob(dg)            
        trees.append((score, dg.tree()))
    trees.sort()
    return (tree for (score, tree) in trees)

def read_file(self, empty_first=True):
    if empty_first:
        self.clear()

    try:
        contents = nltk.data.load(self.filename, format='text', encoding=self.file_encoding)
        # TODO: the above can't handle zip files, but this should anyway be fixed in nltk.data.load()
    except LookupError as e:
        try:
            contents = nltk.data.load('file:' + self.filename, format='text', encoding=self.file_encoding)
        except LookupError:
            raise e
    lines = contents.splitlines()

    for line in lines:                          # example: 'n : (\\x.(<word> x), (v-or))'
                                                #     lambdacalc -^  linear logic -^
        line = line.strip()                     # remove trailing newline
        if not len(line): continue              # skip empty lines
        if line[0] == '#': continue             # skip commented out lines

        parts = line.split(' : ', 2)            # ['verb', '(\\x.(<word> x), ( subj -o f ))', '[subj]']

        glue_formulas = []
        paren_count = 0
        tuple_start = 0
        tuple_comma = 0

        relationships = None

        if len(parts) > 1:
            for (i, c) in enumerate(parts[1]):
                if c == '(':
                    if paren_count == 0:             # if it's the first '(' of a tuple
                        tuple_start = i+1           # then save the index
                    paren_count += 1
                elif c == ')':
                    paren_count -= 1
                    if paren_count == 0:             # if it's the last ')' of a tuple
                        meaning_term =  parts[1][tuple_start:tuple_comma]   # '\\x.(<word> x)'
                        glue_term =     parts[1][tuple_comma+1:i]           # '(v-r)'
                        glue_formulas.append([meaning_term, glue_term])     # add the GlueFormula to the list
                elif c == ',':
                    if paren_count == 1:             # if it's a comma separating the parts of the tuple
                        tuple_comma = i             # then save the index
                elif c == '#':                      # skip comments at the ends of lines
                    if paren_count != 0:             # if the line hasn't parsed correctly so far
                        raise RuntimeError('Formula syntax is incorrect for entry ' + line)
                    break                           # break to the next line

        if len(parts) > 2:                      #if there is a relationship entry at the end
            rel_start = parts[2].index('[')+1
            rel_end   = parts[2].index(']')
            if rel_start == rel_end:
                relationships = frozenset()
            else:
                relationships = frozenset(r.strip() for r in parts[2][rel_start:rel_end].split(','))

        try:
            start_inheritance = parts[0].index('(')
            end_inheritance = parts[0].index(')')
            sem = parts[0][:start_inheritance].strip()
            supertype = parts[0][start_inheritance+1:end_inheritance]
        except:
            sem = parts[0].strip()
            supertype = None

        if sem not in self:
            self[sem] = {}

        if relationships is None: #if not specified for a specific relationship set
            #add all relationship entries for parents
            if supertype:
                for rels in self[supertype]:
                    if rels not in self[sem]:
                        self[sem][rels] = []
                    glue = self[supertype][rels]
                    self[sem][rels].extend(glue)
                    self[sem][rels].extend(glue_formulas) # add the glue formulas to every rel entry
            else:
                if None not in self[sem]:
                    self[sem][None] = []
                self[sem][None].extend(glue_formulas) # add the glue formulas to every rel entry
        else:
            if relationships not in self[sem]:
                self[sem][relationships] = []
            if supertype:
                self[sem][relationships].extend(self[supertype][relationships])
            self[sem][relationships].extend(glue_formulas) # add the glue entry to the dictionary

