def _add_solids(self, X, Y, C):
    '''
    Draw the colors using :meth:`~matplotlib.axes.Axes.pcolor`;
    optionally add separators.
    '''
    ## Change to pcolorfast after fixing bugs in some backends...

    if self.extend in ["min", "both"]:
        cc = self.to_rgba([C[0][0]])
        self.extension_patch1.set_fc(cc[0])
        X, Y, C = X[1:], Y[1:], C[1:]

    if self.extend in ["max", "both"]:
        cc = self.to_rgba([C[-1][0]])
        self.extension_patch2.set_fc(cc[0])
        X, Y, C = X[:-1], Y[:-1], C[:-1]

    if self.orientation == 'vertical':
        args = (X, Y, C)
    else:
        args = (np.transpose(Y), np.transpose(X), np.transpose(C))
    kw = {'cmap':self.cmap, 'norm':self.norm,
          'shading':'flat', 'alpha':self.alpha,
          }

    del self.solids
    del self.dividers

    col = self.ax.pcolor(*args, **kw)
    self.solids = col
    if self.drawedges:
        self.dividers = collections.LineCollection(self._edges(X,Y),
                          colors=(mpl.rcParams['axes.edgecolor'],),
                          linewidths=(0.5*mpl.rcParams['axes.linewidth'],),
                          )
        self.ax.add_collection(self.dividers)
    else:
        self.dividers = None

def convert_extent(self, clob, srid):
    if clob:
        # Generally, Oracle returns a polygon for the extent -- however,
        # it can return a single point if there's only one Point in the
        # table.
        ext_geom = Geometry(clob.read(), srid)
        gtype = str(ext_geom.geom_type)
        if gtype == 'Polygon':
            # Construct the 4-tuple from the coordinates in the polygon.
            shell = ext_geom.shell
            ll, ur = shell[0][:2], shell[2][:2]
        elif gtype == 'Point':
            ll = ext_geom.coords[:2]
            ur = ll
        else:
            raise Exception('Unexpected geometry type returned for extent: %s' % gtype)
        xmin, ymin = ll
        xmax, ymax = ur
        return (xmin, ymin, xmax, ymax)
    else:
        return None

def distance(self, other):
    """
    Returns the distance between the closest points on this Geometry
    and the other. Units will be in those of the coordinate system of
    the Geometry.
    """
    if not isinstance(other, GEOSGeometry):
        raise TypeError('distance() works only on other GEOS Geometries.')
    return capi.geos_distance(self.ptr, other.ptr, byref(c_double()))

def get_default(self):
    """
    Returns the default value for this field.
    """
    if self.has_default():
        if callable(self.default):
            return self.default()
        return self.default
    if (not self.empty_strings_allowed or (self.null and
               not connection.features.interprets_empty_strings_as_nulls)):
        return None
    return ""

